"""Rotate a single character n places in the alphabet
    n is an integer
    """
def rotate_char(c: str, n: int) -> str {
    if c.islower() {
        alpha_base = ord('a');
    } elif c.isupper() {
        alpha_base = ord('A');
    } else {
        return c;
    }
    alpha_number = ord(c) - alpha_base;
    new_alpha_number = (alpha_number + n) % 26;
    return chr(alpha_base + new_alpha_number);
}

"""Return commands whose fields have pending app changes."""
def get_recommendations(
    commands_fields: list[list[str | list[str]]],
    app_pending_changes: dict[str, dict[str, str]]
) -> list[dict[str, str]] {
    recommended_cmds = [];
    for cmd in commands_fields {
        cmd_name = cmd[0];
        cmd_fields = cmd[1];
        for field in cmd_fields {
            if field in app_pending_changes {
                recommended_cmds.append(
                    {
                        'command': cmd_name,
                        'field': field,
                        'user': app_pending_changes[field]['user'],
                        'updated': app_pending_changes[field]['updated']
                    }
                );
                break;
            }
        }
    }
    return recommended_cmds;
}

