"""Write results to a text file using a name based on file_name."""
def write_file(file_name: str, data: list[tuple[str, str]], line_length: int) -> int {
    pos = file_name.rfind('.');
    fn_o = file_name[:pos] + '.OUT' + file_name[pos:];
    f = open(fn_o, "w");
    for (fsn, sequence) in data {
        f.write(fsn + '\n');
        l_length = len(sequence) if line_length == 0 else line_length;
        for p in range(0, len(sequence), l_length) {
            f.write(sequence[p:p + l_length] + '\n');
        }
    }
    f.close();
    return len(data);
}

