"""Returns living neighbors around the cell."""
def get_living_neighbors(i: int, j: int, generation: list[list[int]]) -> int {
    living_neighbors = 0;
    neighbors = [
        (i - 1, j),
        (i + 1, j),
        (i, j - 1),
        (i, j + 1),
        (i - 1, j + 1),
        (i - 1, j - 1),
        (i + 1, j + 1),
        (i + 1, j - 1)
    ];
    for (k, l) in neighbors {
        if 0 <= k < len(generation) and 0 <= l < len(generation[0]) {
            if generation[k][l] == 1 {
                living_neighbors += 1;
            }
        }
    }
    return living_neighbors;
}

"""
    Similar to keras.preprocessing.sequence.pad_sequence but using Sample as higher level
    abstraction.
    pad_func is a pad class generator.
    """
def pad_sequences(
    sequences: list[Sequence], pad_func: Callable[[], int], maxlen: int | None = None
) -> list[list[int]] {
    ret = [];
    max_value = max(map(len, sequences));
    if maxlen is None {
        maxlen = max_value;
    }
    for sequence in sequences {
        cur_seq = list(sequence[:maxlen]);
        cur_seq.extend([pad_func()] * (maxlen - len(sequence)));
        ret.append(cur_seq);
    }
    return ret;
}

