"""Construct a Postgres connection URL from credentials and optional SSL options."""
def _create_postgres_url(
    db_user: str,
    db_password: str,
    db_name: str,
    db_host: str,
    db_port: int = 5432,
    db_ssl_mode: str | None = None,
    db_root_cert: str | None = None
) -> str {
    ssl_mode = '';
    if db_ssl_mode {
        ssl_mode = '?sslmode=%s' % db_ssl_mode;
        if db_root_cert {
            ssl_mode += '&sslrootcert=%s' % db_root_cert;
        }
    }
    return (
        'postgresql://%(user)s:%(password)s@%(host)s:%(port)s/' '%(db)s%(ssl)s'
        % {
            'user': db_user,
            'password': db_password,
            'db': db_name,
            'host': db_host,
            'port': db_port,
            'ssl': ssl_mode
        }
    );
}

