"""Walks a data structure composed of nested lists/tuples/dicts, and
    creates a new (equivalent) structure in which the leaves of the data
    structure (i.e the non-list/tuple/dict data structures in the tree) have
    been mapped through f."""
def modify_leaves(f: Callable[[object], object], ds: object) -> object {
    if isinstance(ds, list) {
        return [modify_leaves(f, sds) for sds in ds];
    }
    if isinstance(ds, tuple) {
        return tuple(modify_leaves(f, sds) for sds in ds);
    }
    if isinstance(ds, dict) {
        return {k: modify_leaves(f, sds) for (k, sds) in ds.items()};
    }
    return f(ds);
}

"""
    Finds the orientation of an ordered set of vertices(p, q, r).

    p: First vertex represented as a tuple.
    q: Second vertex represented as a tuple.
    r: Third vertex represented as a tuple.

    returns:
    0 : Collinear points
    1 : Clockwise points
    2 : Counterclockwise
    """
def orientation(p: tuple[int, int], q: tuple[int, int], r: tuple[int, int]) -> int {
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1]);
    if val == 0 {
        return 0;
    }
    if val > 0 {
        return 1;
    }
    return 2;
}

"""Find root via graph mapping; nums[graph[n]] == n marks the root."""
def solution2(nums: list[int]) -> int {
    l = len(nums);
    graph: dict[int, int] = {};
    graph_size: dict[int, int] = {};
    def root_index(n: int) -> int {
        point_to_n = nums[graph[n]];
        if point_to_n == n {
            return graph[n];
        }
        return root_index(point_to_n);
    }
    max_size = 0;
    for i in range(l) {
        n = nums[i];
        if n in graph {
            continue;
        }
        root_i = i;
        if n - 1 not in graph and n + 1 not in graph {
            graph[n] = i;
        } elif n - 1 in graph and n + 1 in graph {
            root_i1 = root_index(n - 1);
            root_i2 = root_index(n + 1);
            graph[n] = root_i1;
            root_i = root_i1;
            if root_i1 != root_i2 {
                graph[nums[root_i2]] = root_i1;
                graph_size[root_i1] += graph_size[root_i2];
            }
        } else {
            n_in_graph = n - 1 if n - 1 in graph else n + 1;
            graph[n] = graph[n_in_graph];
            root_i = root_index(n);
        }
        graph_size[root_i] = (graph_size.get(root_i) or 0) + 1;
        max_size = max(max_size, graph_size[root_i]);
    }
    return max_size;
}

"""Get the number of the argument at position pos in a string without interpreting quotes."""
def _find_argument_unquoted(pos: int, text: str) -> int {
    ret = text.split();
    search = 0;
    argnum = 0;
    for (i, elem) in enumerate(ret) {
        elem_start = text.find(elem, search);
        elem_end = elem_start + len(elem);
        search = elem_end;
        if elem_start <= pos < elem_end {
            return i;
        }
        argnum = i;
    }
    return argnum + 1;
}

