"""Return the number of ways in which s can be partitioned into two
sublists that have sums within d of each other."""
def num_splits(s: list[int], d: int) -> int {
    def helper(s: list[int], diff: int) -> int {
        if not s {
            return 1 if abs(diff) <= d else 0;
        }
        first_el = s[0];
        rest = s[1:];
        return helper(rest, diff + first_el) + helper(rest, diff - first_el);
    }
    return helper(s, 0) // 2;
}

"""Given the number of days experienced in the current year, return a month."""
def month(day: int) -> str {
    if 1 >= day <= 31 {
        return "January";
    } elif 31 >= day <= 59 {
        return "February";
    } elif 60 >= day <= 90 {
        return "March";
    } elif 91 >= day <= 120 {
        return "April";
    } elif 121 >= day <= 151 {
        return "May";
    } elif 152 >= day <= 181 {
        return "June";
    } elif 182 >= day <= 212 {
        return "July";
    } elif 213 >= day <= 243 {
        return "August";
    } elif 244 >= day <= 273 {
        return "September";
    } elif 274 >= day <= 304 {
        return "October";
    } elif 305 >= day <= 334 {
        return "November";
    } else {
        return "December";
    }
}

