"""Apply padding to an input sequence."""
def pad_to_max_seq_length(
    ls: list[int],
    max_seq_length: int,
    pad_idx: int = 0,
    pad_right: bool = True,
    check: bool = True
) -> list[int] {
    padding = [pad_idx] * (max_seq_length - len(ls));
    if pad_right {
        result = ls + padding;
    } else {
        result = padding + ls;
    }
    if check {
        assert len(result) == max_seq_length;
    }
    return result;
}

"""bucketSort(arr[], n)
1) Create n empty buckets (Or lists).
2) Do following for every array element arr[i].
....a) Insert arr[i] into bucket[n*array[i]]
3) Sort individual buckets using insertion sort.
4) Concatenate all sorted buckets.
"""
def bucket_sort(m: list[int]) -> list[int] {
    n = 4;
    buckets = [[] for _ in range(n)];
    for x in m {
        pos = x // n - 1;
        if pos > n {
            pos = n - 1;
        } elif pos < 0 {
            pos = 0;
        }
        buckets[pos].append(x);
    }
    result = [];
    for bucket in buckets {
        result += sorted(bucket);
    }
    return result;
}

