"""
    Given a data_structure return the *first* value of the key from the first dict
    example:
        data_structure: [ { "id": 1, "name": "name1" }, { "id": 2, "name": "name2"} ]
        key: "id"
        return 1
    """
def get_value_for_key_from_json(key: str, data_structure: list | dict) -> int | str | float | bool | list | dict | None {
    if type(data_structure) == list {
        for v in data_structure {
            r = get_value_for_key_from_json(key, v);
            if r is not None {
                return r;
            }
        }
        return None;
    } elif type(data_structure) == dict {
        if key in data_structure {
            return data_structure[key];
        }
        for k in data_structure {
            v = data_structure[k];
            r = get_value_for_key_from_json(key, v);
            if r is not None {
                return r;
            }
        }
    }
    return None;
}

"""Convert integer to byte array in big endian format."""
def int_to_bytes(number: int) -> bytes {
    return number.to_bytes((number.bit_length() + 7) // 8, byteorder='big');
}

"""Decode dict."""
def decode_dict(d: dict[bytes, bytes | dict]) -> dict[str, str | dict] {
    result = {};
    for (key, value) in d.items() {
        if isinstance(key, bytes) {
            key = key.decode();
        }
        if isinstance(value, bytes) {
            result.update({key: value.decode()});
        } elif isinstance(value, dict) {
            result.update({key: decode_dict(value)});
        } else {
            result.update({key: value});
        }
    }
    return result;
}

"""max_pairwise_product gets the two biggest numbers and returns the product of them
TimeComplexity: O(n)
"""
def max_pairwise_product(numbers: list[int]) -> int {
    biggest = -9999999999999;
    second_bigest = -9999999999999;
    for ele in numbers {
        if ele > biggest {
            (biggest, second_bigest) = (ele, biggest);
        } elif ele > second_bigest {
            second_bigest = ele;
        }
    }
    return biggest * second_bigest;
}

