"""Calculates the FFT size as a power of two greater than or equal to
    the number of samples in a single window length.

    Having an FFT less than the window length loses precision by dropping
    many of the samples; a longer FFT than the window allows zero-padding
    of the FFT buffer which is neutral in terms of frequency domain conversion.
    """
def calculate_nfft(samplerate: int | float, winlen: int | float) -> int {
    window_length_samples = winlen * samplerate;
    nfft = 1;
    while nfft < window_length_samples {
        nfft *= 2;
    }
    return nfft;
}

"""Turn stringified cubehelix params into args/kwargs."""
def _parse_cubehelix_args(argstr: str) -> tuple[list[float], dict[str, float | bool]] {
    if argstr.startswith("ch:") {
        argstr = argstr[3:];
    }
    if argstr.endswith("_r") {
        reverse = True;
        argstr = argstr[:-2];
    } else {
        reverse = False;
    }
    if not argstr {
        return ([], {"reverse": reverse});
    }
    all_args = argstr.split(",");
    args = [float(a.strip(" ")) for a in all_args if "=" not in a];
    kwargs_list = [a.split("=") for a in all_args if "=" in a];
    kwargs: dict[str, float] = {};
    for pair in kwargs_list {
        kwargs[pair[0].strip(" ")] = float(pair[1].strip(" "));
    }
    kwarg_map = {
        "s": "start",
        "r": "rot",
        "g": "gamma",
        "h": "hue",
        "l": "light",
        "d": "dark"
    };
    mapped_kwargs: dict[str, float] = {};
    for (k, v) in kwargs.items() {
        mapped_kwargs[kwarg_map.get(k, k)] = v;
    }
    kwargs = mapped_kwargs;
    if reverse {
        kwargs["reverse"] = True;
    }
    return (args, kwargs);
}

