"""
Given one dimension move (x or y), return the shorter move comparing with opposite move.
The Board is actually round, ship can move to destination by any direction.
Example: Given board size = 5, move = 3, opposite_move = -2, return -2 since abs(-2) < abs(3).
"""
def get_shorter_move(move: int, size: int) -> int {
    if move == 0 {
        return 0;
    } elif move > 0 {
        opposite_move = move - size;
    } else {
        opposite_move = move + size;
    }
    return min([move, opposite_move], key=abs);
}

"""
Takes two sets of pronoun slots and merges them such that the result is valid
for text that might follow text which resulted in either of the merged slot
sets.
"""
def merge_pnslots(pns1: dict[str, list[int | set[str]]], pns2: dict[str, list[int | set[str]]]) -> dict[str, list[int | set[str]]] {
    result = {};
    for pn in pns1 {
        if pns1[pn][1] == pns2[pn][1] {
            result[pn] = [max(pns1[pn][0], pns2[pn][0]), set(pns1[pn][1])];
