"""Partition list around first element; return rearranged list and key index."""
def quick_one(lis: list[int]) -> tuple[list[int], int] {
    n_list = lis.copy();
    key = lis[0];
    key_i = 0;
    p_min = 0;
    p_max = len(lis) - 1;
    while p_min != p_max {
        while p_max > key_i {
            if n_list[p_max] <= key {
                (n_list[p_max], n_list[key_i]) = (n_list[key_i], n_list[p_max]);
                key_i = p_max;
                break;
            }
            p_max -= 1;
        }
        while p_min < key_i {
            if n_list[p_min] > key {
                (n_list[p_min], n_list[key_i]) = (n_list[key_i], n_list[p_min]);
                key_i = p_min;
                break;
            }
            p_min += 1;
        }
    }
    return (n_list, key_i);
}

"""
Exponential Complexity

1. it's prevalent to think about size of smaller
2. Remember that for a set of size K there are pow(2, k) cases
3. To solve this we need something like pow(2, n-1) + pow(2, n-2) + ... + pow(2, 0)
"""
def gen_subsets(L: list[int]) -> list[list[int]] {
    if len(L) == 0 {
        return [[]];
    }
    smaller = gen_subsets(L[:-1]);
    extra = L[-1:];
    new = [];
    for small in smaller {
        new.append(small + extra);
    }
    return smaller + new;
}

"""
In this algorithm, we want to find whether element x belongs to a set of numbers stored in an array numbers[]. Where l and r represent the left and right index of a sub-array in which searching operation should be performed.
"""
def maf_binary(sorted_array: list[int], value: int) -> int | None {
    min = 0;
    max = len(sorted_array) - 1;
    while min <= max {
        mid = (min + max) // 2;
        if sorted_array[mid] > value {
            max = mid - 1;
        } elif sorted_array[mid] < value {
            min = mid + 1;
        } else {
            return mid;
        }
    }
}

