"""combine intervals.

Overlapping intervals are reduced to their intersection.
"""
def getIntersections(intervals: list[tuple[float, float]]) -> list[tuple[float, float]] {
    if not intervals {
        return [];
    }
    intervals.sort();
    max_to = intervals[0][1];
    all_sections: list[list[float]] = [];
    sections: list[float] = [intervals[0][0], intervals[0][1]];
    for (this_from, this_to) in intervals[1:] {
        if this_from > max_to {
            all_sections.append(sections);
            max_to = this_to;
            sections = [];
        }
        max_to = max(max_to, this_to);
        sections.append(this_from);
        sections.append(this_to);
    }
    all_sections.append(sections);
    new_intervals: list[tuple[float, float]] = [];
    for section_group in all_sections {
        section_group.sort();
        last_x = section_group[0];
        for x in section_group[1:] {
            if last_x == x {
                continue;
            }
            new_intervals.append((last_x, x));
            last_x = x;
        }
    }
    return new_intervals;
}

"""Return list of socket files on host and containers."""
def sock_files(dev_uids_list: list[str], is_spp_pri: bool = False) -> list[dict[str, str]] {
    socks = {
        'vhost': {'host': '/tmp/sock{:s}', 'guest': '/var/run/usvhost{:s}'},
        'memif': {'host': '/tmp/spp-memif.sock', 'guest': '/var/run/spp-memif.sock'}
    };
    res = [];
    is_memif_added = False;
    for dev_uid in dev_uids_list {
        parts = dev_uid.split(':');
        if parts[0] == 'memif' and not is_memif_added {
            if is_spp_pri {
                res.append({'host': socks['memif']['host'], 'guest': socks['memif']['host']});
            } else {
                res.append({'host': socks['memif']['host'], 'guest': socks['memif']['guest']});
            }
            is_memif_added = True;
        } elif parts[0] == 'vhost' {
            if is_spp_pri {
                res.append({
                    'host': socks['vhost']['host'].format(parts[1]),
                    'guest': socks['vhost']['host'].format(parts[1])
                });
            } else {
                res.append({
                    'host': socks['vhost']['host'].format(parts[1]),
                    'guest': socks['vhost']['guest'].format(parts[1])
                });
            }
        }
    }
    return res;
}

