"""Finds if bet is in between start and end

    Arguments:
        start {Integer}
        bet {Integer}
        end {Integer}

    Returns:
        Boolean -- True if it is in between, else False
    """
def circular_between(start: int, bet: int, end: int) -> bool | None {
    if end > start {
        return bet > start and bet < end;
    } elif end < start {
        return bet > start or bet < end;
    }
}

"""Solves the calibration equation for the optimal low bound value."""
def calculate_calibrated_value(image_mean: float, vector: dict[str, float | list[list[float]]]) -> float {
    data_mean = vector['mean'][0];
    z_mean = data_mean[0] * vector['coefficient1'] + data_mean[1] * vector['coefficient2'];
    return (z_mean - image_mean * vector['coefficient1']) / vector['coefficient2'];
}

"""Recursively update a dict. """
def updater(old: dict[str, object], new: dict[str, object]) -> dict[str, object] {
    for (k, v) in new.items() {
        if type(v) == dict {
            old[k] = updater(old.get(k, {}) as dict[str, object], v as dict[str, object]);
        } else {
            old[k] = v;
        }
    }
    return old;
}

"""
Round income to the lower 10000th
Intput:
- income
Output:
- lower 10000th of the income. Return 0 if the income
is less than 30,000 or more than 120,000
"""
def round_income(x: int) -> int {
    for y in range(30, 130, 10) {
        if x >= y * 1000 and x < (y + 10) * 1000 {
            return y * 1000;
        }
    }
    return 0;
}

"""Parse a SAS token into its components.

:param sas_token: The SAS token.
:type sas_token: str
:rtype: dict[str, str]
"""
def parse_sas_token(sas_token: str) -> dict[str, str] {
    sas_data = {};
    token = sas_token.partition(' ')[2];
    for field in token.split('&') {
        (key, value) = field.split('=', 1);
        sas_data[key.lower()] = value;
    }
    return sas_data;
}

