"""Hackerrank Problem: https://www.hackerrank.com/challenges/chocolate-feast/problem

Little Bobby buys chocolate bars, eats them, and trades wrappers for more bars.
"""
def chocolate_feast(n: int, c: int, m: int) -> int {
    candies = n // c;
    wrappers = n // c;
    while wrappers >= m {
        wrappers -= m;
        wrappers += 1;
        candies += 1;
    }
    return candies;
}

