"""
Function to (recursively) sort dictionaries used for package data. This procedure is used to ensure
that models always produce the same hash independent of the order of the keys in the dictionaries.
Sorting is done by the Python internal sorting methods depending on the data. This means sorting only
works for keys with same type and otherwise will throw a TypeError.
"""
def sort_dictionary(dictionary: dict, recursive: bool) -> dict {
    if not isinstance(dictionary, dict) {
        raise TypeError("input is not of type dict");
    }
    if not isinstance(recursive, bool) {
        raise TypeError("recursive is not of type bool");
    }
    if recursive {
        for (key, value) in dictionary.items() {
            if isinstance(value, dict) {
                dictionary[key] = sort_dictionary(value, recursive);
            }
        }
    }
    return dict(sorted(dictionary.items(), key=lambda (kv: tuple) { (kv[0], kv[1]); }));
}

"""to select a candidate node for minio install
we sort by
- amount of cpu: the node with the most cpu but least used
- amount of sru: the node with the most sru but least used
"""
def sort_minio_node_candidates(nodes: list[dict[str, dict[str, int]]]) -> list[dict[str, dict[str, int]]] {
    def key(n: dict[str, dict[str, int]]) -> tuple[int, int, int, int] {
        return (
            -n['total_resources']['cru'],
            -n['total_resources']['sru'],
            n['used_resources']['cru'],
            n['used_resources']['sru']
        );
    }
    return sorted(nodes, key=key);
}

"""Computes the weighted mean of interactions using neighbour similarities."""
def weighted_mean(interactions: list[float], similarities: list[float]) -> float | None {
    (sim_sum, interaction_sum) = (0.0, 0.0);
    for (interaction, similarity) in zip(interactions, similarities) {
        interaction_sum += similarity * interaction;
        sim_sum += similarity;
    }
    return interaction_sum / sim_sum if sim_sum > 0 else None;
}

