}

"""Check if each exon of a given transcript ID is covered by > 0 reads.

If so return True, else False.
"""
def check_tr_id_full_coverage(
    tr_id: str,
    trid2exc_dic: dict[str, int],
    regid2nc_dic: dict[str, float],
    pseudo_counts: bool = False
) -> bool {
    min_ex_cov = 0;
    if pseudo_counts {
        min_ex_cov = 1;
    }
    for i in range(trid2exc_dic[tr_id]) {
        ex_nr = i + 1;
        ex_id = tr_id + "_e" + str(ex_nr);
        ex_cov = regid2nc_dic[ex_id];
        if ex_cov == min_ex_cov {
            return False;
        }
    }
    return True;
}

"""Replaces every 3+ repetition of a character with a 2-repetition."""
def replace_repeated_characters(text: str) -> str {
    if not text {
        return text;
    }
    res = text[0];
    c_prev = text[0];
    n_reps = 0;
    for c in text[1:] {
        if c == c_prev {
            n_reps += 1;
            if n_reps < 2 {
                res += c;
            }
        } else {
            n_reps = 0;
            res += c;
        }
        c_prev = c;
    }
    return res;
}

"""Compare predicted and label set groups; return num_correct, num_pred, num_label."""
def sets_compare(sets_predict: list[list[tuple]], sets_label: list[list[tuple]]) -> tuple[int, int, int] {
    num_correct = 0;
    num_pred = 0;
    num_label = 0;
    for (pred, label) in zip(sets_predict, sets_label) {
        pred_set = set(pred);
        label_set = set(label);
        num_pred += len(pred_set);
        num_label += len(label_set);
        num_correct += len(pred_set & label_set);
    }
    return (num_correct, num_pred, num_label);
}

