"""Returns a dictionary of subsystems to their cgroup.

    Arguments:
      cgroup_info: An iterable where each item is a line of a cgroup file.

    """
def _parse_cgroup_ids(cgroup_info: list[str]) -> dict[str, str] {
    cgroup_ids = {};
    for line in cgroup_info {
        parts = line.split(':');
        if len(parts) != 3 {
            continue;
        }
        (_, subsystems, cgroup_id) = parts;
        for subsystem in subsystems.split(',') {
            cgroup_ids[subsystem] = cgroup_id;
        }
    }
    return cgroup_ids;
}

"""Return the largest digit in the number."""
def find_largest_digit(n: float) -> int | None {
    if n < 0 {
        return find_largest_digit(n * -1);
    } elif n < 10 {
        return int(n);
    } elif n % 100 > 0 and n % 10 > 0 {
        if (n % 10) * 10 >= n % 100 {
            m = (n - n % 100) / 10 + n % 10;
            return find_largest_digit(m);
        }
        m = (n - n % 10) / 10;
        return find_largest_digit(m);
    }
}

"""
Returns list of numbers from descriptive range input list.
E.g. ['12-14', '^13', '17'] is converted to [12, 14, 17].
Returns string with error message if unable to parse input.
"""
def convert_range_to_number_list(range_list: list[str]) -> list[int] | str {
    num_list = [];
    exclude_num_list = [];
    try {
        for val in range_list {
            val = val.strip(' ');
            if '^' in val {
                exclude_num_list.append(int(val[1:]));
            } elif '-' in val {
                split_list = val.split("-");
                range_min = int(split_list[0]);
                range_max = int(split_list[1]);
                num_list.extend(range(range_min, range_max + 1));
            } else {
                num_list.append(int(val));
            }
        }
    } except ValueError as exc {
        return "Parse Error: Invalid number in input param 'num_list': %s" % exc;
    }
    return [num for num in num_list if num not in exclude_num_list];
}

