"""Return all subsets of a set (power set)."""
def power_set(arr: list[int]) -> list[list[int]] {
    if len(arr) == 0 {
        return [[]];
    }
    (head, tail) = (arr[0], arr[1:]);
    tail_subsets = power_set(tail);
    head_subsets = [];
    for sub in tail_subsets {
        new_sub = sub[:];
        new_sub.append(head);
        head_subsets.append(new_sub);
    }
    return tail_subsets + head_subsets;
}

"""How many edges would be needed to make v a clique."""
def count_fillin(graph: dict[int, list[int]], nodes: list[int]) -> float {
    count = 0;
    for v1 in nodes {
        for v2 in nodes {
            if v1 != v2 and v2 not in graph[v1] {
                count += 1;
            }
        }
    }
    return count / 2;
}

