"""A tuple containing x- and y- slice tuples from a string or tuple."""
def tupletupleint(
    items: str | tuple[tuple[int | float | str, int | float | str], tuple[int | float | str, int | float | str]]
) -> tuple[tuple[int, int], tuple[int, int]] {
    if isinstance(items, str) {
        for s in " ()[]" {
            items = items.replace(s, "");
        }
        (x1, x2, y1, y2) = items.split(",");
        out = ((int(float(x1)), int(float(x2))), (int(float(y1)), int(float(y2))));
    } else {
        ((x1, x2), (y1, y2)) = items;
        out = ((int(float(x1)), int(float(x2))), (int(float(y1)), int(float(y2))));
    }
    return out;
}

"""Seperates the interface input from the user into the name and number ex.
    Gi1/0/1 becomes ('Gi', '1/0/1') or GigabitEthernet1/0/1 becomes ('GigabitEthernet', '1/0/1')"""
def parse_input(input: str) -> tuple[str, str] {
    interface_name = '';
    interface_number = '';
    x = 0;
    for letter in input {
        if letter.isdigit() {
            interface_number = input[x:];
            break;
        } else {
            interface_name += letter;
        }
        x += 1;
    }
    return (interface_name.strip(' '), interface_number.strip(' '));
}

