def _parse_to_key_and_indices(key_strings: list[str]) -> list[tuple[str, list[int]]] {
    ordered_keys = [];
    for key_string in key_strings {
        key_and_indices = key_string.split("=");
        key = key_and_indices[0];
        if len(key_and_indices) > 1 {
            indices = [int(i) for i in key_and_indices[1].split(",")];
        } else {
            indices = [];
        }
        ordered_keys.append((key, indices));
    }
    return ordered_keys;
}

"""
Match the requested symbol reverse piecewise (split on ``::``) against the tag names to ensure they match exactly (modulo ambiguity).
"""
def find_url_piecewise(mapping: dict[str, str], symbol: str) -> dict[str, str] {
    piecewise_list = {};
    for (item, data) in mapping.items() {
        split_symbol = symbol.split('::');
        split_item = item.split('::');
        split_symbol.reverse();
        split_item.reverse();
        min_length = min(len(split_symbol), len(split_item));
        split_symbol = split_symbol[:min_length];
        split_item = split_item[:min_length];
        if split_symbol == split_item {
            piecewise_list[item] = data;
        }
    }
    return piecewise_list;
}

"""This function filters the test cases from list of test cases and returns
the test cases list."""
def get_scenario_name(cases: dict[str, list[dict[str, str]]]) -> tuple[dict[str, list[str]], dict[str, list[dict[str, str]]]] {
    test_cases_dict = {};
    test_cases_dict_json = {};
    for (class_name, test_case_list) in cases.items() {
        result = {class_name: []};
        for case_name_dict in test_case_list {
            (key, value) = list(case_name_dict.items())[0];
            class_names_dict = dict(
                (c_name, "") for scenario in result[class_name]
                for c_name in scenario.keys()
            );
            if key not in class_names_dict {
                result[class_name].append(case_name_dict);
            }
        }
        test_cases_dict_json.update(result);
        test_cases_list = list(
            dict((`case, "") for test_case in test_case_list for `case in test_case)
        );
        test_cases_dict.update({class_name: test_cases_list});
    }
    return (test_cases_dict, test_cases_dict_json);
}

"""Will return True or False if the given graph
        can be bipartitioned without neighboring nodes put
        into the same partition.
        Time Complexity: O(n^2)
        Space Complexity: O(n)"""
def possible_bipartition(dislikes: list[list[int]]) -> bool {
    visited = [False] * len(dislikes);
    color = [-1] * len(dislikes);
    def dfs(v: int, c: int) {
        visited[v] = True;
        color[v] = c;
        for u in dislikes[v] {
            if not visited[u] {
                dfs(u, 1 - c);
            }
        }
    }
    for i in range(len(dislikes)) {
        if not visited[i] {
            dfs(i, 0);
        }
    }
    for i in range(len(dislikes)) {
        for j in dislikes[i] {
            if color[i] == color[j] {
                return False;
            }
        }
    }
    return True;
}

