"""
Returns True if the manifest.json is a list of the form [{'k' : v}, ...],
where each member dictionary contains an object_id key.
Otherwise, returns False
"""
def is_valid_manifest(manifest_json: list[dict[str, object]], required_keys: list[str]) -> bool {
    for record in manifest_json {
        record_keys = record.keys();
        if not set(required_keys).issubset(record_keys) {
            return False;
        }
    }
    return True;
}

"""Internal Numba implementation of the Lempel-Ziv (LZ) complexity."""
def _lz_complexity(binary_string: list[int]) -> int {
    complexity = 1;
    prefix_len = 1;
    len_substring = 1;
    max_len_substring = 1;
    pointer = 0;
    while prefix_len + len_substring <= len(binary_string) {
        if binary_string[pointer + len_substring - 1] == binary_string[prefix_len + len_substring - 1] {
            len_substring += 1;
        } else {
            max_len_substring = max(len_substring, max_len_substring);
            pointer += 1;
            if pointer == prefix_len {
                complexity += 1;
                prefix_len += max_len_substring;
                pointer = 0;
                max_len_substring = 1;
            }
            len_substring = 1;
        }
    }
    if len_substring != 1 {
        complexity += 1;
    }
    return complexity;
}

"""Rearrange result_map to use typ tags as the top-level keys."""
