"""this function check the dialogue states of the json_object.
  assume both expected action and user action went through
  action standarlization, which means they must have a flight and name field.
  """
def check_states(
    user_action: dict[str, str | list[str]],
    expected_action: dict[str, str | list[str]]
) -> tuple[bool, bool, bool, bool] {
    status_match = expected_action['status'] == user_action['status'];
    user_flight = user_action['flight'] as list[str];
    expected_flight = expected_action['flight'] as list[str];
    if len(user_flight) == 0 {
        flight_match = len(expected_flight) == 0;
    } else {
        assert len(user_flight) == 1;
        flight_match = user_flight[0] in expected_flight;
    }
    name_match = (
        (expected_action['name'] as str).strip().lower()
        == (user_action['name'] as str).strip().lower()
    );
    res = status_match and flight_match and name_match;
    return (res, status_match, flight_match, name_match);
}

