"""Pad DESCRIP with dashes until required length is met."""
def pad_dscrp(in_str: str, out_len: int = 67, pad_char: str = '-') -> str {
    sz_str = len(in_str);
    if sz_str > out_len {
        out_str = in_str[:out_len];
    } elif sz_str < out_len {
        out_str = in_str + pad_char * (out_len - sz_str);
    } else {
        out_str = in_str;
    }
    return out_str;
}

"""Return precision for comparing a value with a double via WF proxy."""
def get_precision(value: int | float | str) -> int {
    sval = '%.2f' % float(value);
    last_index = len(sval);
    found_decimal = False;
    for index in range(len(sval) - 1, 0, -1) {
        char = sval[index];
        last_index = index;
        if char == '.' {
            found_decimal = True;
        }
        if char != '0' and char != '.' {
            break;
        }
    }
    if not found_decimal {
        return last_index - 1;
    }
    return last_index;
}

