"""Rename dictionary key of particular entry."""
def rename_dictionary_key(
    `entry: dict[object, object] | list[dict[object, object]] | tuple[tuple[object, object], ...],
    dict_map: dict[object, object]
) -> dict[object, object] | list[dict[object, object]] | tuple[tuple[object, object], ...] | None {
    if isinstance(`entry, dict) {
        for (old_key, new_key) in dict_map.items() {
            `entry[new_key] = `entry.pop(old_key);
        }
        return `entry;
    } elif isinstance(`entry, list) {
        return [
            dict(
                (dict_map[old_key], value) if old_key in dict_map else (old_key, value)
                for (old_key, value) in item.items()
            ) for item in `entry
        ];
    } elif isinstance(`entry, tuple) {
        return tuple(
            tuple(
                (dict_map[value[0]], value[1]) if value[0] in dict_map else value
                for value in item
            ) for item in `entry
        );
    }
    return None;
}

"""Modeled after the cubic y = (x - 1)^3 + 1."""
def cubic_ease_out(p: float) -> float {
