    offset: tuple[int, int]
) -> tuple[int, int] {
    (w, h) = size;
    (fw, fh) = fit_size;
    (x, y) = offset;
    return (x + (fw - w) // 2, y + (fh - h) // 2);
}

"""Format a range in a simple human-readable form with start, end (inclusive), and step."""
