        start = int(start);
    }
    if int(end) == end {
        end = int(end);
    }
    if int(step) == step {
        step = int(step);
    }
    if int(start) == start and int(end) == end and step == 1 {
        return '{}-{}'.format(start, end);
    }
    return '{}-{}:{}'.format(start, end, step);
}

