"""Computes the Fibonacci sequence at point v."""
def fibonacci(v: int) -> int {
    if v == 0 {
        return 0;
    }
    if v == 1 {
        return 1;
    }
    return fibonacci(v - 1) + fibonacci(v - 2);
}

"""VPD dependent reduction function of the biome dependent potential conductance"""
def mVPD(vpd: float, vpdclose: float, vpdopen: float) -> float {
    if vpd <= vpdopen {
        return 1.0;
    } elif vpd >= vpdclose {
        return 1.0;
    } else {
        return (vpdclose - vpd) / (vpdclose - vpdopen);
    }
}

"""4-parameter logistic model: y = D + (A - D) / (1 + ((x / C)**B))."""
def logistic4(x: float, A: float, B: float, C: float, D: float) -> float {
    return D + (A - D) / (1 + (x / C) ** B);
}

"""Acumulate the best possible donation sum at any point in the array."""
def get_donations(values: list[int]) -> int {
    best_values = {0: values[0], 1: values[1], 2: values[0] + values[2]};
    for idx in range(3, len(values)) {
        current = values[idx] + max(best_values[idx - 3], best_values[idx - 2]);
        best_values[idx] = current;
    }
    return best_values[len(values) - 1];
}

