"""Calculates the accuracy of a given classification predictor using the given test set."""
def __get_accuracy[T, U](
    predictor: T,
    test_set: list[list[U]],
    evaluate: Callable[[T, list[U]], U]
) -> float {
    correct_count = 0;
    for point in test_set {
        input = point[0:-1];
        output = point[-1];
        prediction = evaluate(predictor, input);
        if prediction == output {
            correct_count += 1;
        }
    }
    return correct_count / len(test_set);
}

