""" Takes input text as string; returns dictionary of markov chains.

    Dictionary has tuple as values, lists of words as keys
    """
def make_chains(text_string: str, n: int) -> dict[tuple[str, ...], list[str]] {
    chains: dict[tuple[str, ...], list[str]] = {};
    text_list = text_string.split();
    for i in range(len(text_list) - n) {
        key = tuple(text_list[i:i + n]);
        chains[key] = chains.get(key, []);
        chains[key].extend(text_list[i + n:i + 2 * n]);
    }
    return chains;
}

"""mode escape sequence code for background or foreground color
    string string to be formatted
    color used color"""
def __color(mode: int, string: str, color: int | tuple[int, int, int] | str) -> str {
    if isinstance(color, int) {
        escape = "\x1b[{0}8:5:{1}m".format(mode, color);
    } elif isinstance(color, tuple) {
        (r, g, b) = color;
        escape = "\x1b[{0}8;2;{1};{2};{3}m".format(mode, r, g, b);
    } elif isinstance(color, str) {
        if not color.startswith('#') {
            try {
                color = int(color);
                return __color(mode, string, int(color));
            } except ValueError {
                return string;
            }
        }
        r = int(color[1:3], 16);
        g = int(color[3:5], 16);
        b = int(color[5:7], 16);
        escape = "\x1b[{0}8;2;{1};{2};{3}m".format(mode, r, g, b);
    } else {
        return string;
    }
    return escape + string.replace("\x1b[0m", '') + "\x1b[0m";
}

"""Select username, password, and captcha fields with highest label probability."""
def select_login_fields(fields: dict[str, dict[str, float]]) -> tuple[str | None, str | None, str | None] {
    username_field: str | None = None;
    username_prob = 0.0;
    password_field: str | None = None;
    password_prob = 0.0;
    captcha_field: str | None = None;
    captcha_prob = 0.0;
    for (field_name, labels) in fields.items() {
        for (label, prob) in labels.items() {
            if label in ('username', 'username or email') and prob > username_prob {
                username_field = field_name;
                username_prob = prob;
            } elif label == 'password' and prob > password_prob {
                password_field = field_name;
                password_prob = prob;
            } elif label == 'captcha' and prob > captcha_prob {
                captcha_field = field_name;
                captcha_prob = prob;
            }
        }
    }
    return (username_field, password_field, captcha_field);
}

"""Convert File,Directory or [File,Directory] into string or a list of string"""
def convert_to_string(value: dict[str, str] | list[dict[str, str] | str | int | float | bool] | tuple[dict[str, str] | str | int | float | bool, ...] | str | int | float | bool) -> dict[str, str] | list[dict[str, str] | str | int | float | bool] | tuple[dict[str, str] | str | int | float | bool, ...] | str | int | float | bool {
    if type(value) is dict and (value as dict[str, str]).get("class") in ["File", "Directory"] {
        return (value as dict[str, str])["path"];
    } elif type(value) is list or type(value) is tuple {
        converted_list = [];
        for item in value {
            if type(item) is dict and (item as dict[str, str]).get("class") in ["File", "Directory"] {
                item_dict = item as dict[str, str];
                path = item_dict["path"];
                converted_list.append(path);
            } else {
                converted_list.append(item);
            }
        }
        return converted_list;
    } else {
        return value;
    }
}

