"""
    Given a list of pareto points encoded as a dictionary,  we compute a set of the same pareto points
    (aka remove duplicates) encoded as tuples ordered by the order of the keys (returned by keys() method of first item) .
    """
def computeSetOfParetoPointsTuplesFromListOfParetoPoints(
    ListOfParetoPointsAsDicts: list[dict[str, int | float]]
) -> set[tuple[int | float, ...]] {
    setOfParetoPointsTuples: set[tuple[int | float, ...]] = set();
    if len(ListOfParetoPointsAsDicts) > 0 {
        keyset = ListOfParetoPointsAsDicts[0].keys();
        for row in ListOfParetoPointsAsDicts {
            ParetoPointQualityValues = tuple(
                row[QualityAttributeKey] for QualityAttributeKey in keyset
            );
            setOfParetoPointsTuples.add(ParetoPointQualityValues);
        }
    }
    return setOfParetoPointsTuples;
}

"""Return power of 2 for highest bit set for integer"""
def maxBit(int_val: int) -> int {
    length = 0;
    count = 0;
    while int_val {
        count += int_val & 1;
        length += 1;
        int_val >>= 1;
    }
    return length - 1;
}

"""Gets the data specified by the keys in the data_list from the data_cache."""
def get_data(
    data_list: str | list[str],
    data_cache: dict[str, tuple[list[int], list[int]]]
) -> tuple[list[int], list[int]] | tuple[list[list[int]], list[list[int]]] {
    if not isinstance(data_list, list) {
        data_list = [data_list];
    }
    tmp = [data_cache[d] for d in data_list];
    if len(tmp) == 1 {
        return tmp[0];
    }
    return ([t[0] for t in tmp], [t[1] for t in tmp]);
}

