"""Return the median value of `sorted_seq`.

    >>> median ([1, 2, 2, 3, 14])
    2

    >>> median ([1, 2, 2, 3, 3, 14])
    2.5

    """
def median_s(sorted_seq: list[int | float]) -> int | float {
    length = len(sorted_seq);
    if length % 2 {
        return sorted_seq[length // 2];
    }
    mid = (length // 2) - 1;
    return (sorted_seq[mid] + sorted_seq[mid + 1]) / 2.0;
}

"""merges b into a"""
def _merge(a: dict[str, object], b: dict[str, object], path: list[str] | None = None) -> dict[str, object] {
    if path is None {
        path = [];
    }
    for (key, bv) in b.items() {
        if key in a {
            av = a[key];
            nested_path = path + [key];
            if isinstance(av, dict) and isinstance(bv, dict) {
                _merge(av, bv, nested_path);
                continue;
            }
        }
        a[key] = bv;
    }
    return a;
}

