"""Return the merged value containing the partial combined calculation."""
def merge_partial(a: int | float | dict[str, object], b: int | float | dict[str, object]) -> int | float | dict[str, object] {
    if hasattr(a, '__add__') {
        return (a + b) as int | float | dict[str, object];
    }
    a_dict = a as dict[str, object];
    b_dict = b as dict[str, object];
    for (key, val) in b_dict.items() {
        if key not in a_dict {
            a_dict[key] = val;
        } else {
            a_dict[key] = merge_partial(
                a_dict[key] as int | float | dict[str, object],
                val as int | float | dict[str, object]
            );
        }
    }
    return a_dict;
}

"""Split the string by the version:
    mypacakge<=2.4,==2.4 -> (mypacakge, <=2.4,==2.4)

    In [40]: version_split("asdsda>=2.4,==2")
    Out[40]: ('asdsda', ['>=2.4', '==2'])

    In [41]: version_split("asdsda>=2.4")
    Out[41]: ('asdsda', ['>=2.4'])

    In [42]: version_split("asdsda")
    Out[42]: ('asdsda', [])
    """
def version_split(s: str, delimiters: set[str] = {"=", ">", "<", "~"}) -> tuple[str, list[str]] {
    for (i, c) in enumerate(s) {
        if c in delimiters {
            return (s[:i], s[i:].split(","));
        }
    }
    return (s, []);
}

"""
Determine if the given graph is bipartite.

Time complexity is O(|E|)
Space complexity is O(|V|)
"""
def check_bipartite(adj_list: list[list[int]]) -> bool {
    vertices = len(adj_list);
    set_type = [-1 for v in range(vertices)];
    set_type[0] = 0;
    queue = [0];
    while queue {
        current = queue.pop(0);
        if adj_list[current][current] {
            return False;
        }
        for adjacent in range(vertices) {
            if adj_list[current][adjacent] {
                if set_type[adjacent] == set_type[current] {
                    return False;
                }
                if set_type[adjacent] == -1 {
                    set_type[adjacent] = 1 - set_type[current];
                    queue.append(adjacent);
                }
            }
        }
    }
    return True;
}

""" tint: The ternary integer for (we'll really a quaternary however
              we don't expect a z)
    """
def wc_int_to_string(tint: int) -> str {
    as_str = "";
    while tint {
        part = tint & 3;
        assert part;
        if part == 1 {
            as_str += '0';
        } elif part == 2 {
            as_str += '1';
        } else {
            assert part == 3;
            as_str += 'x';
        }
        tint >>= 2;
    }
    return as_str[::-1];
}

"""Compute the endpoints of the interval for row i."""
def _pomeranz_compute_j1j2(i: int, n: int, ll: int, ceilf: int, roundf: int) -> tuple[int, int] {
    if i == 0 {
        (j1, j2) = (-ll - ceilf - 1, ll + ceilf - 1);
    } else {
        (ip1div2, ip1mod2) = divmod(i + 1, 2);
        if ip1mod2 == 0 {
            if ip1div2 == n + 1 {
                (j1, j2) = (n - ll - ceilf - 1, n + ll + ceilf - 1);
            } else {
                (j1, j2) = (
                    ip1div2 - 1 - ll - roundf - 1,
                    ip1div2 + ll - 1 + ceilf - 1
                );
            }
        } else {
            (j1, j2) = (ip1div2 - 1 - ll - 1, ip1div2 + ll + roundf - 1);
        }
    }
    return (max(j1 + 2, 0), min(j2, n));
}

