    for line in handle {
        if line.startswith(">") {
            if current_id is not None {
                output[current_id] = ''.join(current_seq);
            }
            current_id = line[1:].strip();
            current_seq = [];
        } else {
            current_seq.append(line.strip());
        }
    }
    if current_id is not None {
        output[current_id] = ''.join(current_seq);
    }
    return output;
}

