"""Learning rate schedule optimized for huge batches."""
def noamwd_decay(
    step: int,
    warmup_steps: int,
    model_size: int,
    rate: float = 0.5,
    decay_steps: int = 1000,
    start_step: int = 500
) -> float {
    return (
        model_size ** -0.5
        * min(step ** -0.5, step * warmup_steps ** -1.5)
