"""
Matrix-vector dot product, optimized for small number of components
containing large arrays. For large numbers of components use numpy.dot
instead.
"""
def dotmv(A: list[list[float]], b: list[float], check: bool = True) -> list[float] {
    m = len(A);
    n = len(A[0]);
    if check and m * n > 64 {
        raise Exception('Too large. Use numpy.dot');
    }
    C = [];
    for j in range(m) {
        c = 0.0;
        for i in range(n) {
            c += A[j][i] * b[i];
        }
        C.append(c);
    }
    return C;
}

