"""Compute the XOR of two bytes objects."""
def xor(block_a: str | bytes, block_b: str | bytes) -> bytes {
    if isinstance(block_a, str) {
        block_a = block_a.encode();
    }
    if isinstance(block_b, str) {
        block_b = block_b.encode();
    }
    result = bytearray(block_a);
    for (index, byte) in enumerate(block_b) {
        result[index] ^= byte;
    }
    return bytes(result);
}

