"""
    Accumulative STP of logical variables is bijective.
    Given a result i (\delta_{2^n}^i), find the corresponding logical values.
    """
def inverse_map(i: int, n: int) -> list[int] {
    r = [];
    while n > 0 {
        if i % 2 == 0 {
            r.append(0);
            i = i // 2;
        } else {
            r.append(1);
            i = (i + 1) // 2;
        }
        n = n - 1;
    }
    r.reverse();
    return r;
}

