def next_field_pad(pos_prev: int, offset: int, width: int, display: bool) -> tuple[bool, int, int] {
    if not display {
        return (False, 0, pos_prev);
    }
    if offset < pos_prev or offset + width > 12 {
        next_row = True;
        padding = offset;
    } else {
        next_row = False;
        padding = offset - pos_prev;
    }
    pos_next = offset + width;
    return (next_row, padding, pos_next);
}

