"""Get SI prefix and reduced number."""
def si_prefix(
    n: float,
    prefixes: tuple[str, ...] = ("", "k", "M", "G", "T", "P", "E", "Z", "Y"),
    block: int = 1024,
    threshold: int = 1
) -> tuple[float | int, str] {
