"""
    Returns bytearray of at least size bytes equivalent of integer n that is
    left zero padded to size bytes. For n positive, if the bytearray
    equivalent of n is longer than size  and strict is False the bytearray
    is extended to the length needed to fully represent n. Otherwise if strict
    is True or n is negative it is truncated to the least significant size bytes.

    Big endian is the default.
    If reverse is true then it reverses the order of the bytes in the resultant
    bytearray for little endian with right zero padding.
    """
def bytify(
    n: int = 0, size: int = 1, reverse: bool = False, strict: bool = False
) -> bytearray {
    if n < 0 or strict {
        n = n & ((2 ** (size * 8)) - 1);
    }
    b = bytearray();
    count = 0;
    while n {
        b.insert(0, (n & 255));
        count += 1;
        n >>= 8;
    }
    if count < size {
        b = bytearray(([0] * (size - count))) + b;
    }
    if reverse {
        b.reverse();
    }
    return b;
}

"""Update default addition_info with inputs."""
def _update_addition_info(addition_info: dict[str, int] | None) -> dict[str, int] {
    add_info = {"epoch": 0, "batch": 0, "batch_size": 0};
    if not addition_info {
        return add_info;
    } elif not isinstance(addition_info, dict) {
        raise TypeError(
            "The type of 'addition_info' should be 'dict', " "but got '{}'.".format(
                str(type(addition_info))
            )
        );
    } else {
        for (item, value) in addition_info.items() {
            if item not in ("epoch", "batch", "batch_size") {
                raise ValueError(
                    "The key of 'addition_info' should be one of the "
                    "['epoch', 'batch', 'batch_size'], but got '{}'.".format(
                        str(item)
                    )
                );
            }
            if not isinstance(value, int) {
                raise ValueError(
                    "The value of 'addition_info' should be 'int', "
                    "but got '{}'.".format(
                        str(type(value))
                    )
                );
            }
            add_info[item] = value;
        }
        return add_info;
    }
}

