"""Merge dicts by key."""
def merge_dict[V](this: dict[str, V], other: dict[str, V], cb: Callable[[V, V], V]) -> dict[str, V] {
    result = {};
    result.update(this);
    result.update(other);
    for key in this.keys() & other {
        result[key] = cb(this[key], other[key]);
    }
    return result;
}

"""Fill A or B with zeros if not the same size."""
def fillIfNeeded(A: list[int], B: list[int]) -> tuple[list[int], list[int]] {
    A = list(A)[:];
    B = list(B)[:];
    if len(A) < len(B) {
        A += [0] * (len(B) - len(A));
    }
    if len(B) < len(A) {
        B += [0] * (len(A) - len(B));
    }
    return (A, B);
}

