"""Split a string at the first unquoted occurrence of a character.

Backslash quotes the next character in the head portion.
"""
def unquote_and_split(arg: str, c: str) -> tuple[str, str] {
    head = '';
    i = 0;
    while i < len(arg) {
        if arg[i] == c {
            return (head, arg[i + 1:]);
        } elif arg[i] == '\\' {
            i += 1;
            if i == len(arg) {
                return (head, '');
            }
            head += arg[i];
        } else {
            head += arg[i];
        }
        i += 1;
    }
    return (head, '');
}

"""
Return a new `sz`-sized list obtained by right padding `l` with `pd`.
If the starting list is of size `sz` or greater, no change is applyed.
"""
def pad_right_with[T](l: list[T], sz: int, pd: T) -> list[T] {
    if sz < 0 or len(l) >= sz {
        return l.copy();
    }
    return (l + sz * [pd])[:sz];
}

