"""Will take a dictionary, where *potentially* some values are lists. Will return a list of dictionaries
with no lists, where each possible list member combination is included."""
def _generateParams(param_dict: dict[str, str | int | float | list[str | int | float]]) -> list[dict[str, str | int | float | list[str | int | float]]] {
    keys = param_dict.keys();
    list_key = None;
    for key in keys {
        if isinstance(param_dict[key], list) {
            list_key = key;
            break;
        }
    }
    if list_key is None {
        return [param_dict];
    }
    new_dicts = [];
    for list_val in param_dict[list_key] {
        new_dict = {};
        for key in keys {
            if key is not list_key {
                new_dict[key] = param_dict[key];
            } else {
                new_dict[key] = list_val;
            }
        }
        new_dicts.append(new_dict);
    }
    ret = [];
    for dic in new_dicts {
        ret += _generateParams(dic);
    }
    return ret;
}

"""Provide a dictionary remapping original read indexes to new indexes.

When re-ordering the header, the individual read identifiers need to be
updated as well.
"""
def _id_remapper(orig: list[tuple[str, int]], new: list[tuple[str, int]]) -> dict[int | None, int | None] {
    new_chrom_to_index = {};
    for (i_n, (chr_n, _)) in enumerate(new) {
        new_chrom_to_index[chr_n] = i_n;
    }
    remap_indexes = {};
    for (i_o, (chr_o, _)) in enumerate(orig) {
        if chr_o in new_chrom_to_index {
            remap_indexes[i_o] = new_chrom_to_index[chr_o];
        }
    }
    remap_indexes[None] = None;
    return remap_indexes;
}

