"""functions check's user input for errors such as double operators(excluding + and -)"""
def errors(usr_input: str) -> bool {
    for (i, ch) in enumerate(usr_input) {
        if ch == "*" and usr_input[i + 1] == "*" {
            return True;
        } elif ch == "/" and usr_input[i + 1] == "/" {
            return True;
        }
    }
    if "(" in usr_input and ")" in usr_input {
        if usr_input.index(")") < usr_input.index("(") {
            return True;
        }
    }
    if usr_input.count("(") != usr_input.count(")") {
        return True;
    }
    return False;
}

"""Try to make an ASCII representation of the bytes.

Non printable characters are replaced by '?' except null character which
is replaced by '.'.
"""
def format_data_ascii(data: bytes) -> str {
    msg_str = '';
    for byte in data {
        char = chr(byte);
        if char == '\0' {
            msg_str = msg_str + '.';
        } elif ord(char) < 32 or ord(char) > 126 {
            msg_str = msg_str + '?';
        } else {
            msg_str = msg_str + char;
        }
    }
    return msg_str;
}

"""Memory usage of parity check matrix in vector space elements."""
def _mem_matrix(n: int, k: int, r: int) -> int {
