"""Find video resolution"""
def find_res(line: str) -> str | None {
    lines = [
        le.rstrip()
        for le in line.split()
        if not le.startswith("(") and not le.endswith(")")
    ];
    lines = [
        le
        for le in lines
        if not le.startswith("[") and not le.endswith("]")
    ];
    res = None;
    for le in lines {
        if le.endswith("p") {
            res = le;
            break;
        }
    }
    return res;
}

"""Prepare a given set of results and return a dict structure that
contains, for each size of words, a dict structure that contains,
for each number of states, a list of words that have this size and
this number of states."""
def prepare_results(results: list[tuple[str, int]]) -> dict[int, dict[int, list[str]]] {
    words: dict[int, dict[int, list[str]]] = dict();
    for (word, size) in results {
        length = len(word);
        number_of_states = words.setdefault(length, dict());
        list_of_words = number_of_states.setdefault(size, []);
        if word not in list_of_words {
            list_of_words.append(word);
        }
    }
    return words;
}

"""Calculate the D-efficiency bound of an array extension."""
def DefficiencyBound(D: float, k: int, k2: int) -> float {
    m = 1.0 + k + (k * (k - 1)) / 2;
    m2 = 1.0 + k2 + (k2 * (k2 - 1)) / 2;
    return D ** (m / m2);
}

