"""
Finds the automatic weighting used between classes of test, e.g., a
"top level" Bonferroni correction, or no correction, etc.
"""
def compute_auto_betweenclass_weighting(
    tests: list[str],
    betweenclass_weighting: bool = True
) -> dict[str, float | int] {
    if betweenclass_weighting {
        return {`test: 1 / len(tests) for `test in tests};
    }
    return {`test: 1 for `test in tests};
}

"""Combine the image paths from `center`, `left` and `right` using the correction factor `correction`
Returns ([image_paths], [measurements])
"""
def combine_images(
    center: list[str],
    left: list[str],
    right: list[str],
    measurement: list[int | float],
    correction: int | float
) -> tuple[list[str], list[int | float]] {
    image_paths = [];
    image_paths.extend(center);
    image_paths.extend(left);
    image_paths.extend(right);
    measurements = [];
    measurements.extend(measurement);
    measurements.extend([(x + correction) for x in measurement]);
    measurements.extend([(x - correction) for x in measurement]);
    return (image_paths, measurements);
}

"""Find start date from participants, host logins, and repository cache."""
def get_start_date(
    participants: list[dict[str, str]],
    host_dict: dict[str, str],
    repo_dates: dict[str, str],
    repo: str
) -> str {
    if repo not in repo_dates {
        for user in participants {
            try {
                cur_username = user["login"];
            } except (TypeError, KeyError) {
                continue;
            }
            if cur_username in host_dict {
                start_date = host_dict[cur_username];
                repo_dates[repo] = start_date;
                return start_date;
            }
        }
        return "unknown";
    }
    return repo_dates[repo];
}

