"""Get infinitive form of a conjugated Spanish verb, or None if not found."""
def infinitve(conjugate: str, infinitive_map: dict[tuple[str, ...], str]) -> str | None {
    conjugate = conjugate.lower();
    for word_list in infinitive_map {
        if conjugate in word_list {
            infinitive = infinitive_map[word_list];
            return infinitive if infinitive else None;
        }
    }
    return None;
}

"""
  sq: a number that is the square of an integer (perfect square)
  return: -1 if sq is not a perfect square and the square of the square root of sq + 1 if
  sq is a perfect square
  """
def find_next_perfect_square(sq: int | float) -> int {
    if sq ** 0.5 * 10 == int(sq ** 0.5) * 10 {
        return int((sq ** 0.5 + 1) ** 2);
    }
    return -1;
}

"""
    Calculates the intensity of a given cell in the stellar surface using a
    square-root limb-darkening law.
    """
def square_root(mu: float, c: list[float], i0: float = 1.0) -> float {
    (c1, c2) = c;
    attenuation = 1 - c1 * (1 - mu) - c2 * (1 - mu ** 0.5);
    return i0 * attenuation;
}

