def _DivideAndCeil(dividend: int, divisor: int) -> int {
    quotient = dividend // divisor;
    if dividend % divisor != 0 {
        quotient += 1;
    }
    return quotient;
}

"""Substitution for unary multioperations."""
def unary_superposition_mop_r_3(ar_1: tuple[int, int, int], mop: tuple[int, ...]) -> tuple[int, int, int] {
    dic_mop = {
        1: (0,),
        2: (1,),
        3: (0, 1),
        4: (2,),
        5: (0, 2),
        6: (1, 2),
        7: (0, 1, 2)
    };
    a = 0;
    b = 0;
    c = 0;
    if ar_1[0] != 0 {
        for x in dic_mop[ar_1[0]] {
            a = a | mop[x];
        }
    }
    if ar_1[1] != 0 {
        for x in dic_mop[ar_1[1]] {
            b = b | mop[x];
        }
    }
    if ar_1[2] != 0 {
        for x in dic_mop[ar_1[2]] {
            c = c | mop[x];
        }
    }
    return (a, b, c);
}

"""Returns a list of primes from 2 to 'upper'"""
def prime_sieve(upper: int, lower: int = 2) -> list[int] {
    if lower < 2 {
        raise ValueError("Lower bound cannot be lower than 2");
    }
    prime_list = list(range(lower, upper));
    index = 0;
    while True {
        try {
            prime = prime_list[index];
            for i in prime_list[index + 1:] {
                if i % prime == 0 {
                    prime_list.remove(i);
                }
            }
        } except IndexError {
            break;
        }
        index += 1;
    }
    return prime_list;
}

