    for (key, value) in config_schema['properties'].items() {
        if isinstance(value, dict) and 'default' in value {
            defaults[key] = value['default'];
        } elif isinstance(value, dict) and value.get('type', '') == 'object' {
            defaults[key] = _extract_default_values(value);
        }
    }
    return defaults;
}

""" Returns the max subarray of the given list of numbers.
        Returns 0 if  nums is None or an empty list.
        Time Complexity: ?
        Space Complexity: ?
    """
def max_sub_array(nums: list[int] | None) -> int {
    if nums == None {
        return 0;
    }
    if len(nums) == 0 {
        return 0;
    }
    if nums == None {
        return 0;
    }
    if len(nums) == 0 {
        return 0;
    }
    nums_size = len(nums);
    max_so_far = nums[0];
    curr_sum = 0;
    for i in range(0, nums_size) {
        curr_sum = curr_sum + nums[i];
        if curr_sum < 0 {
            curr_sum = 0;
        } elif max_so_far < curr_sum {
            max_so_far = curr_sum;
        }
    }
    for i in nums {
        if max_so_far < i {
            max_so_far = nums[i];
        }
    }
    return max_so_far;
}

"""
Computes and returns the derivative of a polynomial function. If the
derivative is 0, returns (0.0,).
"""
def compute_deriv(poly: tuple[float, ...]) -> tuple[float, ...] {
    index = 0.0;
    der = [];
    for mono in poly {
        mono_der = index * mono;
        if index > 0.0 {
            der.append(mono_der);
        }
        index += 1.0;
    }
    return tuple(der);
}

