"""Like `numpy.transposed`, but allows uneven row lengths

Uneven lengths will affect the order of the elements in the rows of the transposed lists
"""
def transposed_lists(list_of_lists: list[list[object]], `default: object = None) -> list[list[object]] {
    if `default is None or `default is [] or `default is tuple() {
        `default = [];
    } elif `default is 'None' {
        `default = [None];
    } else {
        `default = [`default];
    }
    n = len(list_of_lists);
    ms = [len(row) for row in list_of_lists];
    m = max(ms);
    ans: list[list[object]] = [];
    for j in range(m) {
        ans += [[]];
        for i in range(n) {
            if j < ms[i] {
                ans[-1] += [list_of_lists[i][j]];
            } else {
                ans[-1] += list(`default);
            }
        }
    }
    return ans;
}

"""Concatenate two environment paths avoiding repeats.

    Here `old` is the environment string before the base class initialize
    function is called and `new` is the string after the call. The new string
    will be a fixed string if it is not obtained from the current enviroment,
    or the same as the old string if obtained from the same enviroment. The aim
    here is not to append the new string if it is already contained in the old
    string so as to limit the growth of the environment string.

    Parameters
    ----------
    old : string
        Previous enviroment string.
    new : string
        New environment string.

    Returns
    -------
    ret : string
        Updated environment string.

    """
def _merge(old: str, new: str) -> str {
    if new in old {
        return old;
    }
    if not old {
        return new;
    }
    return ";".join([old, new]);
}

