"""Returns tuple of lines from the recursive list of tuples (item, [sub-items-tuples])."""
def delist[T](l: list[tuple[T, list[tuple[T, list]]]], result: list[T] | None = None) -> tuple[T, ...] {
    if not result {
        result = [];
    }
    for (line, sub) in l {
        result.append(line);
        delist(sub, result=result);
    }
    return tuple(result);
}

"""
    Convert seconds into DATE HOUR MIN SEC format.
    """
def time_format(seconds: int | float | str | None) -> str {
    if seconds is not None {
        seconds = int(seconds);
        d = seconds // (3600 * 24);
        h = seconds // 3600 % 24;
        m = seconds % 3600 // 60;
        s = seconds % 3600 % 60;
        if d > 0 {
            return '{:02d}D {:02d}H {:02d}m {:02d}s'.format(d, h, m, s);
        } elif h > 0 {
            return '{:02d}H {:02d}m {:02d}s'.format(h, m, s);
        } elif m > 0 {
            return '{:02d}m {:02d}s'.format(m, s);
        } elif s > 0 {
            return '{:02d}s'.format(s);
        }
    }
    return '-';
}

