"""If append is None, return element; otherwise extend or append element into append."""
def _AppendOrReturn(append: list[int] | None, element: list[int] | tuple[int, ...] | int | None) -> list[int] | tuple[int, ...] | int | None {
    if append is not None and element is not None {
