"""Return a string joining *terms* as reStructuredText."""
def joinTerms(
    terms: list[str],
    sep: str = ', ',
    last: str | None = None,
    sort: bool = False
) -> str {
    terms = list(terms);
    if sort {
        terms.sort();
    }
    if last is None {
        last = '';
    } else {
        last = last + ':term:`' + terms.pop() + '`';
    }
    return ':term:`' + ('`' + sep + ':term:`').join(terms) + '`' + last;
}

