""" returns a new graph = the original directed graph with all arcs reversed """
def reverse_direction(graph: dict[object, list[object]]) -> dict[object, list[object]] {
    rev = {};
    for (`node, neighbors) in graph.items() {
        for nbr in neighbors {
            if nbr in rev {
                rev[nbr].append(`node);
            } else {
                rev[nbr] = [`node];
