"""
    Returns a copy of text with the replacements applied.

    >>> replace('abc.-.', {'.': '*', '-': '<===>'})
    'abc*<===>*'
    >>> replace('Hola1 que2 ase3', {'Hola': 'Hi', 'que': 'ase', 'ase': None})
    'Hi1 ase2 3'
    """
def replace(text: str, replacements: dict[str, str | None]) -> str {
    if not replacements {
        return text;
    }
    result: list[str] = [];
    start = 0;
    while start < len(text) {
        pattern: list[str] = [];
        for char in text[start:] {
            pattern.append(char);
            try {
                new_value = replacements[''.join(pattern)];
            } except KeyError {
                ;
            } else {
                result.append(new_value or '');
                start += len(pattern);
                break;
            }
        } else {
            result.append(text[start]);
            start += 1;
        }
    }
    return ''.join(result);
}

"""
    Return the number of ways that `k` stairs can be climbed
    given that you can climb either 1 or 2 stairs at a time
    """
def climb_stairs(k: int) -> int {
    num_ways = [1];
    for idx in range(1, k + 1) {
        one_step = num_ways[idx - 1];
        two_step = num_ways[idx - 2] if idx > 1 else 0;
        num_ways.append(one_step + two_step);
    }
    return num_ways[-1];
}

