"""Improvement over binary search when the data is uniformly distributed."""
def interpolation_search(to_be_searched: list[int], searching_for: int) -> int {
    if to_be_searched {
        low = 0;
        high = len(to_be_searched) - 1;
        while low <= high
            and searching_for >= to_be_searched[low]
            and searching_for <= to_be_searched[high] {
            pos = low + int(
                (searching_for - to_be_searched[low]) * (high - low)
                / (to_be_searched[high] - to_be_searched[low])
            );
            if searching_for == to_be_searched[pos] {
                return pos;
            }
            if searching_for < to_be_searched[pos] {
                high = pos - 1;
            } else {
                low = pos + 1;
            }
        }
    }
    return -1;
}

"""Transform an integer confidence value (0-100) into a 0-10 scale string."""
def value_to_zero_ten(confidence_value: int) -> str {
    match confidence_value {
        case v if 0 <= v <= 4:
            return '0';
        case v if 5 <= v <= 14:
            return '1';
        case v if 15 <= v <= 24:
            return '2';
        case v if 25 <= v <= 34:
            return '3';
        case v if 35 <= v <= 44:
            return '4';
        case v if 45 <= v <= 54:
            return '5';
        case v if 55 <= v <= 64:
            return '6';
        case v if 65 <= v <= 74:
            return '7';
        case v if 75 <= v <= 84:
            return '8';
        case v if 85 <= v <= 94:
            return '9';
        case v if 95 <= v <= 100:
            return '10';
        case _:
            raise ValueError("Range of values out of bounds: %s" % confidence_value);
    }
}

"""Receive file size and return a list of size ranges."""
def size_splitter(size: int, part_size: int) -> list[str] {
    result: list[str] = [];
    if size == 0 {
        result.append('0-0');
        return result;
    }
    span = part_size if part_size <= size else size;
    parts = max(size // span, 1);
    x = 0;
    size = size - 1;
    for i in range(parts) {
        y = x + span - 1;
        if size - y < span {
            y = size;
        }
        result.append(f'{x}-{y}');
        x = y + 1;
    }
    return result;
}

"""Creates an axis from start to finish with divs divisions."""
