"""Returns the year, month, day of the next day. Simple version: assume every month has 30 days."""
def nextDay(year: int, month: int, day: int) -> tuple[int, int, int] {
    if day >= 30 {
        day = 1;
        month += 1;
    } else {
        day += 1;
    }
    if month > 12 {
        year += 1;
        month = 1;
    }
    return (year, month, day);
}

"""eta( r_net_day, evaporative_fraction, temperature)"""
def eta(r_net_day: float, evaporative_fraction: float, temperature: float) -> float {
    t_celsius = temperature - 273.15;
    latent = 86400.0 / ((2.501 - 0.002361 * t_celsius) * pow(10, 6));
    return r_net_day * evaporative_fraction * latent;
}

"""
    The algorithm for determining whether two lines intersect or not:
    https://www.geometrictools.com/Documentation/IntersectionLine2Circle2.pdf
    This one is the same, with visualization: http://geomalgorithms.com/a05-_intersect-1.html
    a and b are vector representation of the received edges and u is the vector from point a1 to point b1
    """
def edges_intersect(a1: list[float], a2: list[float], b1: list[float], b2: list[float]) -> bool {
    a = {'x': a2[0] - a1[0], 'y': a2[1] - a1[1]};
    b = {'x': b2[0] - b1[0], 'y': b2[1] - b1[1]};
    u = {'x': a1[0] - b1[0], 'y': a1[1] - b1[1]};
    a_dot_b = b['y'] * a['x'] - b['x'] * a['y'];
    if a_dot_b == 0 {
        return False;
    }
    b_dot_u = b['x'] * u['y'] - b['y'] * u['x'];
    a_dot_u = a['x'] * u['y'] - a['y'] * u['x'];
    ua = b_dot_u / a_dot_b;
    ub = a_dot_u / a_dot_b;
    return 0 <= ua <= 1 and 0 <= ub <= 1;
}

