"""Pads a batch of token sequences to a common length."""
def pad_batch(batch_tokens: list[list[str]]) -> tuple[list[list[str]], list[int]] {
    max_length = 0;
    for tokens in batch_tokens {
        max_length = max(max_length, len(tokens));
    }
    lengths = [];
    for tokens in batch_tokens {
        length = len(tokens);
        tokens += [""] * (max_length - length);
        lengths.append(length);
    }
    return (batch_tokens, lengths);
}

"""
    Apply formatting to each item in an iterable. Returns a list.
    Each item is made available in the format_string as the 'item' keyword argument.
    example usage: ['png','svg','pdf']|format_list_items('{0}. {item}', [1,2,3]) -> ['1. png', '2. svg', '3. pdf']
    """
def format_list_items(
    items: Iterable[object],
    format_string: str,
    *args: object,
    **kwargs: object
) -> list[str] {
    return [format_string.format(*args, item=item, **kwargs) for item in items];
}

"""Return a str containing each key and value in dict d.
Keys and values are separated by a comma. Key-value
pairs are separated by a newline character from each
other, and are sorted in ascending order by key.
For example, dict_to_str_sorted({1:2, 0:3, 10:5}) should
return "0, 3\n1, 2\n10, 5". The keys in the string must
be sorted in ascending order by key."""
def dict_to_str_sorted(d: dict[int, int]) -> str {
    pairs = [str(key) + ", " + str(value) + "\n" for (key, value) in d.items()];
    return ''.join(sorted(pairs));
}

