"""Collapse consecutive integers in a 1d array into range tuples."""
def sr(a: list[int]) -> list[tuple[int, int]] {
    r = [];
    i = 0;
    while i < len(a) {
        n = a[i];
        while i + 1 < len(a) and a[i + 1] - a[i] == 1 {
            i += 1;
        }
        if a[i] != n {
            r.append((n, a[i]));
        } else {
            r.append((n, n));
        }
        i += 1;
    }
    return r;
}

"""Reconstruct a path from a back-pointer array."""
def getPath(bp: list[int], start: int, goal: int) -> list[int] {
    current = goal;
    s = [current];
    while current != start {
        current = bp[current];
        s += [current];
    }
    return list(reversed(s));
}

"""Adds a number of spaces to the start of each line
    Doesn't add spaces to the first line, as it should already be
    fully indented"""
def add_spaces_to_lines(count: int, string: str) -> str {
    all_lines = string.splitlines(True);
    new_string = all_lines[0];
    for line in all_lines[1:] {
        new_string += " " * count + line;
    }
    return new_string;
}

"""Return the length of leading repeated characters and the first character."""
def _get_leading(o: str) -> tuple[int, str] {
    return (len(o) - len(o.lstrip(o[0])), o[0]);
}

"""
    Color a string for terminal output
    @params
        str - Required : the string to color
        color - Optional : the color to use. Default value: red. Available options: red, yellow, blue
    """
def colored(str: str, color: str = "red") -> str {
    colors = {
        "red": "\033[91m",
        "yellow": "\33[33m",
        "blue": "\33[34m",
        "green": "\33[32m"
    };
    end = "\033[0m";
    return f"{colors[color]}{str}{end}";
}

"""Removes characters that Windows doesn't allow in filenames from the specified string."""
def remove_invalid(s: str) -> str {
    s = s.replace('"', "'");
    for invalid_char in ["\\", "/", ":", "*", "?", "<", ">", "|"] {
        s = s.replace(invalid_char, "");
    }
    return s;
}

"""Compute the differences between data points in the time series of tuples (date, vt, mt)."""
def get_energy_diff(data: list[tuple]) -> list[tuple] {
    diff_data = [[d[0] for d in data[1:]]];
    for c in range(1, 3) {
        diff = [(b[c] - a[c]) for (a, b) in zip(data[:-1], data[1:])];
        diff_data.append(diff);
    }
    return list(zip(diff_data[0], diff_data[1], diff_data[2]));
}

"""Return the Hamming weight of n."""
def hammingWeight(n: int) -> int {
    num_ones = 0;
    binary_string = bin(n);
    for elem in binary_string {
        if elem == '1' {
            print(elem);
            num_ones += 1;
        }
    }
    if n == 0 {
        return 0;
    } elif n < 0 {
        return 32 - num_ones;
    } else {
        return num_ones;
    }
}

""" Returns a tuple (user, host) from the user_host string. """
def get_user_host(user_host: str) -> tuple[str | None, str] | tuple[str, ...] {
    if "@" in user_host {
        return tuple(user_host.split("@"));
    }
    return (None, user_host);
}

"""How are we going to call the underlying implementation of a
    declaration?  There are two strategies:

        - use_derived: we want to call the implementation on CPUDoubleType
          (or a similar, derived Type instance).  Because these derived
          instances deal in Tensors, not Variables (it's a completely different
          object, so it doesn't dispatch back to VariableType), code on
          this dispatch path needs to wrap/unwrap tensors.  If the
          derived implementation takes and returns tensors, the
          implementation is usually differentiable (although we also use
          the derived dispatch path for non-differentiable functions
          that we still want to dispatch on the derived Type instance;
          e.g., size())

        - use_type: we want to call the implementation on Type, because
          it is implemented concretely, and the functions it invokes will
          get dispatched back to VariableType (which will ensure that they
          are differentiable.)
    """
def dispatch_strategy(declaration: dict[str, bool | object | None]) -> str {
    if (
        declaration['abstract']
        or declaration['requires_tensor']
        or declaration['derivative'] is not None
    ) {
        return 'use_derived';
    }
    return 'use_type';
}

"""
    Expected format: `<channel_id>,<from_addr>,<api_url>;<channel_id>,<from_addr>,<api_url>;`

    Returns a tuple.
    The first item is the assumed default junebug channel which can be used as a
    default fallback for JUNEBUG_DEFAULT_CHANNEL_ID.
    The second item is the dictionary that can be passed to JUNEBUG_CHANNELS
    """
def parse_channel_info(data: str) -> tuple[str | None, dict[str, dict[str, str]]] {
    channels: dict[str, dict[str, str]] = {};
    default_channel_id: str | None = None;
    for channel in data.strip().split(';') {
        (channel_id, from_addr, api_url) = channel.split(',');
        if not default_channel_id {
            default_channel_id = channel_id.strip();
        }
        channels[channel_id.strip()] = {
            'FROM_ADDRESS': from_addr.strip(),
            'API_URL': api_url.strip()
        };
    }
    return (default_channel_id, channels);
}

"""Updates the action-value function estimate using the most recent time step."""
def update_Q(
    Qsa: float, Qsa_next: float, reward: float, alpha: float = 0.01, gamma: float = 0.9
) -> float {
    return Qsa + alpha * (reward + gamma * Qsa_next - Qsa);
}

"""
    Generates the first n Fibonacci numbers.
    Adopted from: https://docs.python.org/3/tutorial/modules.html
    """
def fibonacci(n: int) -> list[int] {
    result = [];
    (a, b) = (0, 1);
    while len(result) < n {
        result.append(b);
        (a, b) = (b, a + b);
    }
    return result;
}

"""Return the number of ways to make change for total."""
def count_change(total: int) -> int {
    def compute(sum_price: int, power: int) -> int {
        if sum_price == 0 {
            return 1;
        }
        cur_price = 1 << power;
        if sum_price < cur_price {
            return 0;
        }
        return compute(sum_price, power + 1) + compute(sum_price - cur_price, power);
    }
    return compute(total, 0);
}

"""Get a int from a token, if it fails, returns the string (PRIVATE)."""
def _gp_int(tok: str) -> int | str {
    try {
        return int(tok);
    } except ValueError {
        return str(tok);
    }
}

"""
    Gets an element in a deeply nested data structure
    """
def find(data: dict[str, object | None], value_path: str) -> object | None {
    keys = value_path.split('.');
    inner: object | None = data;
    for key in keys {
        if inner is None {
            return None;
        }
        inner = (inner as dict[str, object | None]).get(key);
    }
    return inner;
}

""" Alternative method, works by evaluating anything non-zero as True (0.000001 --> True) """
def find_next_square2(sq: float) -> int {
    sq_root = sq ** 0.5;
    return -1 if sq_root % 1 else (sq_root + 1) ** 2 as int;
}

"""Convert bytes int to int in aggregate units"""
def convert_bytes(num: int | float, suffix: str = 'B') -> str {
    for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'] {
        if abs(num) < 1024.0 {
            return "%3.1f%s%s" % (num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "%.1f%s%s" % (num, 'Yi', suffix);
}

"""Gets sort key for the given name, when sorting attribute, method, or such names."""
def name_sort_key(name: str) -> tuple[int, str] {
    if name.startswith('__') {
        if name == '__new__' {
            prefix_count = 0;
        } elif name == '__init__' {
            prefix_count = 1;
        } elif name == '__call__' {
            prefix_count = 2;
        } else {
            prefix_count = 102;
        }
    } elif name.startswith('_') {
        prefix_count = 101;
    } else {
        prefix_count = 100;
    }
    return (prefix_count, name);
}

"""Transform a dict into a string formatted as an HTML style."""
