}

"""Check if answer is correct (word overlap meets limit threshold)."""
def is_correct_answer(
    user_answer: str,
    correct_answer: str,
    limit: float,
    answer_handler: Callable[[str], str] | None = None
) -> bool {
    prepared_correct = correct_answer;
    prepared_user = user_answer;
    if answer_handler is not None {
        prepared_correct = answer_handler(correct_answer);
        prepared_user = answer_handler(user_answer);
    }
    correct_words = set(prepared_correct.split());
    user_words = set(prepared_user.split());
    intersection = correct_words.intersection(user_words);
    return len(intersection) / len(user_words) >= limit;
}

"""Return the sum of all positive integer
multiples of k less than or equal to n,
i.e. sum_multiple(k, n) = k + 2k + ... + k floor(n/k)."""
def sum_multiple(k: int, n: int) -> float {
    N = n / k;
    return k * N * (N + 1) / 2;
}

"""Calculate on-grid emissions for given electricity consumption and generation mix."""
def calc_ongrid(
    elec: int,
    mix: dict[str, int],
    tech_lut: dict[str, dict[str, int]],
    elec_types: str,
    emission_type: str
) -> int {
    emissions = 0;
    for elec_type in elec_types {
        emissions += elec * mix[elec_type] * tech_lut[elec_type][emission_type];
    }
    return emissions;
}

