"""
    Given a timezone string, convert it to a two-tuple suitable
    for a choice in a FormField.

    >>> timezone_choice('UTC')
    ('UTC', 'UTC')
    >>> timezone_choice('Australia/Sydney')
    ('Australia/Sydney', 'Sydney')
    >>> timezone_choice('America/Indiana/Indianapolis')
    ('America/Indiana/Indianapolis', 'Indianapolis (Indiana)')
    """
def timezone_choice(tzname: str, country: str | None = None) -> tuple[str, str] {
    try {
        (base, rest) = tzname.split('/', 1);
    } except ValueError {
        (base, rest) = (None, tzname);
    }
    rest = rest.replace('_', ' ');
    try {
        (mid, rest) = rest.split('/');
        if mid != base and mid != country {
            rest = '{0} ({1})'.format(rest, mid);
        }
    } except ValueError {
        ;
    }
    return (tzname, rest);
}

""" return list of candidates who need to be eliminated this round

    WARNING: doesn't deal properly with ties in support for min candidates....
    """
def find_min_cand(counts: dict[str, int]) -> str | None {
    if len(counts.keys()) == 0 {
        return None;
    }
    curmin = min(list(counts.values()));
    for k in counts.keys() {
        if counts[k] == curmin {
            return k;
        }
    }
}

"""Unify alternate spellings of unit names to a single form."""
def unify_units(dic: dict[str, str | list[str]]) -> dict[str, str | list[str]] {
    lookup = [
        ['meter', 'metre'],
        ['meters', 'metres'],
        ['Meter', 'Metre'],
        ['Meters', 'Metres'],
        ['kilometer', 'kilometre'],
        ['kilometers', 'kilometres'],
        ['Kilometer', 'Kilometre'],
        ['Kilometers', 'Kilometres']
    ];
    dic = dict(dic);
    for l in lookup {
        if not isinstance(dic['unit'], str) {
            for n in range(len(dic['unit'])) {
                if dic['unit'][n] in l {
                    dic['unit'][n] = l[0];
                }
            }
        } elif dic['unit'] in l {
            dic['unit'] = l[0];
        }
        if not isinstance(dic['units'], str) {
            for n in range(len(dic['units'])) {
                if dic['units'][n] in l {
                    dic['units'][n] = l[0];
                }
            }
        } elif dic['units'] in l {
            dic['units'] = l[0];
        }
    }
    return dic;
}

