"""Return complete fuel needed"""
def get_fuel(mass: int) -> int {
    out = 0;
    fuel = mass // 3 - 2;
    while fuel > 0 {
        out += fuel;
        fuel = fuel // 3 - 2;
    }
    return out;
}

"""Annealing learning rate by steps."""
def step_anneal(
    base_lr: float,
    global_step: int,
    anneal_rate: float = 0.98,
    anneal_interval: int = 30000,
    min_lr: float | None = None
) -> float {
    lr = base_lr * anneal_rate ** (global_step // anneal_interval);
    if min_lr is not None {
        lr = max(min_lr, lr);
    }
    return lr;
}

"""
appends the given argument to a command line such that CommandLineToArgvW will return
the argument string unchanged.
"""
def win_concat_quote(command_line: str, argument: str) -> str {
    result = (command_line + " ") if command_line else "";
    if argument {
        if len(argument.split()) == 1 {
            if '"' not in argument {
                result += argument;
                return result;
            }
        }
    }
    result += '"';
    it = 0;
    end = len(argument);
    while it < end {
        number_backslashes = 0;
        char = argument[it];
        while char == '\\' {
            it += 1;
            number_backslashes += 1;
            try {
                char = argument[it];
            } except IndexError {
                break;
            }
        }
        if it >= end {
            result += '\\' * (number_backslashes * 2);
            break;
        } elif char == '"' {
            result += '\\' * ((number_backslashes * 2) + 1);
            result += char;
        } else {
            result += '\\' * number_backslashes;
            result += char;
        }
        it += 1;
    }
    result += '"';
    return result;
}

