"""
Check buildings of unique height in each column.

Return True if buildings in all columns have unique height, False otherwise.
"""
def check_uniqueness_in_columns(board: list[str]) -> bool {
    for col_idx in range(1, len(board[0]) - 1) {
        heights = set();
        for row_idx in range(1, len(board) - 1) {
            if board[row_idx][col_idx] == '*' {
                continue;
            }
            if board[row_idx][col_idx] in heights {
                return False;
            }
            heights.add(board[row_idx][col_idx]);
        }
    }
    return True;
}

"""
    Helper that converts the semicolon delimited status values to
    a dict
    """
def status_to_dict(status_str: str) -> dict[str, str] {
    status = {};
    params = [
        param.strip()
        for param in status_str.split(";")
        if param.strip()
    ];
    for param in params {
        (key, val) = param.split(":");
        status[key] = val;
    }
    return status;
}

"""
    For some reason Prodigy was assigning the same hashes
    to every example in the data, which meant that when
    it looked at the saved annotations in the dataset to
    figure out which to exclude, it excluded all of them.

    Setting the _input_hash to the index of the candidate
    connection also makes lookup easier when we filter the
    candidates according to their annotation.
    """
def set_hashes(task: dict[str, int | str], i: int) -> dict[str, int | str] {
    task["_input_hash"] = i;
    task["_task_hash"] = -(i + 1);
    return task;
}

