"""
    Credits to https://stackoverflow.com/users/1235039/aquavitae
    Return a list of words and their indexes in a string.
"""
def spliter(line: str, _len: Callable[[str], int] = len) -> list[tuple[str, int, int]] {
    words = line.split(' ');
    running_offset = 0;
    offsets = [];
    for word in words {
        word_offset = line.index(word, running_offset);
        word_len = _len(word);
        running_offset = word_offset + word_len;
        offsets.append((word, word_offset, running_offset));
    }
    return offsets;
}

"""Convert bytes length to a human-readable version."""
def human_size(num: int | float, suffix: str = 'B') -> str {
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'] {
        if abs(num) < 1024.0 {
            return "{0:3.1f}{1!s}{2!s}".format(num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "{0:.1f}{1!s}{2!s}".format(num, 'Yi', suffix);
}

"""Removes list of base class."""
def removeBases(str: str) -> str {
    pos1 = -2;
    while pos1 < len(str) {
        pos1 = str.find(':', pos1 + 2);
        if pos1 < 0 {
            return str;
        }
        if pos1 == len(str) - 1 or str[pos1 + 1] != ':' {
            return str[:pos1];
        }
    }
    return str.strip();
}

