"""Sample n unique comparable objects from a zero-argument sampling function."""
def sample_n_unique(sampling_f: Callable[[], int | str], n: int) -> list[int | str] {
    res: list[int | str] = [];
    times_tried = 0;
    while len(res) < n and times_tried < 100 {
        candidate = sampling_f();
        if candidate not in res {
            res.append(candidate);
        } else {
            times_tried += 1;
        }
    }
    return res;
}

"""Parse a .pgpass line, splitting on ':' with backslash escaping."""
def splitPgpassLine(a: str) -> list[str] {
    b: list[str] = [];
    escape = False;
    d = '';
    for c in a {
        if not escape and c == '\\' {
            escape = True;
        } elif not escape and c == ':' {
            b.append(d);
            d = '';
        } else {
            d += c;
            escape = False;
        }
    }
    if escape {
        d += '\\';
    }
    b.append(d);
    return b;
}

