    for (idx, elt) in enumerate(ls) {
        if elt != key {
            ls[write_idx] = elt;
            write_idx += 1;
        }
    }
    while write_idx < len(ls) {
        ls[write_idx] = None;
        write_idx += 1;
    }
    return ls;
}

"""
