"""
    Extend the given list with the given element. If element is a scalar, it is
    appended to target; if element is a list, target is extended with it.
    >>> extend([1, 2], 4)
    [1, 2, 4]
    >>> extend([1, 2], (1, 2,))
    [1, 2, 1, 2]
    >>> extend([1, 2], {1: 2, 3: 4})
    [1, 2, {1: 2, 3: 4}]
    >>> extend([1, 2], [0, 1])
    [1, 2, 0, 1]

    :param target:
    :type target: list
    :param element:
    :rtype: list

    """
def extend(target: list[object], element: object) -> list[object] {
    assert isinstance(target, list);
    if isinstance(element, (list, tuple)) {
        target.extend(element);
    } else {
        target.append(element);
    }
    return target;
}

"""
Returns the value of an entity separated from its datatype ('represented by a string')
"""
def entity(ent: str) -> tuple[str, str] {
    if ent.startswith('_') {
        return (ent, 'blank_node');
    }
    if ent.startswith('"') {
        if '^^' in ent {
            (datatype, ent) = ent[::-1].split('^^', maxsplit=1);
            (datatype, ent) = (datatype[::-1], ent[::-1]);
            (datatype, ent) = (datatype[1:-1], ent[1:-1]);
            return (ent, datatype);
        }
        return (ent[1:-1], 'none');
    }
    assert ent.startswith(('http', 'file', 'urn', 'mailto'));
    return (ent, 'uri');
}

