"""Element-wise multiplication for complex numbers represented as pairs."""
def complex_multiply(x: tuple[float, float], y: tuple[float, float]) -> tuple[float, float] {
    (x_re, x_im) = x;
    (y_re, y_im) = y;
    z_re = x_re * y_re - x_im * y_im;
    z_im = x_re * y_im + x_im * y_re;
    return (z_re, z_im);
}

