"""Convert a roman numeral to integer."""
def integer(roman: str) -> int {
    symbol_value = {'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1};
    second_last_index = len(roman) - 1;
    result = 0;
    for i in range(second_last_index) {
        present_value = symbol_value[roman[i]];
        next_value = symbol_value[roman[i + 1]];
        if present_value < next_value {
            result -= present_value;
        } else {
            result += present_value;
        }
    }
    result += symbol_value[roman[-1]];
    return result;
}

"""
        Calculates very large GCD
        Uses squaring for calculating residue
        Complexity: O(log(n))
    """
def mGCD(a: int, b: int, m: int = 1) -> int {
    a1 = a % m;
    p = 1;
    b_val = float(b);
    while b_val > 0 {
        if b_val % 2 == 1 {
            p *= a1;
            p = p % m;
        }
        b_val /= 2;
        a1 = (a1 * a1) % m;
    }
    return p;
}

"""Remove AWS @-based region specification from file."""
def clean_file(f: str, config: dict[str, str]) -> str {
    (approach, rest) = f.split("://");
    (bucket_region, key) = rest.split("/", 1);
    if bucket_region.find("@") > 0 {
        (bucket, region) = bucket_region.split("@");
    } else {
        bucket = bucket_region;
    }
    if config.get("input_type") in ["http", "https"] {
        return "https://s3.amazonaws.com/%s/%s" % (bucket, key);
    }
    return "%s://%s/%s" % (approach, bucket, key);
}

"""Count the number of each nucleotide in the given DNA string."""
def get_nucleotide_count(dna: str) -> tuple[int, int, int, int] {
    (a, c, g, t) = (0, 0, 0, 0);
    for char in dna {
        val = char.upper();
        if val == 'A' {
            a += 1;
        } elif val == 'C' {
            c += 1;
        } elif val == 'G' {
            g += 1;
        } elif val == 'T' {
            t += 1;
        }
    }
    return (a, c, g, t);
}

