"""Computes expected value of transition probability according to theoretical results."""
def expected_p_t(step: int, p0: float, c_lambda: float, model_type: str) -> float {
    match model_type {
        case 'success_punished':
            e = ((2 * c_lambda) - 1) ** step * p0 + (1 - ((2 * c_lambda) - 1) ** step) / 2 if c_lambda != 0.5 else 0.5;
        case 'success_rewarded':
            e = p0;
        case 'success_punished_two_lambdas':
            e = 0;
        case 'success_rewarded_two_lambdas':
            e = 0;
        case _:
            raise Exception(f'Unexpected walk type: {model_type}');
    }
    return e;
}

"""Split the coordinate arrays into nparts. Add extra_args to each part."""
def _split_arrays(arrays: list[list[int]], extra_args: list[str], nparts: int) -> list[list[list[int] | str]] {
    size = len(arrays[0]);
    n = size // nparts;
    strides = [(i * n, (i + 1) * n) for i in range(nparts - 1)];
    strides.append((strides[-1][-1], size));
    return [[x[low:high] for x in arrays] + extra_args for (low, high) in strides];
}

