"""Computes precision, recall and f1-score from count of TP, TN and FN."""
def _compute_metrics(tp: int, fp: int, fn: int) -> dict[str, float] {
    res: dict[str, float] = {};
    res['precision'] = tp / (tp + fp);
    res['recall'] = tp / (tp + fn);
    res['f1_score'] = (2 * res['precision'] * res['recall']) / (res['precision'] + res['recall']);
    return res;
}

"""Add title to calendar[date]; create the date entry when start_time <= end_time."""
def command_add(
    date: str,
    start_time: int,
    end_time: int,
    title: str,
    calendar: dict[str, list[dict[str, int | str]]]
) -> bool {
    if start_time <= end_time {
        newevent = {"start": start_time, "end": end_time, "title": title};
        for dates in calendar.keys() {
            if dates == date {
                calendar[dates].append(newevent);
                return True;
            }
        }
        calendar[date] = [];
        calendar[date].append(newevent);
        return True;
    }
    return False;
}

