"""Integrate fx from x_min to x_max using the trapezoidal rule."""
def trapezoidal(
    f: Callable[[float], float],
    x_min: float,
    x_max: float,
    n: int = 1000
) -> float {
    h = (x_max - x_min) / n;
    jum = 0.5 * f(x_min);
    for i in range(1, n) {
        xi = x_min + h * i;
        jum = jum + f(xi);
    }
    jum = jum + 0.5 * f(x_max);
    return jum * h;
}

"""
https://stackoverflow.com/questions/480214/how-do-you-remove-duplicates-from-a-list-whilst-preserving-order
"""
def remove_dups[T](seq: list[T]) -> list[T] {
    seen = set();
    seen_add = seen.add;
    return [x for x in seq if not (x in seen or seen_add(x))];
}

"""Compute the adjusted Rand index from pair counts; helper function."""
def adjusted_rand_index_pair_counts(a: int, b: int, c: int, d: int) -> float {
    denominator = a * (b + c + 2 * d) + b * (b + d) + c * (c + d);
    if denominator != 0 {
        return float(2 * (a * d - b * c)) / float(denominator);
    }
    return 1.0;
}

