"""
Adapted from https://gist.github.com/zacharybell/8d9b1b25749fe6494511f843361bb167
Calculates the intersection-over-union of two bounding boxes.
"""
def get_iou(bboxes1: list[list[float]], bboxes2: list[list[float]]) -> list[float] {
    ious = [];
    for (bbox1, bbox2) in zip(bboxes1, bboxes2) {
        bbox1 = [float(x) for x in bbox1];
        bbox2 = [float(x) for x in bbox2];
        (x0_1, y0_1, x1_1, y1_1) = bbox1;
        (x0_2, y0_2, x1_2, y1_2) = bbox2;
        overlap_x0 = max(x0_1, x0_2);
        overlap_y0 = max(y0_1, y0_2);
        overlap_x1 = min(x1_1, x1_2);
        overlap_y1 = min(y1_1, y1_2);
        if overlap_x1 - overlap_x0 <= 0 or overlap_y1 - overlap_y0 <= 0 {
            ious.append(0);
            continue;
        }
        size_1 = (x1_1 - x0_1) * (y1_1 - y0_1);
        size_2 = (x1_2 - x0_2) * (y1_2 - y0_2);
        size_intersection = (overlap_x1 - overlap_x0) * (overlap_y1 - overlap_y0);
        size_union = (size_1 + size_2) - size_intersection;
        iou = size_intersection / size_union;
        ious.append(iou);
    }
    return ious;
}

"""encode_packet

Take an already encoded data string and encode it to a BitShuffle data
packet.
"""
def encode_packet(
    data: bytes,
    checksum: int | str,
    seqnum: int | str,
    seqmax: int | str,
    compression: str
) -> str {
    msg = (
        "This is encoded with BitShuffle, which you can download "
        + "from https://github.com/charlesdaniels/bitshuffle"
    );
    compatlevel = "1";
    encoding = "base64";
    decoded = data.decode(encoding="ascii");
    fmt = "((<<{}|{}|{}|{}|{}|{}|{}|{}>>))";
    return fmt.format(
        msg, compatlevel, encoding, compression, seqnum, seqmax, checksum, decoded
    );
}

"""
    Returns true if 'base' is an ancestor of 'name'.
    Particularly useful for checking if a given Vulkan type descends from VkDevice or VkInstance.
    """
def isAncestor(types: dict[str, dict[str, str]], name: str, base: str) -> bool {
    if name == base {
        return True;
    }
    `type = types.get(name);
    if `type is None {
        return False;
    }
    parent = `type.get('parent');
    if not parent {
        return False;
    }
    return isAncestor(types, parent, base);
}

"""Check if the board is a winner (one row or column is all zeros)."""
def is_winner(board: list[list[int]]) -> bool {
    for row in board {
        result_sum = 0;
        for val in row {
            result_sum += val;
        }
        if result_sum == 0 {
            return True;
        }
    }
    for j in range(len(board[0])) {
        result_sum = 0;
        for i in range(len(board)) {
            result_sum += board[i][j];
        }
        if result_sum == 0 {
            return True;
        }
    }
    return False;
}

