"""
>>> traverse_set({'level': {'one': 1}}, 'level', 'one', 42)
{'level': {'one': 42}}
"""
def traverse_config_set(target: dict[str, dict], *args: str | int) -> dict[str, dict] {
    (path, value) = (args[:-1], args[-1]);
    current: dict = target;
    last: dict = target;
    for level in path {
        if not level in current {
            current[level] = {"arg": None, "config": {}};
        }
        last = current[level];
        current = last["config"];
    }
    last["arg"] = value;
    return target;
}

"""Find tags '#!--' and '#--!' in each cell and remove lines in between."""
def hideCode(notebook: dict[str, list[dict[str, list[str]]]]) -> dict[str, list[dict[str, list[str]]]] {
    for (i, cell) in enumerate(notebook["cells"]) {
        istart = 0;
        istop = -1;
        for (idx, line) in enumerate(cell["source"]) {
            if "#!--" in line {
                istart = idx;
            }
            if "#--!" in line {
                istop = idx;
            }
        }
        notebook["cells"][i]["source"] = cell["source"][:istart] + cell["source"][istop + 1:];
    }
    return notebook;
}

