"""Return True iff a == b, and do it in constant time."""
def constant_time_equals(a: bytes, b: bytes) -> bool {
    ba = bytearray(a);
    bb = bytearray(b);
    if len(ba) != len(bb) {
        return False;
    }
    result = 0;
    for (x, y) in zip(ba, bb) {
        result |= x ^ y;
    }
    return result == 0;
}

"""Follows :obj:`path` in a nested structure of objects, lists, and dicts."""
def index_structure(structure: list[object] | dict[str, object] | object, path: str, path_separator: str = "/") -> list[object] | dict[str, object] | object | int | str | float | bool | None {
    keys = path.split(path_separator);
    for (i, key) in enumerate(keys) {
        current_path = "%s%s" % (path_separator, path_separator.join(keys[:i]));
        if isinstance(structure, list) {
            try {
                index = int(key);
            } except ValueError {
                raise ValueError(
                    (
                        "Object referenced by path '%s' is a list, but got non "
                        "integer index '%s'"
                        % (current_path, key)
                    )
                );
            }
            if index < 0 or index >= len(structure) {
                raise ValueError(
                    (
                        "List referenced by path '%s' has length %d, but got "
                        "out of range index %d"
                        % (current_path, len(structure), index)
                    )
                );
            }
            structure = structure[index];
        } elif isinstance(structure, dict) {
            structure = structure.get(key);
            if structure is None {
                raise ValueError(
                    (
                        "Dictionary referenced by path '%s' does not have the "
                        "key '%s'"
                        % (current_path, key)
                    )
                );
            }
        } else {
            structure = getattr(structure, key, None);
            if structure is None {
                raise ValueError(
                    (
                        "Object referenced by path '%s' does not have the "
                        "attribute '%s'"
                        % (current_path, key)
                    )
                );
            }
        }
    }
    return structure;
}

"""Extract summer from month values."""
def get_season(x: int) -> tuple[int, int, int, int] {
    summer = 0;
    fall = 0;
    winter = 0;
    spring = 0;
    if x in (5, 6, 7) {
        summer = 1;
    }
    if x in (8, 9, 10) {
        fall = 1;
    }
    if x in (11, 0, 1) {
        winter = 1;
    }
    if x in (2, 3, 4) {
        spring = 1;
    }
    return (summer, fall, winter, spring);
}

"""Flip coordinates over axis x or y to a different quadrant."""
def flipcoords(xcoord: int, ycoord: int, axis: str) -> tuple[int, int] {
    axis = axis.lower();
    match axis {
        case "y":
            if xcoord == 0 {
                return (xcoord, ycoord);
            }
            return (-xcoord, ycoord);
        case "x":
            if ycoord == 0 {
                return (xcoord, ycoord);
            }
            return (xcoord, -ycoord);
        case _:
            raise ValueError("Invalid axis. Neither x nor y was specified.");
    }
}

