"""BFS: Return visited nodes."""
def bfs_visited(`node: int, graph: dict[int, list[int]]) -> list[int] {
    queue = [`node];
    visited = [];
    while queue {
        current = queue.pop();
        queue[0:0] = [
            neighbor
            for neighbor in graph[current]
            if neighbor not in visited
        ];
        visited.append(current);
    }
    return visited;
}

"""
    maps a variables values based on old range and new range linearly
    source: https://stackoverflow.com/questions/929103/convert-a-number-range-to-another-range-maintaining-ratio
    """
def variable_mapping(
    value: float, from_low: float, from_high: float, to_low: float, to_high: float
) -> float {
    new_range = to_high - to_low;
    old_range = from_high - from_low;
    return ((value - from_low) * new_range) / old_range + to_low;
}

