        lists_out = [];
        for list_i in lists {
            list_o = [
                x
                for (i, x) in enumerate(list_i)
                if i not in indxs
            ];
            lists_out.append(list_o);
        }
    } else {
        lists_out = lists;
    }
    return list(lists_out);
}

