"""
Calculate value of alpha used in loss based on the epoch.
"""
def alpha_weight(epoch: float, T1: float, T2: float, af: float) -> float {
    if epoch < T1 {
        return 0.0;
    } elif epoch > T2 {
        return af;
    } else {
        return (epoch - T1) / (T2 - T1) * af;
    }
}

"""Move spiral down."""
def down(spiral: list[list[int]], coordinates: dict[str, int]) -> bool {
    done = True;
    while coordinates['row'] < len(spiral) {
        row = coordinates['row'];
        col = coordinates['col'];
        if row == len(spiral) - 1 and spiral[row][col] == 0 {
            spiral[row][col] = 1;
            done = False;
            break;
        } elif row + 2 <= len(spiral) - 1 and spiral[row + 2][col] == 0 and spiral[row + 1][col] == 0 {
            spiral[row][col] = 1;
            coordinates['row'] += 1;
            done = False;
        } elif row + 1 == len(spiral) - 1 and spiral[row + 1][col] == 0 {
            spiral[row][col] = 1;
            coordinates['row'] += 1;
            done = False;
        } else {
            break;
        }
    }
    return done;
}

"""Learning Rate Schedule."""
def lr_schedule(epoch: int, lr: float = 0.01) -> float {
    if epoch > 50 {
        if epoch % 10 == 9 {
            lr *= 0.0005;
        } elif 6 <= epoch % 10 < 9 {
            lr *= 0.001;
        } elif 3 <= epoch % 10 < 6 {
            lr *= 0.01;
        } elif epoch % 10 < 3 {
            lr *= 0.1;
        }
    }
    print('Learning rate: ', lr);
    return lr;
}

