"""Implement the quadratic cost function."""
def calc_construction_cost(
    levee_height_cm: float,
    height_increase_cm: float,
    construction_quadratic: float,
    construction_linear: float,
    construction_fixed: float
) -> float {
    a = construction_quadratic;
    b = construction_linear;
    c = construction_fixed;
    if height_increase_cm == 0.0 {
        cost_millions = 0.0;
    } elif height_increase_cm > 0.0 {
        new_height = levee_height_cm + height_increase_cm;
        cost_millions = a * (new_height ** 2) + b * height_increase_cm + c;
    } else {
        raise ValueError("height increase must be non-negative");
    }
    return cost_millions * 1000000.0;
}

"""
    Returns a 0-based list of integers specifying which occurrence,
    i.e. enumerated duplicate, each list item is.

    For example, if `lst` = [ 'A','B','C','C','A'] then the
    returned list will be   [  0 , 0 , 0 , 1 , 1 ].  This is useful
    when working with `DataSet` objects that have `collisionAction`
    set to "keepseparate".
    """
def compute_occurrence_indices(lst: list[str | int]) -> list[int] {
    lookup: dict[str | int, int] = {};
    ret: list[int] = [];
    for x in lst {
        if x not in lookup {
            lookup[x] = 0;
        } else {
            lookup[x] += 1;
        }
        ret.append(lookup[x]);
    }
    return ret;
}

"""Selection partition."""
def partition(array: list[int], pivot: int) -> int {
    i = -1;
    j = 0;
    while j < len(array) - 1 {
        if array[j] == pivot {
            (array[-1], array[j]) = (array[j], array[-1]);
            continue;
        } elif array[j] < pivot {
            i += 1;
            (array[i], array[j]) = (array[j], array[i]);
        }
        j += 1;
    }
    (array[-1], array[i + 1]) = (array[i + 1], array[-1]);
    return i + 1;
}

