Parameters
----------
endclasses : dict
    Dictionary of end-state classifications 'classification' and 'prob' attributes

Returns
-------
probabilities : dict
    Dictionary of probabilities of different simulation classifications
"""
def state_probabilities(endclasses: dict[str, dict[str, str | float]]) -> dict[str, float] {
    classifications = {props['classification'] for (_, props) in endclasses.items()};
    probabilities: dict[str, float] = {};
    for classif in classifications {
        probabilities[classif] = sum(
            [props['prob'] for (_, props) in endclasses.items() if classif == props['classification']]
        );
    }
    return probabilities;
}

