"""
    Round up the given value to minimize the number of prime factors.  Factors
    other than 2, 3, and 5 are not allowed, and the number of factors of 3 and
    5 cannot exceed maxprimes.
    """
def round_up_to_even(n: int, maxprimes: int = 3) -> int {
    if n % 2 != 0 {
        n += 1;
    }
    while True {
        r = n;
        n_primes = 0;
        while r > 1 and r % 2 == 0 {
            r //= 2;
        }
        while r > 1 and r % 3 == 0 {
            r //= 3;
            n_primes += 1;
        }
        while r > 1 and r % 5 == 0 {
            r //= 5;
            n_primes += 1;
        }
        if r == 1 and n_primes <= maxprimes {
            return n;
        }
        n += 2;
    }
}

"""Number contiguous elements in an array with the information of the missing indices."""
def split_and_number(strips: list[object], missing_indices: list[int]) -> list[tuple[int, object]] {
    remapped_strips: list[tuple[int, object]] = [];
    j = 0;
    missing_indices.sort();
    for strip in strips {
        if j in missing_indices {
            while j in missing_indices {
                j += 1;
            }
        }
        remapped_strips.append((j, strip));
        j += 1;
    }
    return remapped_strips;
}

"""Time complexity: O(n) because you are returning the function continuously until index equals to nth-item
    """
def linear_search_recursive(array: list[int], item: int, index: int = 0) -> int {
    if len(array) <= index {
        return index;
    }
    if array[index] == item {
        return index;
    }
    return linear_search_recursive(array, item, index + 1);
}

