    value_list = tran1[:];
    value_list.extend(tran2[:]);
    value_list = list(set(value_list));
    andcount = 1;
    xorcount = 1;
    for t in value_list {
        if t in tran1 and t in tran2 {
            andcount += 1;
        } elif t not in tran1 and t not in tran2 {
