    """
def countInversions(state: list[int | str]) -> int {
    n = len(state);
    invs = 0;
    for i in range(n - 1) {
        for j in range(i + 1, n) {
            if 'b' not in (state[i], state[j]) and state[i] > state[j] {
                invs += 1;
            }
        }
    }
    return invs;
}

"""See quatOfLaueGroup."""
def ltypeOfLaueGroup(tag: str) -> str {
    if not isinstance(tag, str) {
        raise RuntimeError("entered flag is not a string!");
    }
    lower = tag.lower();
    if lower in ('ci', 's2') {
        return 'triclinic';
    } elif lower == 'c2h' {
        return 'monoclinic';
    } elif lower in ('d2h', 'vh') {
        return 'orthorhombic';
    } elif lower in ('c4h', 'd4h') {
        return 'tetragonal';
    } elif lower in ('c3i', 's6', 'd3d') {
        return 'trigonal';
    } elif lower in ('c6h', 'd6h') {
        return 'hexagonal';
    } elif lower in ('th', 'oh') {
        return 'cubic';
    } else {
        raise RuntimeError(
            "unrecognized symmetry group.  "
            + "See ''help(quatOfLaueGroup)'' for a list of valid options.  "
            + "Oh, and have a great day ;-)"
        );
    }
}

