"""
A function to inject arguments manually into a method signature before
it's been parsed. If using keyword arguments use 'kw=type' instead in
the types array.

  sig     the string signature
  types   a list of types to be inserted

Returns the altered signature.
"""
def _inject_args(sig: str, types: list[str]) -> str {
    if '(' in sig {
        parts = sig.split('(');
        sig = '{}({}{}{}'.format(
            parts[0],
            ', '.join(types),
            ', ' if parts[1].index(')') > 0 else '',
            parts[1]
        );
    } else {
        sig = '{}({})'.format(sig, ', '.join(types));
    }
    return sig;
}

"""o(log(m)+log(n)) solution n=sizeof a ,m=sizeof b"""
def kthSmall(A: list[int], B: list[int], k: int) -> int {
    if not A {
        return B[k];
    } elif not B {
        return A[k];
    }
    ia = len(A) // 2;
    ib = len(B) // 2;
    ma = A[ia];
    mb = B[ib];
    if ia + ib < k {
        if ma > mb {
            return kthSmall(A, B[(ib + 1):], k - (ib + 1));
        }
        return kthSmall(A[(ia + 1):], B, k - (ia + 1));
    } elif ma > mb {
        return kthSmall(A[:ia], B, k);
    }
    return kthSmall(A, B[:ib], k);
}

"""check composite number for rabin-miller primality test"""
def try_composite(a: int, d: int, n: int, s: int) -> bool {
    if pow(a, d, n) == 1 {
        return False;
    }
    for i in range(s) {
        if pow(a, (2 ** i) * d, n) == n - 1 {
            return False;
        }
    }
    return True;
}

