"""Extend list with items without duplicities.

    :param list listToBeExtended: list to be extended
    :param list newItems: new items
    :return: extended list
    :rtype: list

    >>> extendListNoDuplicates([1, 2, 3, 4], [4, 5, 6])
    [1, 2, 3, 4, 5, 6]
    """
def extendListNoDuplicates[T](listToBeExtended: list[T], newItems: list[T]) -> list[T] {
    for item in newItems {
        if item not in listToBeExtended {
            listToBeExtended.append(item);
        }
    }
    return listToBeExtended;
}

"""Adds elements from aux dictionary which are not in final dictionary to it."""
def mergeDictsItems(
    final: dict[str, str | dict[str, str | dict[str, str]]],
    aux: dict[str, str | dict[str, str | dict[str, str]]]
) -> dict[str, str | dict[str, str | dict[str, str]]] {
    for key in aux.keys() {
        if key not in final {
            final[key] = aux[key];
        } elif type(final[key]) == dict {
            merged = mergeDictsItems(
                final[key] as dict[str, str | dict[str, str | dict[str, str]]],
                aux[key] as dict[str, str | dict[str, str | dict[str, str]]]
            );
            final[key] = merged as dict[str, str | dict[str, str]];
        }
    }
    return final;
}

