"""Return n'th fibonacci Number."""
def fibonacciNumber(n: int) -> int {
    if n == 0 {
        return 0;
    } elif n == 1 {
        return 1;
    } else {
        return fibonacciNumber(n - 1) + fibonacciNumber(n - 2);
    }
}

"""compute the xy coordinate given an index"""
def get_xy_coord(n: int) -> tuple[int, int] {
    if n < 1 {
        raise ValueError;
    } elif n == 1 {
        return (0, 0);
    } elif n == 2 {
        return (1, 0);
    } else {
        (x, y) = get_xy_coord(n - 1);
        if abs(x) > abs(y) {
            if x >= 0 {
                return (x, y + 1) if y < x else (x - 1, y);
            } else {
                return (x, y - 1) if y > x else (x + 1, y);
            }
        } elif y >= 0 {
            return (x - 1, y) if x > -y else (x, y - 1);
        } else {
            return (x + 1, y);
        }
    }
}

