        background_index_right (int): index in compressed depths of background right to a peak
        keys (List): The keys for the compressed depths dictionary

    Returns:
        str: A peak in start - end format that is the result of registration
    """
def register_new_peak(
    background_index_left: int,
    background_index_right: int,
    keys: list[tuple[str, str]]
) -> tuple[str, str] {
    if background_index_right - background_index_left >= 5 {
        peak = (
            keys[background_index_left + 1][0],
            keys[background_index_right - 1][1]
        );
    } else {
        peak = (keys[background_index_left][0], keys[background_index_right][1]);
    }
    return peak;
}

"""Converts n bits to a human readable format."""
def bits2human(n: int, format: str = "%(value).1f%(symbol)s") -> str {
    symbols = ('B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB', 'ZiB', 'YiB');
    prefix: dict[str, int] = {};
    prefix['B'] = 8;
    for (i, s) in enumerate(symbols[1:]) {
        prefix[s] = (1024 ** (i + 1)) * 8;
    }
    for symbol in reversed(symbols) {
        if n >= prefix[symbol] {
            value = float(n) / prefix[symbol];
            return format % locals();
        }
    }
    return format % dict(symbol=symbols[0], value=n);
}

