    for site in single_elem_environments {
        for (elem, value) in site {
            elem_len = len([val for val in site if val[0] == elem]);
            if elem not in max_num_elem {
                max_num_elem[elem] = 0;
            }
            if elem_len > max_num_elem[elem] {
                max_num_elem[elem] = elem_len;
