"""
    Problem: There are distinct integers in list `complete`. The same integers are in list `incomplete`, except for one.

    Task: Find the one integer which is missing from the incomplete list.

    Complexity: O(n) time, O(1) space
    """
def find_missing_int_using_sum(complete: list[int], incomplete: list[int]) -> int {
    s = 0;
    for (a, b) in zip(complete[:-1], incomplete) {
        s += a;
        s -= b;
    }
    return s + complete[-1];
}

"""Parse a dict of dicts to generate a list of lists describing
the fields, and an array of the corresponding data records."""
def parseData(data: dict[str, dict[str, int | str | list]]) -> tuple[list[list[str | int]], list[list[int | str | list]]] {
    fields = [];
    records = [];
    for k in list(data.keys()) {
        t = data[k]['Type'] as int;
        l = data[k]['Length'] as int;
        if t == 0 {
            nt = 'C';
            p = 0;
        } elif t == 1 {
            nt = 'N';
            p = 0;
        } elif t == 2 {
            nt = 'N';
            p = data[k]['Precision'] as int;
        } else {
            fields.append([k, t, l, 0]);
            records.append([data[k]['Data']]);
            continue;
        }
        fields.append([k, nt, l, p]);
        records.append([data[k]['Data']]);
    }
    return (fields, records);
}

