"""returns a list of the elements that are
    not in common"""
def drop_matches(list1: list[int], list2: list[int]) -> tuple[int, list[int]] {
    list1.sort();
    list2.sort();
    matches = [];
    i = 0;
    j = 0;
    len_lst1 = len(list1);
    len_lst2 = len(list2);
    while i < len_lst1 and j < len_lst2 {
        if list1[i] < list2[j] {
            matches.append(list1[i]);
            i += 1;
        } elif list1[i] > list2[j] {
            matches.append(list2[j]);
            j += 1;
        } else {
            i += 1;
            j += 1;
        }
    }
    while i < len_lst1 {
        matches.append(list1[i]);
        i += 1;
    }
    while j < len_lst2 {
        matches.append(list2[j]);
        j += 1;
    }
    return (len(matches), matches);
}

"""Get frequency weighted intersection over union."""
def get_frequency_weighted_iou(n: dict[int, dict[int, int]]) -> float {
    k = len(n[0]);
    t = [sum(n[i][j] for j in range(k)) for i in range(k)];
    a = sum(t) ** -1;
    b = sum(
        (t[i] * n[i][i]) / ((t[i] - n[i][i]) + sum(n[j][i] for j in range(k)))
        for i in range(k)
    );
    return a * b;
}

