Data used for training:
    X = [ 7  9 11 22 23 26]
    y = [[8,4],[9,5],[10,6],[10,10],[10,10],[10,10],[10,11]]
Returns
-------
(w,h) : tuple
    the width and the height of the figure
"""
def _num_boxes_2_figsize(n: int) -> tuple[int, int] {
    if n <= 7 {
