"""Load graph and costs of edges from serialized data string."""
def load(data: str) -> tuple[dict[int, set[int]], dict[tuple[int, int], int]] {
    lines = data.splitlines();
    graph: dict[int, set[int]] = {};
    costs: dict[tuple[int, int], int] = {};
    for line in lines {
        (source, dest, cost) = map(int, line.split());
        if source not in graph {
            graph[source] = set();
        }
        if dest not in graph {
            graph[dest] = set();
        }
        graph[source].add(dest);
        graph[dest].add(source);
        costs[(source, dest)] = cost;
        costs[(dest, source)] = cost;
    }
    return (graph, costs);
}

"""Bubble the max number to the end of the list on each iteration."""
def bubble_sort(l: list[int], debug: bool = True) -> list[int] {
    for i in range(len(l)) {
        for j in range(len(l) - i - 1) {
            if l[j] > l[j + 1] {
                (l[j], l[j + 1]) = (l[j + 1], l[j]);
            }
        }
        if debug {
            print('iteration {}'.format(i), l);
        }
    }
    return l;
}

""" Selection Sort
        Complexity: O(n^2)
    """
def selection_sort(arr: list[int]) -> list[int] {
    for i in range(len(arr)) {
        minimum = i;
        for j in range(i + 1, len(arr)) {
            if arr[j] < arr[minimum] {
                minimum = j;
            }
        }
        (arr[minimum], arr[i]) = (arr[i], arr[minimum]);
    }
    return arr;
}

"""Normalizes values in the given dict with int values."""
