}

"""
@param rows: rows to be grouped by
@param db: database name, string
"""
def merge_duplicate_rows(rows: list[dict[str, dict[str, str | int | float | list]]], db: str) -> dict[str, dict[str, str | int | float | list]] {
    rows = list(rows);
    keys = set();
    for row in rows {
        for k in row[db] {
            keys.add(k);
        }
    }
    first_row = rows[0];
    other_rows = rows[1:];
    for row in other_rows {
        for i in keys {
            try {
                aa = first_row[db][i];
            } except KeyError {
                try {
                    first_row[db][i] = row[db][i];
                } except KeyError {
                    ;
                }
                continue;
            }
            if i in row[db] {
                if row[db][i] != first_row[db][i] {
                    if not isinstance(aa, list) {
                        aa = [aa];
                    }
                    aa.append(row[db][i]);
                    first_row[db][i] = aa;
                }
            } else {
                continue;
            }
        }
    }
    return first_row;
}

