"""Return the maximum sum of all the possible contiguous subarrays."""
def largest_sum(int_list: list[int]) -> float {
    max_sum = float('-inf');
    for i in range(len(int_list)) {
        for j in range(i + 1, len(int_list) + 1) {
            current_sum = sum(int_list[i:j]);
            if current_sum > max_sum {
                max_sum = current_sum;
            }
        }
    }
    return max_sum;
}

"""Returns i + the ordinal indicator for the number.

    Example: ordinal(3) => '3rd'
    """
def ordinal(i: int | str) -> str {
    i = int(i);
    if i % 100 in (11, 12, 13) {
        return '%sth' % i;
    }
    ord = 'th';
    last_digit = i % 10;
    if last_digit == 1 {
        ord = 'st';
    } elif last_digit == 2 {
        ord = 'nd';
    } elif last_digit == 3 {
        ord = 'rd';
    }
    return '%s%s' % (i, ord);
}

"""Build a resource based on a list of properties given as key-value pairs. Leave properties with empty values out of the inserted resource."""
def get_api_request_dict(properties: dict[str, object]) -> dict[str, object] {
    resource = {};
    for p in properties {
        prop_array = p.split('.');
        ref = resource;
        for (pa, _) in enumerate(prop_array) {
            is_array = False;
            key = prop_array[pa];
            if key[-2:] == '[]' {
                key = key[0:len(key) - 2];
                is_array = True;
            }
            if pa == len(prop_array) - 1 {
                if properties[p] {
                    if is_array {
                        if isinstance(properties[p], str) {
                            ref[key] = properties[p].split(',');
                        } else {
                            ref[key] = properties[p];
                        }
                    } else {
                        ref[key] = properties[p];
                    }
                }
            } elif key not in ref {
                ref[key] = {};
                ref = ref[key];
            } else {
                ref = ref[key];
            }
        }
    }
    return resource;
}

