"""Permutes the provided list."""
def permutations(values: list[str]) -> str | list[str] {
    if len(values) == 1 {
        return values[0];
    }
    ret = [];
    i = 0;
    for item in values {
        values.remove(item);
        perms = permutations(values);
        for perm in perms {
            ret.append(item + perm);
        }
        values.insert(i, item);
        i += 1;
    }
    return ret;
}

"""Finds all the primes below number n using the sieve of Eratosthenes."""
def find_primes(n: int) -> list[int] {
    candidates = [(i + 2) for i in range(n - 1)];
    for p in candidates {
        for i in candidates {
            if i % p == 0 and p != i {
                candidates.remove(i);
            }
        }
    }
    return candidates;
}

