jac_code:
"""Return a possibly deeply buried {key, value} with all parent keys.

    Given:

        keys = ['a', 'b']
        d = {'a': {'b': 1, 'c': 3}, 'b': 4}

    returns:

        {'a': {'b': 1}}

    """
def find_item(keys: list[str], d: dict[str, int | dict[str, int]], create: bool = False) -> dict[str, int | dict | None] {
    fallback: dict[str, int | dict[str, int]] | None = {} if create else None;
    value = d.get(keys[0], fallback);
    if len(keys) > 1 and type(value) is dict {
        return {keys[0]: find_item(keys[1:], value as dict[str, int | dict[str, int]], create)};
    }
    return {keys[0]: value};
}

"""Return the value of a string

    This function finds the longest leftmost number in the string and
    returns it. If there are no valid numbers then it returns 0.

    The method chosen here is very poor - we just keep trying to convert the
    string to a float and just use the last successful as we increase
    the size of the string. A Regular expression approach is probably
    quicker.

    """
