"""given the ram state, get the position of the player"""
def get_player_position(ram: list[int]) -> tuple[int, int] {
    def _getIndex(address: str) -> int {
        assert type(address) == str and len(address) == 2;
        row: str = address[0];
        col: str = address[1];
        row_i = int(row, 16) - 8;
        col_i = int(col, 16);
        return row_i * 16 + col_i;
    }
    def getByte(ram: list[int], address: str) -> int {
        idx = _getIndex(address);
        return ram[idx];
    }
    x = int(getByte(ram, 'aa'));
    y = int(getByte(ram, 'ab'));
    return (x, y);
}

