"""x is a positive integer. Convert it to base two as a list of integers
    in reverse order as a list."""
def int2baseTwo(x: int) -> list[int] {
    assert x >= 0;
    bit_inverse = [];
    while x != 0 {
        bit_inverse.append(x & 1);
        x >>= 1;
    }
    return bit_inverse;
}

"""Calculate matching score that considers both the relative intensities of the matching peaks
    (i.e. is is 100 vs 98, or 100 vs 2?) and also the number of matches versus the total number of peaks in each vector

    """
def weighted_match_score(vector1: list[float], vector2: list[float]) -> float {
    vector1_weighted_pairwise_match = 0.0;
    vector2_weighted_pairwise_match = 0.0;
    for i in range(len(vector1)) {
        if vector1[i] > 0 and vector2[i] > 0 {
            weighting_factor = vector1[i] / vector2[i];
            if weighting_factor > 1 {
                weighting_factor = 1 / weighting_factor;
            }
            vector1_weighted_pairwise_match += vector1[i] * weighting_factor;
            vector2_weighted_pairwise_match += vector2[i] * weighting_factor;
        }
    }
    vector1_score = vector1_weighted_pairwise_match / sum(vector1) if sum(vector1) > 0 else 0;
    vector2_score = vector2_weighted_pairwise_match / sum(vector2) if sum(vector2) > 0 else 0;
    return vector1_score if vector1_score < vector2_score else vector2_score;
}

