def isBin(s: str) -> bool {
    for ch in s {
        code = ord(ch);
        if code < 9 {
            return True;
        } elif code > 13 and code < 32 {
            return True;
        } elif code > 126 {
            return True;
        }
    }
    return False;
}

"""
    Returns True if each key,val pair is present in the matchee
    """
def dict_match(matcher: dict[str, str | list[str]], matchee: dict[str, str | list[str]]) -> bool {
    for (key, val) in matcher.items() {
        if not matchee.get(key) {
            return False;
        } elif not isinstance(matchee.get(key), list) {
            mval = [matchee.get(key) as str];
        } else {
            mval = matchee.get(key) as list[str];
        }
        if isinstance(val, list) {
            for item in val {
                if item not in mval {
                    return False;
                }
            }
        } elif val not in mval {
            return False;
        }
    }
    return True;
}

"""
       blending function increasing concave
       d = delta x = xabs - xdr
       u = uncertainty radius of xabs estimate error
       s = tuning scale factor

       eq 3.12

       returns blend
    """
def blendConcaveInc(d: float = 0.0, u: float = 1.0, s: float = 1.0, h: float = 1.0) -> float {
    d = float(d);
    u = float(u);
    s = float(s);
    m = 2 * s - u - d;
    if m == 0 {
        return h;
    }
    if d >= s {
        return h;
    }
    b = h * (s - u) / m;
    return b;
}

