"""Convert a match's letter identifier to numbers."""
def matchIdToNumber(matchId: str) -> int {
    id_sum = 0;
    for letter in matchId {
        value = ord(letter.upper()) - 64;
        if value < 1 or value > 26 {
            raise ValueError(
                "Match identifier should only contain letters (got '{}')".format(letter)
            );
        }
        id_sum += value;
    }
    return id_sum;
}

"""
    Binomial coefficients, thanks to Andrew Dalke.
    """
def binomial(n: int, k: int) -> int {
    if 0 <= k <= n {
        n_tok = 1;
        k_tok = 1;
        for t in range(1, min(k, n - k) + 1) {
            n_tok *= n;
            k_tok *= t;
            n -= 1;
        }
        return n_tok // k_tok;
    } else {
        return 0;
    }
}

