    for i in range(zoom, 0, -1) {
        digit = 0;
        mask = 1 << (i - 1);
        if (TileX & mask) != 0 {
            digit += 1;
        }
        if (TileY & mask) != 0 {
            digit += 2;
        }
        quadKey += str(digit);
    }
    return quadKey;
}

