"""
    Generate full taxonomic lineage from a taxid
    Args:
        taxid (str): taxid
        names_map (dict[str:str]): the taxonomic names for each taxid node
        ranks_map (dict[str:str]): the parent node for each taxid
    Returns:
        taxonomy (str): full taxonomic lineage string

    """
def get_full_name(taxid: str, names_map: dict[str, str], ranks_map: dict[str, str]) -> str {
    taxid_lineage = list();
    while True {
        taxid_lineage.append(taxid);
        if taxid not in ranks_map {
            break;
        }
        new_taxid = ranks_map[taxid];
        if taxid == new_taxid {
            break;
        } else {
            taxid = new_taxid;
        }
    }
    names_lineage = [names_map[t] for t in taxid_lineage];
    return ";".join(reversed(names_lineage));
}

"""Sorts the list by inserting the numbers in a specific index."""
def insertionSort(myList: list[int]) -> list[int] {
    for index in range(1, len(myList)) {
        actual_value = myList[index];
        actual_position = index;
        while actual_position > 0 and myList[actual_position - 1] > actual_value {
            myList.insert(actual_position, myList.pop(actual_position - 1));
            actual_position -= 1;
        }
        myList[actual_position] = actual_value;
    }
    return myList;
}

"""
The governing differential equation of the Falkner-Skan boundary layer solution.
"""
def falkner_skan_differential_equation(eta: float, f: list[float], beta: float) -> list[float] {
    return [f[1], f[2], -f[0] * f[2] - beta * (1 - f[1] ** 2)];
}

