"""
If Q = [
    [1,2,3],
    [4,5,6],
    [7,8,9],
]
I - Q:
[[1,0,0]            [[0,-2,-3]
 [0,1,0]   - Q =     [-4,-4,-6]
 [0,0,1]]            [-7,-8,-8]]
"""
def subtract_Q_from_identity(Q: list[list[int]]) -> list[list[int]] {
    for (row, _) in enumerate(Q) {
        for (item, _) in enumerate(Q[row]) {
            if row == item {
                Q[row][item] = 1 - Q[row][item];
            } else {
                Q[row][item] = -Q[row][item];
            }
        }
    }
    return Q;
}

"""From https://www.geeksforgeeks.org/longest-common-substring-array-strings/"""
def find_stem(arr: list[str]) -> str {
    n = len(arr);
    s = arr[0];
    ll = len(s);
    res = '';
    for i in range(ll) {
        for j in range(i + 1, ll + 1) {
            stem = s[i:j];
            k = 1;
            for k in range(1, n) {
                if stem not in arr[k] {
                    break;
                }
            }
            if k + 1 == n and len(res) < len(stem) {
                res = stem;
            }
        }
    }
    return res;
}

