"""Parse optimization method parameters."""
def parse_optimization_method(lr_method: str) -> tuple[str, dict[str, float]] {
    if '-' in lr_method {
        lr_method_name = lr_method[:lr_method.find('-')];
        lr_method_parameters: dict[str, float] = {};
        for x in lr_method[lr_method.find('-') + 1:].split('-') {
            split = x.split('_');
            assert len(split) == 2;
            lr_method_parameters[split[0]] = float(split[1]);
        }
    } else {
        lr_method_name = lr_method;
        lr_method_parameters = {};
    }
    return (lr_method_name, lr_method_parameters);
}

"""
Convert number of bytes to a "human-readable" format. i.e. 1024 -> 1KB
Shamelessly copied from: https://stackoverflow.com/a/1094933/2307994
"""
def bytes_to_human_readable(bytes_in: int, suffix: str = 'B') -> str {
    size: float = bytes_in;
    for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'] {
        if abs(size) < 1024.0 {
            return "%3.1f%s%s" % (size, unit, suffix);
        }
        size /= 1024.0;
    }
    return "%.1f%s%s" % (size, 'Yi', suffix);
}

