"""
    True when my_word matches other_word with _ gaps and equal length.
    """
def match_with_gaps(my_word: str, other_word: str) -> bool {
    my_word = my_word.replace('_ ', '_');
    other_word_letters: list[str] = [];
    non_other_word_letters: list[str] = [];
    if len(my_word) != len(other_word) {
        return False;
    }
    for (index, letter) in enumerate(my_word) {
        other_letter = other_word[index];
        if letter == '_' {
            non_other_word_letters.append(other_letter);
            if other_letter in other_word_letters {
                return False;
            }
        } else {
            other_word_letters.append(other_letter);
            if letter != other_letter or letter in non_other_word_letters {
                return False;
            }
        }
    }
    return True;
}

"""Value matrix for knapsack problem.

items - list(name, weight, value)
limit - maximum weight of knapsack

return matrix NxM (N - len(item) + 1, M - limit + 1)
"""
def knapsack_matrix(items: list[tuple[str, int, int]], limit: int) -> list[list[int]] {
    matrix = [[0] * (limit + 1) for _ in range(len(items) + 1)];
    for i in range(1, len(items) + 1) {
        (_, weight, value) = items[i - 1];
        for w in range(1, limit + 1) {
            if weight > w {
                matrix[i][w] = matrix[i - 1][w];
            } else {
                matrix[i][w] = max(matrix[i - 1][w], matrix[i - 1][w - weight] + value);
            }
        }
    }
    return matrix;
}

"""Transform EDU predictions to SciDTB format."""
def transform_prediction_to_scidtb_format(edus: list[list[str]], arcs: list[tuple[int, int, str]]) -> dict[str, list[dict[str, int | str]]] {
    output = {'root': []};
    output['root'].append({'id': 0, 'parent': -1, 'text': 'ROOT', 'relation': 'null'});
    for (head, dep, rel) in arcs {
        assert dep != 0;
        edu_info = {
            'id': dep,
            'parent': head,
            'text': ' '.join(edus[dep]),
            'relation': rel
        };
        output['root'].append(edu_info);
    }
    return output;
}

