"""
    Given an input array consisting on only 0, 1, and 2, sort the array in a single traversal.
    """
def sort_012(arr: list[int]) -> list[int] {
    n = len(arr);
    pos0 = 0;
    pos2 = n - 1;
    i = 0;
    while i <= pos2 {
        if arr[i] == 0 {
            (arr[pos0], arr[i]) = (arr[i], arr[pos0]);
            pos0 += 1;
            i += 1;
        } elif arr[i] == 2 {
            (arr[pos2], arr[i]) = (arr[i], arr[pos2]);
            pos2 -= 1;
        } else {
            i += 1;
        }
    }
    return arr;
}

"""Returns the difference between the sum of the squares and the square of the sum of the specified number of the first natural numbers."""
def calculate(nth_number: int) -> int {
    sums = sum(number for number in range(1, nth_number + 1));
    sum_of_squares = sum(number ** 2 for number in range(1, nth_number + 1));
    return sums ** 2 - sum_of_squares;
}

