def countparens(text: str) -> bool {
    currcount = 0;
    for char in text {
        if char == "(" {
            currcount += 1;
        } elif char == ")" {
            currcount -= 1;
            if currcount < 0 {
                return False;
            }
        }
    }
    return currcount == 0;
}

