"""Detect binary object beginnings, ends, and lengths in a !d signal."""
def detect_binary_blocks(vec_bin: list[bool]) -> tuple[list[int], list[int], list[int]] {
    (begins, ends, lengths) = ([], [], []);
    if vec_bin[0] {
        begins.append(0);
    }
    length = 0;
    for i in range(1, len(vec_bin)) {
        if vec_bin[i] > vec_bin[i - 1] {
            begins.append(i);
        } elif vec_bin[i] < vec_bin[i - 1] {
            ends.append(i);
            lengths.append(length);
            length = 0;
        } elif vec_bin[i] == 1 {
            length += 1;
        }
    }
    if vec_bin[-1] {
        ends.append(len(vec_bin) - 1);
        lengths.append(length);
    }
    return (begins, ends, lengths);
}

"""Count the # of differences between equal length strings str1 and str2. Max diff can be capped using capdistance to short-circuit full calculation when only care about a range of distances."""
def hamming_distance(str1: str, str2: str, capdistance: int | None = None) -> int {
    diffs = 0;
    if len(str1) != len(str2) {
        raise ValueError(
            'str1 and str2 must be equal lengths, but found %s and %s.' % (len(str1), len(str2))
        );
    }
    for (ch1, ch2) in zip(str1, str2) {
        if ch1 != ch2 {
            diffs += 1;
            if capdistance is not None and diffs >= capdistance {
                return diffs;
            }
        }
    }
    return diffs;
}

