        return [x + y for (x, y) in zip(seq1, seq2)];
    } elif len(seq1) == 0 or len(seq2) == 0 {
        return [];
    } else {
        smaller_length = len(seq1) if len(seq1) < len(seq2) else len(seq2);
        seq1 = seq1[0:smaller_length];
        seq2 = seq2[0:smaller_length];
        return [x + y for (x, y) in zip(seq1, seq2)];
    }
}

