def _generate_anchor_configs(
    min_level: int,
    max_level: int,
    num_scales: int,
    aspect_ratios: list[tuple[float, float]]
) -> dict[int, list[tuple[int, float, tuple[float, float]]]] {
    anchor_configs = {};
    for level in range(min_level, max_level + 1) {
        anchor_configs[level] = [];
        for scale_octave in range(num_scales) {
            for aspect in aspect_ratios {
                anchor_configs[level].append(
