"""Find the greatest common denominator with 2 arbitrary integers."""
def gcd_iter(a: int, b: int) -> int | None {
    orig_b = b;
    orig_a = a;
    if a > b {
        while b > 0 {
            if a % b == 0 and orig_b % b == 0 {
                return b;
            }
            b -= 1;
        }
    } else {
        while a > 0 {
            if b % a == 0 and orig_a % a == 0 {
                return a;
            }
            a -= 1;
        }
    }
}

"""
    Improved version, stop when no swap occur
    :type nums: List[int]
    :rtype: List[int]
    """
def bubbleSort2(nums: list[int]) -> list[int] {
    res = list(nums);
    flag = True;
    while flag {
        flag = False;
        for j in range(1, len(res)) {
            if res[j - 1] > res[j] {
                (res[j - 1], res[j]) = (res[j], res[j - 1]);
                flag = True;
            }
        }
    }
    return res;
}

