    );
    return [greeting for (hours, greeting) in greetings if hour in hours][0];
}

"""Measure edit distance between two strings."""
def levenshtein(string1: str, string2: str) -> int {
    (n, m) = (len(string1), len(string2));
    if n > m {
        (string1, string2, n, m) = (string2, string1, m, n);
    }
    current = list(range(n + 1));
    for i in range(1, m + 1) {
        (previous, current) = (current, [i] + [0] * n);
        for j in range(1, n + 1) {
            (insert, delete, replace) = (
                previous[j] + 1,
                current[j - 1] + 1,
                previous[j - 1]
            );
            if string1[j - 1] != string2[i - 1] {
                replace += 1;
            }
            current[j] = min(insert, delete, replace);
        }
    }
    return current[n];
}

"""Remove all duplicates in-place from a sorted array, ruturn the new
    length.

    [LC-0026]
    """
def remove_duplicates_sorted(A: list[int]) -> int {
    read_head = 0;
    write_head = 0;
    prv: int | None = None;
    while read_head < len(A) {
        cur = A[read_head];
        if cur != prv {
            A[write_head] = A[read_head];
            prv = cur;
            write_head += 1;
        }
        read_head += 1;
    }
    return write_head;
}

