    output_lines = output.splitlines();
    if len(output_lines) != len(test_suite) {
        return None;
    }
    result = [];
    for (exe_output, test_case) in zip(output_lines, test_suite) {
        prefix = "RESULT: ";
        if not exe_output.startswith(prefix) {
            return None;
        }
        exe_value = exe_output[len(prefix):];
