"""Less than o(m+n) complexity."""
def intersectionOfSortedArrays(a: list[int], b: list[int]) -> list[int] {
    ia = 0;
    ib = 0;
    op = [];
    while ia < len(a) and ib < len(b) {
        if a[ia] < b[ib] {
            ia += 1;
        } elif a[ia] > b[ib] {
            ib += 1;
        } else {
            op.append(a[ia]);
            ia += 1;
        }
    }
    return op;
}

