"""
    Calculates square parameters acquired from the mouse movements for rendering the square on the image.

    """
def square_params(x_initial: int, x: int, y_initial: int, y: int) -> tuple[tuple[int, int], tuple[int, int], int] {
    side: int = abs(y_initial - y);
    half = side / 2.0;
    x_top = round(x - half);
    x_bottom = round(x + half);
    y_top = min(y_initial, y);
    y_bottom = max(y_initial, y);
    return ((x_top, y_top), (x_bottom, y_bottom), side);
}

"""
    Rebuild the shortest path from source to target as a list and its cost

            Parameters:
                    source (int): the vertex choose as source
                    target (int): the vertex choose as target
                    prev (dict): a dictionary with vertex as key and last previous vertex in the path from the source as value
                                -1 if it is not reachable
                    dist (dict): a dictionary with vertex as key and the total distance from the source as value
            Returns:
                    path (list): the sequence of nodes covered
                    cost (int): cost of the path
    """
def getShortestPath(
    source: int,
    target: int,
    prev: dict[int, int],
    dist: dict[int, int]
) -> tuple[list[int], int] {
    path = [target];
    cost = dist[target];
    while target != source {
        path.append(prev[target]);
        target = prev[target];
    }
    path.reverse();
    return (path, cost);
}

"""Calculates the sum of the square differences of the components of
    v1 and v2 vectors.
    """
def sum_of_square_difference(v1: list[float], v2: list[float]) -> float {
    sum = 0.0;
    for (c1, c2) in zip(v1, v2) {
        t = c1 - c2;
        sum += t * t;
    }
    return sum;
}

