"""This function takes a date of birth and checks whether it's valid or not."""
def dob_fun(dob: str) -> str {
    condition = len(dob) == 10
        and (dob[:4] + dob[5:7] + dob[8:]).isdigit()
        and dob[4] == '-'
        and dob[7] == '-'
        and int(dob[5:7]) <= 12
        and int(dob[8:]) <= 30;
    while not condition {
        dob = input("ERROR: Must follow 1970-01-01 format, try again: ");
        condition = len(dob) == 10
            and (dob[:4] + dob[5:7] + dob[8:]).isdigit()
            and dob[4] == '-'
            and dob[7] == '-'
            and int(dob[5:7]) <= 12
            and int(dob[8:]) <= 30;
    }
    return dob;
}

