"""
See https://engineering.q42.nl/redis-scan-cursor/

Apply mask from max_cursor and reverse bits order
"""
def convert_scan_cursor(cursor: int, max_cursor: int) -> int {
    n = len(bin(max_cursor)) - 2;
    value = bin(cursor)[2:];
    s = ("{:>0%ss}" % n).format(value);
    return int(s[::-1], base=2);
}

"""Implements a comparator using the lexicographical ordering of octets as unsigned integers."""
def _bytearray_comparator(a: bytearray, b: bytearray) -> int {
    a_len = len(a);
    b_len = len(b);
    i = 0;
    while i < a_len and i < b_len {
        a_byte = a[i];
        b_byte = b[i];
        if a_byte != b_byte {
            return -1 if a_byte < b_byte else 1;
        }
        i += 1;
    }
    len_diff = a_len - b_len;
    if len_diff < 0 {
        return -1;
    }
    if len_diff > 0 {
        return 1;
    }
    return 0;
}

"""Implements boolean -> integer matrix mult."""
def matmul2(Ma: list[list[int]], Mb: list[list[int]]) -> list[list[int]] {
    assert len(Ma[0]) == len(Mb), "Ma and Mb sizes aren't compatible";
    size = len(Mb);
    Mres = [[0 for i in range(size)] for j in range(size)];
    for i in range(size) {
        for j in range(size) {
            for k in range(size) {
                Mres[i][j] ^= Ma[i][k] * 255 and Mb[k][j];
            }
        }
    }
    return Mres;
}

