"""
Arguments:
    faces ([[vIdx, ...], ...]): A face representation

Returns:
    set : A set of vertex indexes along the border of the mesh
"""
def getBorders(faces: list[list[int]]) -> set[int] {
    edge_pairs = set();
    for face in faces {
        for f in range(len(face)) {
            edge_pairs.add((face[f], face[f - 1]));
        }
    }
    borders = set();
    for ep in edge_pairs {
        if (ep[1], ep[0]) not in edge_pairs {
            borders.update(ep);
        }
    }
    return borders;
}

"""
    A way to generate varying timeouts based on ranges
  """
def get_timeout(
    gross_time: int,
    start: int,
    end: int,
    precision: int | float,
    split_range: bool
) -> float {
    if split_range {
        top_num = float(end) / precision;
        bottom_num = float(start) / precision;
        if gross_time % 2 == 0 {
            timeout = top_num - float(gross_time) / precision;
        } else {
            timeout = bottom_num + float(gross_time) / precision;
        }
    } else {
        timeout = float(gross_time) / precision;
    }
    return timeout;
}

