"""Returns nCk(n+r-1, n-1) optimized for large n and small r."""
def nCWRk(n: int, r: int) -> int {
    val = 1;
    for i in range(1, r + 1) {
        val *= n + r - i;
        val //= i;
    }
    return val;
}

""" Removes a trailing space in a sentence eg.
