"""Apply map_fn on each element in collection, preserving collection type."""
def map_collection(
    collection: list[int | str | float | bool] | tuple[int | str | float | bool, ...] | dict[str, int | str | float | bool] | None | int | str | float | bool,
    map_fn: Callable[[int | str | float | bool], int | str | float | bool]
) -> list[int | str | float | bool] | tuple[int | str | float | bool, ...] | dict[str, int | str | float | bool] | None | int | str | float | bool {
    if collection is None {
        return None;
    }
    if isinstance(collection, (tuple, list)) {
        return `type(collection)(map_fn(x) for x in collection);
    }
    if isinstance(collection, dict) {
        return {k: map_fn(v) for (k, v) in collection.items()};
    }
    return map_fn(collection);
}

"""
extended euclidean algorithm, returning the gcd and two bezout coefficients
a * alpha + b * beta = 1
"""
def extended_euclidean_gcd(a: int, b: int) -> tuple[int, int, int] {
    (alpha, s, beta, t) = (1, 0, 0, 1);
    while b > 0 {
        q = a // b;
        r = a % b;
        a = b;
        b = r;
        (alpha, s) = (s, alpha - q * s);
        (beta, t) = (t, beta - q * t);
    }
    return (a, alpha, beta);
}

"""Keeps "best" item of each f-defined equivalence class."""
def fancier_uniquer(seq: list[object], f: Callable[[object], object], p: Callable[[list[tuple[int, object]]], tuple[int, object]]) -> list[object] {
    bunches: dict[object, list[tuple[int, object]]] = {};
    for (index, item) in enumerate(seq) {
        marker = f(item);
        bunches.setdefault(marker, []).append((index, item));
    }
    auxlist = [p(candidates) for candidates in bunches.values()];
    auxlist.sort();
    return [item for (_, item) in auxlist];
}

