"""
    get KMP next arrray
    next[i] is the biggest k s.t. pattern[:k] == pattern[:i + 1][-k:]
    """
def getKmpNext(pattern: str) -> list[int] {
    next_arr = [0] * len(pattern);
    (i, j) = (1, 0);
    while i < len(pattern) {
        while j and pattern[j] != pattern[i] {
            j = next_arr[j - 1];
        }
        if pattern[i] == pattern[j] {
            j += 1;
        }
        next_arr[i] = j;
        i += 1;
    }
    return next_arr;
}

"""
Helper function to determine number on a Gann square at coords: x, 0.
If x = 0 -> 1
If x < 0 -> f(-x) - 4 * (-x)
Else -> f(x-1) + 8 * x - 3
"""
def f(x: int) -> int {
    return 1 if x == 0 else f(-x) - 4 * -x if x < 0 else f(x - 1) + 8 * x - 3;
}

