"""Parse a line of input to determine what the user would like to do with it."""
def input(line: str) -> dict[str, str | list[str]] {
    if line.startswith('#') {
        return {"type": "comment", "contents": line};
    }
    tokens = line.split();
    if len(tokens) < 2 {
        raise ValueError(
            "The line must be the name of the branch and have a least one commit"
        );
    }
    (branch, _, source_branch) = tokens[0].partition(':');
    if not source_branch {
        source_branch = 'origin/master';
    }
    return {
        'type': 'newBranch',
        'newBranch': branch,
        'sourceBranch': source_branch,
        'commits': tokens[1:]
    };
}

"""Computes a modified form of the edge clustering coefficient using squares instead of triangles."""
def edge_clustering_coefficient_4(
    u: int, v: int, degree: dict[int, int], neighbors: dict[int, set[int]]
) -> float {
    udeg = degree[u];
    vdeg = degree[v];
    mdeg = (udeg - 1) * (vdeg - 1);
    if mdeg == 0 {
        return float('inf');
    }
    uneighbors = neighbors[u] - {v};
    vneighbors = neighbors[v] - {u};
    num_squares = 0;
    for w in uneighbors {
        wneighbors = neighbors[w] - {u};
        num_squares += len(wneighbors & vneighbors);
    }
    return (num_squares + 1.0) / mdeg;
}

