"""
    Ternary Search
    Complexity: O(log3(N))

    Requires a unimodal array. That means
    that the array has to be increasing and then
    decreasing (or the opposite). The point is to
    find the maximum (or minimum) element. Small
    modifications needed to work with descending
    and then ascending order as well.
    """
def ternary_search(array: list[int]) -> int {
    lower = 0;
    upper = len(array) - 1;
    while lower < upper {
        first_third = lower + (upper - lower) // 3;
        second_third = upper - (upper - lower) // 3;
        if array[first_third] < array[second_third] {
            lower = first_third + 1;
        } else {
            upper = second_third - 1;
        }
    }
    return lower;
}

"""
    Call object method, if it exists.

    Arguments:
        obj (object): The object.
        attr (str): The name of the object method.
        *args (optional): Arguments for method.
        **kwargs (optional): Keyword arguments for method.

    Returns:
        Return value of calling method, or None if object does not have method.
    """
def call_if_attribute(`obj: object, attr: str, *args: object, **kwargs: object) -> object {
    op = getattr(`obj, attr, None);
    if callable(op) {
        return op(*args, **kwargs);
    }
}

