  """
def calculateBallRegion(ballCoordinate: list[float], robotCoordinate: list[float]) -> int {
    ballRegion = 0;
    if ballCoordinate[0] > robotCoordinate[0] {
        if ballCoordinate[1] > robotCoordinate[1] {
            ballRegion = 1;
        } else {
            ballRegion = 4;
        }
    } elif ballCoordinate[1] > robotCoordinate[1] {
        ballRegion = 2;
    } else {
        ballRegion = 3;
    }
    return ballRegion;
}

"""
What comes in:  The sole argument is a non-negative integer n.
What goes out:  Returns n!, that is, n x (n-1) x (n-2) x ... x 1.
Side effects:   None.
Examples:
    factorial(5) returns 5 x 4 x 3 x 2 x 1, that is, 120.
    factorial(0) returns 1 (by definition).
"""
def factorial(n: int) -> int {
    answer = 1;
    for k in range(n) {
        answer = answer * (n - k);
    }
    return answer;
}

