}

"""
    Finds the start of a comment in the line, if any, and returns the line
    up to the comment, the token that started the comment (#, //, or /*),
    and the line after the comment token
    """
def strip_line_comment(line: str) -> tuple[str, str | None, str | None] {
    comment_tokens = ['#', '//', '/*'];
    index = 0;
    while index < len(line) {
        for token in comment_tokens {
            if index > len(line) - len(token) {
                continue;
            }
            if line[index:(index + len(token))] == token
                and line[0:index].replace('\\"', '').count('"') % 2 == 0 {
                return (line[0:index], token, line[(index + len(token)):]);
            }
        }
        index += 1;
    }
    return (line, None, None);
}

"""
    Returns unsigned integer equivalent of bytearray b
    b may be any iterable of ints including bytes or list of ints.
    Big endian is the default.
    If reverse is true then it reverses the order of the bytes in the byte array
    before conversion for little endian.
    """
def unbytify(b: bytes | list[int] = bytearray([]), reverse: bool = False) -> int {
    buf = bytearray(b);
    if not reverse {
        buf.reverse();
    }
    n = 0;
    while buf {
        n <<= 8;
        n += buf.pop();
    }
    return n;
}

"""
Lets use a simple linear function that maps the ends of one scale onto ends
of another. Obviously, we need that
      f(left_min) -> right_min and
      f(left_max) -> right_max,
and points in between are mapped proportionally.
"""
def linear_mapping(_from: list[float], _to: list[float], x: float) -> float {
    return _to[0] + (x - _from[0]) / (_from[1] - _from[0]) * (_to[1] - _to[0]);
}

