"""Compute the value x**n for integer n."""
def power(x: int | float, n: int) -> int | float {
    if n == 0 {
        return 1;
    }
    partial = power(x, n // 2);
    result = partial * partial;
    if n % 2 == 1 {
        result *= x;
    }
    return result;
}

