"""Return whether the sequence slice is a tandem repeat of the given unit length."""
def is_tandem_repeat(start: int, stop: int, unitlength: int, sequence: str) -> bool {
    subseq = sequence[start:stop];
    first_unit = subseq[:unitlength];
    subseq = subseq[unitlength:];
    while subseq {
        thisunit = subseq[:unitlength];
        subseq = subseq[unitlength:];
        if not first_unit.startswith(thisunit) {
            return False;
        }
    }
    return True;
}

