"""Calculates the vertices of the building block/body depending on the input."""
def verticesBody(
    o: list[int | float],
    x: int | float,
    y: int | float,
    z: int | float,
    h: int | float | None = None,
    top: int | float | None = None,
    `override: int | float | None = None
) -> list[str] {
    if not h {
        h = 0.0;
    }
    if top {
        if top < 1.5 {
            z = z + float(top) * h;
        }
    } elif top is None {
        if `override {
            z = `override;
        } else {
            z = z + h;
        }
    }
    p = [];
    p.append("%s %s %s" % (o[0], o[1], o[2]));
    p.append("%s %s %s" % (o[0] + x, o[1], o[2]));
    p.append("%s %s %s" % (o[0] + x, o[1] + y, o[2]));
    p.append("%s %s %s" % (o[0], o[1] + y, o[2]));
    p.append("%s %s %s" % (o[0], o[1], o[2] + z));
    p.append("%s %s %s" % (o[0] + x, o[1], o[2] + z));
    p.append("%s %s %s" % (o[0] + x, o[1] + y, o[2] + z));
