        [-thresh, thresh] -> 0.0
        (thresh, inf) -> 1.0
    """
def triclamp(val: float, thresh: float = 0.8) -> float {
    if val < -thresh {
        return -1.0;
    } elif val > thresh {
        return 1.0;
    }
