"""Associate two dictionaries of (stamp, data) by closest timestamp match."""
def associate(
    first_list: dict[float, object],
    second_list: dict[float, object],
    offset: float,
    max_difference: float
) -> list[tuple[float, float]] {
    first_keys = list(first_list.keys());
    second_keys = list(second_list.keys());
    potential_matches = [
        (abs(a - (b + offset)), a, b) for a in first_keys
        for b in second_keys
        if abs(a - (b + offset)) < max_difference
    ];
    potential_matches.sort();
    matches = [];
    for (diff, a, b) in potential_matches {
        if a in first_keys and b in second_keys {
            first_keys.remove(a);
            second_keys.remove(b);
            matches.append((a, b));
        }
    }
    matches.sort();
    return matches;
}

"""
    Return modular inverse using a version Euclid's Algorithm
    Code by Andrew Kuchling in Python Journal:
    http://www.pythonjournal.com/volume1/issue1/art-algorithms/
    -- in turn also based on Knuth, vol 2.
    """
def invmod(a: int, b: int) -> int {
    (a1, a2, a3) = (1, 0, a);
    (b1, b2, b3) = (0, 1, b);
    while b3 != 0 {
        q = a3 / b3;
        t = (a1 - b1 * q, a2 - b2 * q, a3 - b3 * q);
        (a1, a2, a3) = (b1, b2, b3);
        (b1, b2, b3) = t;
    }
    while a2 < 0 {
        a2 = a2 + a;
    }
    return a2;
}

