"""
Internal recursive call to calculate the GCD.

Remarks:
    See the Q# source for the "_gcd" function at
    https://github.com/Microsoft/QuantumLibraries/blob/master/Canon/src/Math/Functions.qs
"""
def gcd_recursion(
    sign_a: int,
    sign_b: int,
    r: tuple[int, int],
    s: tuple[int, int],
    t: tuple[int, int]
) -> tuple[int, int] {
    (r_1, r_2) = r;
    (s_1, s_2) = s;
    (t_1, t_2) = t;
    if r_2 == 0 {
        return (s_1 * sign_a, t_1 * sign_b);
    }
    quotient = r_1 // r_2;
    r_ = (r_2, r_1 - quotient * r_2);
    s_ = (s_2, s_1 - quotient * s_2);
    t_ = (t_2, t_1 - quotient * t_2);
    return gcd_recursion(sign_a, sign_b, r_, s_, t_);
}

"""Join multiple lists of path segments together, intelligently
handling path segments borders to preserve intended slashes of the
final constructed path.

This function is not encoding aware. It doesn't test for, or change,
the encoding of path segments it is passed.

Examples:
  join_path_segments(['a'], ['b']) == ['a','b']
  join_path_segments(['a',''], ['b']) == ['a','b']
  join_path_segments(['a'], ['','b']) == ['a','b']
  join_path_segments(['a',''], ['','b']) == ['a','','b']
  join_path_segments(['a','b'], ['c','d']) == ['a','b','c','d']

Returns: A list containing the joined path segments.
"""
def join_path_segments(*args: list[str]) -> list[str] {
    finals = [];
    for segments in args {
        if not segments or segments == [''] {
            continue;
        } elif not finals {
            finals.extend(segments);
        } else {
            if finals[-1] == '' and (segments[0] != '' or len(segments) > 1) {
                finals.pop(-1);
            } elif finals[-1] != '' and segments[0] == '' and len(segments) > 1 {
                segments = segments[1:];
            }
            finals.extend(segments);
        }
    }
    return finals;
}

