    >>> _nih_segmented("0123456789abcdef")
    "012345-6789ab-cdef"

    .. _RFC6920: https://www.ietf.org/rfc/rfc6920
    """
def _nih_segmented(h: str, grouping: int = 6) -> str {
    segmented = [];
    while h {
        segmented.append(h[:grouping]);
