"""Remove prefix `start` from sting `s`. Raises a :py:exc:`ValueError`
    if `s` didn't start with `start`."""
def drop_prefix(s: str, start: str) -> str {
    prefix_len = len(start);
    if s[:prefix_len] != start {
        raise ValueError('string does not start with expected value');
    }
    return s[prefix_len:];
}

"""set a bit in a bitstring, 0 = MSB."""
def set_bitstring_bit(bitstring: bytes, bitnum: int, valuetoset: bool) -> bytes {
    bytepos = bitnum >> 3;
    bitpos = 7 - bitnum % 8;
    bytevalue = bitstring[bytepos];
    mask = 1 << bitpos;
    if valuetoset {
        if bytevalue & mask {
            return bitstring;
        }
        return (
            bitstring[:bytepos]
            + (bytevalue + mask).to_bytes(1, byteorder='big')
            + bitstring[bytepos + 1:]
        );
    }
    if bytevalue & mask {
        return (
            bitstring[:bytepos]
            + (bytevalue - mask).to_bytes(1, byteorder='big')
            + bitstring[bytepos + 1:]
        );
    }
    return bitstring;
}

