"""Naive PreOp algorithm."""
def PreOpN[T](op: Callable[[T, T], T], items: list[T]) -> list[T | None] {
    k = len(items);
    output = [None] * k;
    output[0] = items[0];
    for i in range(1, k) {
        output[i] = op(output[i - 1], items[i]);
    }
    return output;
}

"""
    parse optional parameters. Use user input keyword argument's
    values if possible, otherwise use the default value
    """
def parse_optional_param(default_params: dict[str, str], kwargs_dict: dict[str, str]) -> dict[str, str | None] {
    result = dict();
    for key in default_params {
        if key in kwargs_dict {
            if kwargs_dict[key] == "None" {
                result[key] = None;
            } else {
                result[key] = kwargs_dict[key];
            }
        } else {
            result[key] = default_params[key];
        }
    }
    return result;
}

