"""Create a protein fasta file from features with amino acid sequences."""
def features_to_protein_fasta_file(feature_list: list[dict[str, str]], file_name: str) -> int {
    num_added = 0;
    with open(file_name, 'w') as handle {
        for feature in feature_list {
            if 'aa_sequence' in feature {
                match feature['annotation'] {
                    case 'PATRIC':
                        aa_id = 'patric_id';
                    case 'RefSeq':
                        aa_id = 'protein_id';
                    case _:
                        raise ValueError('Annotation must be either "PATRIC" or "RefSeq"');
                }
                handle.write(
                    '>{0}\n{1}\n'.format(feature[aa_id], feature['aa_sequence'])
                );
                num_added += 1;
            }
        }
    }
    return num_added;
}

"""Return the string representation of n in base-b."""
def base_b(n: int, b: int) -> str {
    e = n // b;
    q = n % b;
    if n == 0 {
        return '0';
    } elif e == 0 {
        return str(q);
    } else {
        return base_b(e, b) + str(q);
    }
}

"""This function reverse the table."""
def reverse_table[T](tab: list[T]) -> list[T] {
    for i in range(len(tab) // 2) {
        tmp = tab[i];
        end_val = len(tab) - i - 1;
        tab[i] = tab[end_val];
        tab[end_val] = tmp;
    }
    return tab;
}

