"""Inverts age_to_eye_diameter

    Args:
         D_eye (float): Diameter of Eyepiece (mm); default is 7 mm
    Returns:
         age (float): approximate age
    """
def eye_to_age(D_eye: float) -> int {
    if D_eye > 7.25 {
        return 15;
    } elif D_eye <= 7.25 and D_eye > 6.75 {
        return 25;
    } elif D_eye <= 6.75 and D_eye > 6.25 {
        return 33;
    } elif D_eye <= 6.25 and D_eye > 5.75 {
        return 40;
    } elif D_eye <= 5.75 and D_eye > 5.25 {
        return 54;
    } else {
        return 70;
    }
}

"""Finds the length of microhomology before or after a mutation."""
def __find_microhomology(seq_before: str, seq: str, seq_after: str) -> int {
    i = 1;
    number_of_bases_found = 0;
    while seq[:i] == seq_after[:i] {
        number_of_bases_found += 1;
        i += 1;
    }
    if number_of_bases_found == 0 {
        i = 1;
        while seq[::-1][:i] == seq_before[::-1][:i] {
            number_of_bases_found += 1;
            i += 1;
        }
    }
    return number_of_bases_found;
}

