"""Get Edges & Nodes"""
def clean_field(`node: dict[str, dict[str, dict[str, bool | dict]]]) -> list[str] {
    return_value = [];
    if `node.get("edges") {
        fields = `node["edges"]["node"];
        for (key, val) in fields.items() {
            if val {
                items = clean_field(val as dict[str, dict[str, dict[str, bool | dict]]]);
                return_value.extend([f"{key}.{i}" for i in items]);
            } else {
                return_value.append(key);
            }
        }
    }
    return return_value;
}

