"""
EAN checksum
gewichtete Summe: die letzte Stelle (vor der Pruefziffer) mal 3,
die vorletzte mal 1, ..., addiert Pruefziffer ist dann die Differenz
dieser Summe zum naechsten Vielfachen von 10
"""
def ean8_check_digit(num: int | str) -> int {
    s = str(num)[::-1];
    checksum = 0;
    even = True;
    for char in s {
        n = int(char);
        if even {
            n *= 3;
        }
        checksum += n;
        even = not even;
    }
    return (10 - (checksum % 10)) % 10;
}

"""Pretty-print a number of bytes."""
def FormatBytes(byte_count: int | float) -> str {
    if byte_count > 1000000.0 {
        byte_count = byte_count / 1000000.0;
        return '%.1fm' % byte_count;
    }
    if byte_count > 1000.0 {
        byte_count = byte_count / 1000.0;
        return '%.1fk' % byte_count;
    }
    return str(byte_count);
}

"""Calibrate the begin char position of each token in the sentence."""
def token_begin_char_calibrate(token_value: dict[str, str], text: str) -> dict[str, int] | None {
    res = {};
    ptr = 0;
    for key in sorted(token_value.keys()) {
        token = token_value[key];
        ptr_t = 0;
        while ptr_t < len(token) {
            if ptr >= len(text) {
                print('Calibration failed!');
                return None;
            }
            if text[ptr] == token[ptr_t] {
                if ptr_t == 0 {
                    res[key] = ptr;
                }
                ptr += 1;
                ptr_t += 1;
            } else {
                ptr += 1;
            }
        }
    }
    assert len(token_value) == len(res);
    return res;
}

"""Splits a string into its host and port components."""
def split_host_and_port(host: str | None) -> dict[str, str | int] | None {
    if host is None {
        return None;
    }
    host_and_port: dict[str, str | int] = {};
    parts = host.split(":");
    if len(parts) > 0 {
        host_and_port['host'] = parts[0];
        if len(parts) > 1 {
            host_and_port['port'] = int(parts[1]);
        }
    }
    return host_and_port;
}

"""Returns a group for a URI e.g. science museum, v&a, wikidata. Should operate on the normalised URI produced by `normaliseURI`."""
def assignGroupToURI(uri: str) -> str {
    if "collection.sciencemuseumgroup" in uri {
        return "Science Museum Group Collection";
    } elif "blog.sciencemuseum.org.uk" in uri {
        return "Science Museum Blog";
    } elif "journal.sciencemuseum.ac.uk" in uri {
        return "Science Museum Journal";
    } elif "collections.vam.ac.uk" in uri or "api.vam.ac.uk/v2/objects/search?" in uri {
        return "V&A collection";
    } elif "http://www.wikidata.org/entity/" in uri {
        return "Wikidata";
    } else {
        return "Literal (raw value)";
    }
}

"""Returns class labels from indexes min(1, min(labels_map)) through max(labels_map)."""
def get_class_labels(labels_map: dict[int, str]) -> list[str] {
