"""
Factorize a number into prime numbers. Not that this has been modified to fit the need of the application.
"""
def prime_factorization(n: int) -> list[int] {
    primes = [];
    i = 2;
    while i * i <= n {
        d = 1;
        while n % i == 0 {
            d *= i;
            n = n // i;
        }
        if d > 1 {
            primes += [d];
        }
        i += 1;
    }
    if n > 1 {
        primes += [n];
    }
    return primes;
}

"""
Searches for first occurance of the provided target in the given array.
If target found then returns index of it, else None
Time Complexity = O(log n)
Space Complexity = O(1)
"""
def binary_search(arr: list[int], target: int) -> int | None {
    first = 0;
    last = len(arr) - 1;
    while first <= last {
        mid = (last + first) // 2;
        if arr[mid] == target {
            return mid;
        }
        if arr[mid] > target {
            last = mid - 1;
        }
        if arr[mid] < target {
            first = mid + 1;
        }
    }
    return None;
}

"""Compute the falling factorial of n to depth k."""
def falling(n: int, k: int) -> int {
    if not k {
        return 1;
    }
    output = n;
    while k != 1 {
        output = output * (n - 1);
        n = n - 1;
        k -= 1;
    }
    return output;
}

