"""Turn an integer genomic distance into a pretty string."""
def format_genomic_distance(distance: int, precision: int = 1) -> str {
    formatting_string = '{{0:.{0}f}}'.format(precision);
    if distance < 1000 {
        return '{0:d}bp'.format(int(distance));
    }
    if distance < 1000000 {
        fmt_string = formatting_string + 'kb';
        return fmt_string.format(float(distance) / 1000);
    }
    fmt_string = formatting_string + 'Mb';
    return fmt_string.format(float(distance) / 1000000);
}

"""
        Collect repeated multiplications of string v in s and replace them by exponentiation.

        **Examples**::

            >>> collect_powers('c*c','c')
            'c**2'
            >>> collect_powers('c*c*c*c*c*c*c*c*c*c','c')
            'c**10'
            >>> collect_powers('d*c*c','c')
            'd*c**2'
    """
import re;

def collect_powers(s: str, v: str) -> str {
    m = s.count(v);
    for i in range(m, 0, -1) {
        pattern = re.compile(v + '(\*' + v + '){' + str(i) + '}');
        s = pattern.sub(v + '**' + str(i + 1), s);
    }
    return s;
}

