"""
    Function to achieve 2-way partitioning for quicksort
    1. Start with 2 pointers lt and gt, choose first element (lo) as pivot
    2. Invariant: everything to the left of lt is less than pivot, right of gt is larger than pivot
    3. In each iteration, do the following in order:
        (a) Increment lt until arr[lt] >= arr[lo]
        (b) Decrement gt until arr[gt] <= arr[lo]
        (c) Check if pointers have crossed (gt<=lt),
                if yes then swap arr[lo] with arr[gt] and break out
        (d) If pointers didn't cross, then swap arr[lt] with arr[gt]
    4. Return the index of the pivot (now gt) so that it can be used by __quicksortHelper__
    """
def __partition2way__(arr: list[int], lo: int, hi: int) -> int | None {
    if lo >= hi {
        return;
    }
    lt = lo;
    gt = hi + 1;
    while True {
        while lt < hi {
            lt += 1;
            if arr[lt] >= arr[lo] {
                break;
            }
        }
        while gt > lo {
            gt -= 1;
            if arr[gt] < arr[lo] {
                break;
            }
        }
        if gt <= lt {
            (arr[lo], arr[gt]) = (arr[gt], arr[lo]);
            break;
        }
        if arr[lt] > arr[gt] {
            (arr[lt], arr[gt]) = (arr[gt], arr[lt]);
        }
    }
    return gt;
}

"""Gets input tensor in `input_tensors` that maps `input_detail[i]`."""
def _get_input_tensor(input_tensors: dict[str, list[float]] | list[list[float]], input_details: list[dict[str, str]], i: int) -> list[float] {
    if isinstance(input_tensors, dict) {
        input_detail = input_details[i];
        for (input_tensor_name, input_tensor) in input_tensors.items() {
            if input_tensor_name in input_detail['name'] {
                return input_tensor;
            }
        }
        raise ValueError(
            'Input tensors don\'t contains a tensor that mapped the '
            'input detail %s' % str(input_detail)
        );
    }
    return input_tensors[i];
}

"""Compute the recall in a zero safe way."""
def recall(overlap_count: int, gold_count: int) -> float {
    if gold_count == 0 {
        return 0.0;
    }
    return overlap_count / float(gold_count);
}

"""Apply a loss function to a tensor and pre- and post-scale it."""
def scaled_loss(x: float, fn: callable[[float], tuple[float, float, float]], a: float) -> tuple[float, float, float] {
    a2 = a ** 2;
    (loss, loss_d1, loss_d2) = fn(x / a2);
    return ((loss as float) * a2, loss_d1, (loss_d2 as float) / a2);
}

"""Reverse the odd_flag list from the encoder."""
def get_odd_flags(odd_flags: list[list[bool]], blocks: list[list[bool]], flag_input: bool = False) -> list[list[bool]] {
    odd_list = [flag_input];
    for odd_block in odd_flags {
        odd_list += odd_block;
    }
    odd_list.reverse();
    odd_de = blocks.copy();
    i = 0;
    for (m, odd_block) in enumerate(odd_de) {
        odd_de[m] = blocks[m].copy();
        for (n, _) in enumerate(odd_block) {
            odd_de[m][n] = odd_list[i + 1];
            i += 1;
        }
    }
    return odd_de;
}

