"""
Checks relative (%) difference <floor between x and y.
floor would be a decimal value, e.g. 0.05
"""
def reldiff(x: float, y: float, floor: float | None = None) -> float | int {
    d = x - y;
    if not d {
        return 0;
    }
    ref = x or y;
    d = float(d) / ref;
    return d if not floor else (0, d)[abs(d) >= floor];
}

"""
A numerically stable algorithm is given below. It also computes the mean.
This algorithm is due to Knuth,[1] who cites Welford.[2]
"""
def calcMeanSD(useme: list[float | int]) -> tuple[float, float] {
    mean = 0.0;
    M2 = 0.0;
    sd = 0.0;
    n = len(useme);
    if n > 1 {
        for (i, x) in enumerate(useme) {
            delta = x - mean;
            mean = mean + delta / (i + 1);
            M2 = M2 + delta * (x - mean);
        }
        variance = M2 / (n - 1);
        sd = pow(variance, 0.5);
    }
    return (mean, sd);
}

"""survival_score = 80% * survival time score + 20% * win place score"""
def survival_score(timeSurvived: int, duration: int, winPlace: int) -> int {
    survival = timeSurvived / duration * 100;
    if winPlace == 1 {
        win_place = 100;
    } else {
        win_place = 100 - winPlace;
    }
    survival_score = int(survival * 0.8 + win_place * 0.2);
    if survival_score < 50 {
        survival_score = 50;
    }
    return survival_score;
}

