"""Returns a tuple of the active firmware's configuration"""
def find_active_firmware(sector: bytes) -> tuple[int | None, int | None, int | None] {
    for i in range(8) {
        app_entry = sector[(i * 32):((i * 32) + 32)];
        config_flags = int.from_bytes(app_entry[0:4], "big");
        active = (config_flags & 1) == 1;
        if not active {
            continue;
        }
        app_address = int.from_bytes(app_entry[4:(4 + 4)], "big");
        app_size = int.from_bytes(app_entry[8:(8 + 4)], "big");
        return (app_address, app_size, i);
    }
    return (None, None, None);
}

""" Calcule o troco numa lista com notas de 1,2,5,10,20,50 com sua
    quantidade de notas sem considerar centavos
    ex:
    1 e 10 retorna troco_notas_quantidade = [5,2] quantidade_notas = [1,2]"""
def dar_troco(valor_a_pagar: int, valor_em_dinheiro: int) -> list[tuple[int, int]] {
    notas = (50, 20, 10, 5, 2, 1);
    valor_troco = valor_em_dinheiro - valor_a_pagar;
    troco = [];
    for nota in notas {
        quantidade = valor_troco // nota;
        valor_troco = valor_troco % nota;
        if quantidade != 0 {
            troco.append((nota, quantidade));
        }
    }
    return troco;
}

