"""
    line y = ax + b. returns a,b

    """
def get_line_cf(x0: float, y0: float, x1: float, y1: float) -> tuple[float | None, float | None] {
    same_x = abs(x1 - x0) < 1e-06;
    same_y = abs(y1 - y0) < 1e-06;
    if same_x and same_y {
        return (None, None);
    }
    if same_x {
        a = None;
        b = x0;
    } elif same_y {
        a = 0;
        b = y0;
    } else {
        a = (y1 - y0) / (x1 - x0);
        b = (y0 * x1 - x0 * y1) / (x1 - x0);
    }
    return (a, b);
}

"""
Reference:
https://www.kaggle.com/onodera/multilabel-fscore
https://github.com/KazukiOnodera/Instacart
"""
def multi_label_f_score(y_true: list[int | None], y_pred: list[int | None]) -> float {
    true_labels = set(y_true);
    pred_labels = set(y_pred);
    precision = len(pred_labels & true_labels) / len(pred_labels);
    recall = len(true_labels & pred_labels) / len(true_labels);
    if precision + recall == 0 {
        return 0;
    }
    return (2 * precision * recall) / (precision + recall);
}

"""Count recipes in the sequence before the given pattern appears."""
def find_recipes_2(pattern: str) -> int {
    pattern_len = len(pattern);
    digits = [int(i) for i in pattern];
    last_digits = [];
    recipes = [3, 7];
    elf1 = 0;
    elf2 = 1;
    looking = True;
    while looking {
        new_recipe = recipes[elf1] + recipes[elf2];
        for i in str(new_recipe) {
            if len(last_digits) == pattern_len {
                last_digits.pop(0);
            }
            recipes.append(int(i));
            last_digits.append(int(i));
            if last_digits == digits {
                looking = False;
                break;
            }
        }
        elf1 = (elf1 + recipes[elf1] + 1) % len(recipes);
        elf2 = (elf2 + recipes[elf2] + 1) % len(recipes);
    }
    return len(recipes) - len(digits);
}

