"""Round number of filters based on width multiplier."""
def round_filters(filters: int, width_coefficient: float, depth_divisor: int) -> int {
    scaled_filters = filters * width_coefficient;
    new_filters = int(scaled_filters + depth_divisor / 2) // depth_divisor * depth_divisor;
    new_filters = max(depth_divisor, new_filters);
    if new_filters < 0.9 * scaled_filters {
        new_filters += depth_divisor;
    }
    return int(new_filters);
}

"""
    KlipChop func to to convert lines into a CSV list
    """
def main(textlines: Callable[[], Iterable[str]], messagefunc: Callable[[str], None], config: dict[str, bool | str]) -> str {
    result = list();
    count = 0;
    for line in textlines() {
        if line not in result {
            result.append(line);
            count += 1;
        }
    }
    if config['sort'] {
        result = sorted(result);
    }
    csv_result = (config['separator'] as str).join(result);
    messagefunc(f'{count} unique lines converted into long CSV list.');
    return csv_result;
}

