"""
    Computes elementwise mean across arrays.
    E.g. for input [[1, 2, 4], [5, 3, 6]] returns [3, 2.5, 5]
    """
def mean_across_arrays(arrays: list[list[float]]) -> list[float] {
    n_arrays = len(arrays);
    return [
        sum(array[i] for array in arrays) / n_arrays
        for i in range(len(arrays[0]))
    ];
}

"""Repeatedly apply a function using a regular python loop."""
def unrolled[T](
    i: int,
    init_x: T,
    func: Callable[[T], T],
    num_iter: int,
    return_last_two: bool = False
) -> tuple[int, T] | tuple[int, T, T | None] {
    x = init_x;
    x_old: T | None = None;
    for _ in range(num_iter) {
        x_old = x;
        x = func(x_old);
        i = i + 1;
    }
    if return_last_two {
        return (i, x, x_old);
    }
    return (i, x);
}

