"""
Given a bunch of participants' open-interests and fees,
calculate the total current market score.
"""
def cur_mkt_score_a(a: float, ds: list[float], fs: list[float]) -> float {
  total = 0.0;
  for (d, f) in zip(ds, fs) {
    total += d ** (1 - a) * f ** a;
  }
  return total;
}

"""
    Convert a string to title case.

    Title case means that the first letter of each word is capitalized, and all other letters in the word are lowercase.
    """
def title_case(sentence: str) -> str {
    if not isinstance(sentence, str) {
        raise TypeError(
            ('Invalid input, type %s - Input must be type string' % `type(sentence))
        );
    }
    ret = sentence[0].upper();
    for i in range(1, len(sentence)) {
        if sentence[i - 1] == ' ' {
            ret = ret + sentence[i].upper();
        } else {
            ret = ret + sentence[i].lower();
        }
    }
    return ret;
}

"""Returns a new dictionary containing only the given keys."""
def only_keys[K, V](d: dict[K, V], *keys: K) -> dict[K, V] {
