"""Return the energy for given volume (V - it can be a vector) according to
the Birch Murnaghan function with parameters E0,V0,B0,B01.
"""
def birch_murnaghan(V: float, E0: float, V0: float, B0: float, B01: float) -> float {
    r = (V0 / V) ** (2.0 / 3.0);
    return E0 + 9.0 / 16.0 * B0 * V0 * ((r - 1.0) ** 3 * B01 + (r - 1.0) ** 2 * (6.0 - 4.0 * r));
}

"""Return a double-quoted string, with all special characters properly escaped."""
def shell_esc(txt: str | int | float | bool) -> str {
  new = str(txt);
  new = new.replace("$", "\\$");
  new = new.replace('"', '\\"');
  new = new.replace('`', '\\`');
  return '"' + new + '"';
}

"""
    use points that are on the diagonal to calculate the center points
    corners - array of 4 [x,y] arrays.
    corner[0] = [x0,y0]
        corner[0][0] = x0
        corner[0][1] = y0

    """
def find_center_point(corners: list[list[int]]) -> tuple[int, int] {
    center_x = (corners[0][0] + corners[2][0]) // 2;
    center_y = (corners[0][1] + corners[2][1]) // 2;
    return (center_x, center_y);
}

