""" Check if a value is of the format required to be a call to a header keyword

    Parameters
    ----------
    v : str
      Value to be tested

    Returns
    -------
    valid : bool
      True if 'v' has the correct format to be a header keyword, False otherwise.
    """
def is_keyword(v: str) -> bool {
    valid = True;
    if "," in v or "." not in v {
        return False;
    }
    vspl = v.split(".");
    try {
        int(vspl[0]);
    } except ValueError {
        valid = False;
    }
    if len(vspl) != 2 {
        return False;
    }
    try {
        if valid is True {
            int(vspl[1]);
            valid = False;
        }
    } except ValueError {
        valid = True;
    }
    return valid;
}

