"""
    Returns a list with a running average of input

    The running average is a list with the same size
    as the input.  Each element at position n is the
    average of all of the elements in input[:n+1]

    Example: average([1, 3, 5, 7]) returns
    [1.0, 2.0, 3.0, 4.0]

    Parameter input: The data to process
    Precondition: input an iterable, each element a number
    """
def average(input: list[int]) -> list[float] {
    result: list[float] = [];
    sum = 0;
    count = 0;
    for x in input {
        sum += x;
        count += 1;
        result.append(sum / count);
    }
    return result;
}

""" Calculates relative ratio of power within two bands.

    Parameters
    ----------
    rel_pow_low : float or list of floats
        Low band power or list of low band powers
    rel_pow_high : float or list of floats
        High band power or list of high band powers

    Outputs
    -------
    res : list of float
        List of relative power ratio of given frequency range.
    """
def calc_group_rel_ratios(rel_pow_low: list[float], rel_pow_high: list[float]) -> list[float] {
    if len(rel_pow_low) != len(rel_pow_high) {
        raise ValueError("Size of lists do not match.");
    }
    return [low / high for (low, high) in zip(rel_pow_low, rel_pow_high)];
}

