"""Compute word level Jaccard similarity."""
def jaccard_word_level_similarity(y_true: str, y_pred: str) -> float {
    true_set = set(y_true.lower().split());
    pred_set = set(y_pred.lower().split());
    y_intersect = true_set.intersection(pred_set);
    return len(y_intersect) / (len(true_set) + len(pred_set) - len(y_intersect));
}

""" If `str_or_list` is a list will return it as it is. If it is a str, will return a
    list with the str inside.

    Parameters
    ----------
    str_or_list: str or list

    Returns
    -------
    list
    """
def _check_list[T](str_or_list: str | list[T] | None) -> list[T] | None {
    if str_or_list is None {
        return None;
    }
    if isinstance(str_or_list, list) {
        return str_or_list;
    }
    if isinstance(str_or_list, str) {
        return [str_or_list];
    }
    raise ValueError(
        'Expected a str` or a list`, ' 'got {}.'.format(type(str_or_list))
    );
}

"""
    Return the timecode corresponding to the given frame, for the given fps.

    :param frame_duration: Int representing a number of frames.
    :param fps: Float value representing frames per second.
    :returns: String representing a non-drop-frame timecode value.
    """
def timecode_from_frame(frame_duration: int, fps: float = 24.0) -> str {
    seconds = frame_duration / fps;
    remainder = seconds - int(seconds);
    frames = int(round(remainder * fps));
    minutes = int(seconds) / 60;
    remainder = minutes - int(minutes);
    seconds = int(round(remainder * 60));
    hours = int(minutes) / 60;
    remainder = hours - int(hours);
    minutes = int(round(remainder * 60));
    hours = int(hours);
    timecode = "%02d:%02d:%02d:%02d" % (hours, minutes, seconds, frames);
    return timecode;
}

