"""Return the Excel column number for a column title string."""
def excel_title_to_column(column_title: str) -> int {
    assert column_title.isupper();
    answer = 0;
    index = len(column_title) - 1;
    power = 0;
    while index >= 0 {
        value = (ord(column_title[index]) - 64) * pow(26, power);
        answer += value;
        power += 1;
        index -= 1;
    }
    return answer;
}

""" Utility method to convert a file size in bytes to a human-readable format

    Args:
        num    (int): Number of bytes
        suffix (str): Suffix for 'bytes'

    Returns:
        str: The formatted file size as a string, eg. ``1.21 GB``
    """
def sizeof(num: int | float, suffix: str = 'B') -> str {
    for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'] {
        if abs(num) < 1024.0 {
            return "%3.1f %s%s" % (num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "%.1f %s%s" % (num, 'Y', suffix);
}

"""Convert numbers in word form to integers."""
def text_to_int(textnum: str) -> int | float {
    units = [
        "zero",
        "one",
        "two",
        "three",
        "four",
        "five",
        "six",
        "seven",
        "eight",
        "nine",
        "ten",
        "eleven",
        "twelve",
        "thirteen",
        "fourteen",
        "fifteen",
        "sixteen",
        "seventeen",
        "eighteen",
        "nineteen"
    ];
    tens = [
        "",
        "",
        "twenty",
        "thirty",
        "forty",
        "fifty",
        "sixty",
        "seventy",
        "eighty",
        "ninety"
    ];
    modifiers = ["", "quarter", "half", "three-quarters"];
    numwords: dict[str, int | float] = {"and": 0, "a": 0};
    for (idx, word) in enumerate(units) {
        numwords[word] = idx;
    }
    for (idx, word) in enumerate(tens) {
        numwords[word] = idx * 10;
    }
    for (idx, word) in enumerate(modifiers) {
        numwords[word] = idx * 0.25;
    }
    current: int | float = 0;
    for word in textnum.split() {
        if word not in numwords {
            raise ValueError("Illegal word: " + word);
        }
        current += numwords[word];
    }
    return current;
}

"""Converts a magnitude to the AB system.

Raises:
    ValueError: If the band is not 'R' or 'V'.
"""
def ConvertToABMag(mag: float, band: str) -> float {
    if band == "V" {
        return mag - 0.044;
    } elif band == "R" {
        return mag + 0.055;
    } else {
        raise ValueError(f"Band {band} cannot be converted to AB.");
    }
}

"""Pads the items list up to the expected length with the provided defaults."""
def defaults(items: list[str], expected: int, *default_values: str) -> list[str] {
    if len(items) == expected {
        return items;
    }
    if len(items) + len(default_values) < expected {
        raise Exception("Too few items, even with defaults.");
    }
    items = list(items);
    items.extend(default_values[len(items) - expected - 1:]);
    return items;
}

"""
    Returns an integer size and scale that best approximates
    the floating point scale on the original size

    Args:
        dsize (tuple): original width height
        scale (float or tuple): desired floating point scale factor
    """
def get_round_scaled_dsize(dsize: tuple[int, int], scale: float | tuple[float, float]) -> tuple[tuple[int, int], tuple[float, float]] {
    try {
        (sx, sy) = scale;
    } except TypeError {
        sx = sy = scale;
    }
    (w, h) = dsize;
    new_w = int(round(w * sx));
    new_h = int(round(h * sy));
    new_scale = (new_w / w, new_h / h);
    new_dsize = (new_w, new_h);
    return (new_dsize, new_scale);
}

"""Compute the base 2 logarithm of n."""
def log2(n: int) -> int {
    l = 0;
    while n > 1 {
        n = n >> 1;
        l = l + 1;
    }
    return l;
}

