"""Merge two sorted lists and count split inversions."""
def merge_and_count_split_inv(B: list[int], C: list[int]) -> tuple[list[int], int] {
    merged = [];
    inv_counter = 0;
    item_b = None;
    item_c = None;
    while B or C or item_b or item_c {
        if not item_b and B {
            item_b = B.pop(0);
        }
        if not item_c and C {
            item_c = C.pop(0);
        }
        if item_b and item_c {
            if item_b <= item_c {
                merged.append(item_b);
                item_b = None;
            } else {
                merged.append(item_c);
                if item_b {
                    inv_counter += 1 + len(B);
                }
                item_c = None;
            }
        } else {
            if item_b {
                merged.append(item_b);
                item_b = None;
            }
            if item_c {
                merged.append(item_c);
                item_c = None;
            }
        }
    }
    return (merged, inv_counter);
}

"""Integral of polynomial order 3 where f(x) = a + b * x + c * x**2 + d * x**3."""
def polynomial_3_integral(x0: int | float, x1: int | float, a: int | float, b: int | float, c: int | float, d: int | float) -> float {
    return (
        a * (x1 - x0)
        + b * (x1 ** 2 - x0 ** 2) / 2.0
        + c * (x1 ** 3 - x0 ** 3) / 3.0
        + d * (x1 ** 4 - x0 ** 4) / 4.0
    );
}

