"""Number of times the slope of the EMG signal changes sign."""
def getSSC(rawEMGSignal: list[int], threshold: int) -> int {
    N = len(rawEMGSignal);
    SSC = 0;
    for i in range(1, N - 1) {
        (a, b, c) = [rawEMGSignal[i - 1], rawEMGSignal[i], rawEMGSignal[i + 1]];
        if a + b + c >= threshold * 3 {
            if a < b > c or a > b < c {
                SSC += 1;
            }
        }
    }
    return SSC;
}

"""Reorders `string` according to `salt`."""
def _reorder(string: str, salt: str) -> str {
    len_salt = len(salt);
    if len_salt != 0 {
        chars = list(string);
        (index, integer_sum) = (0, 0);
        for i in range(len(chars) - 1, 0, -1) {
            integer = ord(salt[index]);
            integer_sum += integer;
            j = (integer + index + integer_sum) % i;
            (chars[i], chars[j]) = (chars[j], chars[i]);
            index = (index + 1) % len_salt;
        }
        string = ''.join(chars);
    }
    return string;
}

