    hits: dict[str, list[str]] = {};
    hit_map: dict[str, str | list[str]] = {};
    for (read, hit) in hit_iter {
        hit_map[read] = hit;
        if isinstance(hit, list) {
            for h in hit {
                hits.setdefault(h, []).append(read);
