"""Get all keys from a value in a dictionary."""
def get_keys_from_val(dic: dict[str, int | str], val: int | str) -> list[str] {
    return [key for key in dic if dic[key] == val];
}

"""Separate arguments passed to J2ObjC into source files and J2ObjC flags."""
def _ParseArgs(j2objc_args: list[str]) -> tuple[list[str], list[str]] {
    source_files = [];
    flags = [];
    is_next_flag_value = False;
    for j2objc_arg in j2objc_args {
        if j2objc_arg.startswith('-') {
            flags.append(j2objc_arg);
            is_next_flag_value = True;
        } elif is_next_flag_value {
            flags.append(j2objc_arg);
            is_next_flag_value = False;
        } else {
            source_files.append(j2objc_arg);
        }
    }
    return (source_files, flags);
}

"""the dot product of two vectors"""
def dot(
    v1: tuple[int | float, int | float, int | float],
    v2: tuple[int | float, int | float, int | float]
) -> int | float {
    (x1, y1, z1) = v1;
    (x2, y2, z2) = v2;
    return x1 * x2 + y1 * y2 + z1 * z2;
}

"""
Filter out all conjunctions in a disjunction that contain 'Unknown' keywords.
This can be applied to the resulting value from `flatten_expr`
"""
def remove_unknowns(disj: list[list[str]]) -> list[list[str]] {
    return [
        conj
        for conj in disj
        if 'Unknown' not in conj
    ];
}

"""Compute contrast ratio of two luminance values."""
def get_cr_lum(lum1: float, lum2: float) -> float {
    val = (lum1 + 0.05) / (lum2 + 0.05);
    return val if val >= 1 else 1 / val;
}

"""Edits two given strings and compare them."""
def backspace_compare(first: str, second: str) -> bool {
    first_index = len(first) - 1;
    second_index = len(second) - 1;
    skip_in_first = 0;
    skip_in_second = 0;
    while first_index >= 0 or second_index >= 0 {
        if first[first_index] == '#' {
            skip_in_first += 1;
            first_index -= 1;
            continue;
        } elif skip_in_first > 0 {
            first_index -= 1;
            skip_in_first -= 1;
            continue;
        }
        if second[second_index] == '#' {
            skip_in_second += 1;
            second_index -= 1;
            continue;
        } elif skip_in_second > 0 {
            second_index -= 1;
            skip_in_second -= 1;
            continue;
        }
        if (first_index >= 0 and second_index < 0) or (first_index < 0 and second_index >= 0) {
            return False;
        }
        if first[first_index] != second[second_index] {
            return False;
        }
        first_index -= 1;
        second_index -= 1;
    }
    return True;
}

"""
    check for null string values in array
    """
def check_for_null(array: list[str]) -> list[str] {
    while "" in array {
        array.remove("") if "" in array else array;
    }
    return array;
}

