"""For purposes of vocabulary creation ignore non-ascii documents."""
def keep_comment(
    text: str, min_ascii_fraction: float = 0.75, min_length: int = 1
) -> bool {
    len_total = len(text);
    if len_total < min_length {
        return False;
    }
    len_ascii = sum(c.isalpha() for c in text);
    frac_ascii = float(len_ascii) / float(len_total);
    if frac_ascii < min_ascii_fraction {
        return False;
    }
    return True;
}

"""
Slices off the passed proportion of items from BOTH ends of the passed
list. Assumes list is sorted by magnitude.
"""
def ltrimboth(l: list[float], proportiontocut: float) -> list[float] {
    lowercut = int(proportiontocut * len(l));
    uppercut = len(l) - lowercut;
    return l[lowercut:uppercut];
}

"""Add two tuples."""
def add_tuple(tuple_a: tuple[int, ...] = (), tuple_b: tuple[int, ...] = ()) -> tuple[int, int] {
    if len(tuple_a) < 2 {
        if len(tuple_a) == 0 {
            tuple_a = (0, 0);
        } else {
            tuple_a = (tuple_a[0], 0);
        }
    }
    if len(tuple_b) < 2 {
        if len(tuple_b) == 0 {
            tuple_b = (0, 0);
        } else {
            tuple_b = (tuple_b[0], 0);
        }
    }
    return (tuple_a[0] + tuple_b[0], tuple_a[1] + tuple_b[1]);
}

"""Remove empty entries in a nested list/dictionary of items, deep removing nested empty entries."""
def clean_empty(data: dict | list | str | int | float | bool | None) -> dict | list | str | int | float | bool | None {
    if isinstance(data, dict) {
        cleaned = {k: clean_empty(v) for (k, v) in data.items()};
        return {k: v for (k, v) in cleaned.items() if v};
    }
    if isinstance(data, list) {
        return [v for v in map(clean_empty, data) if v];
    }
    return data;
}

"""Perform accounting-style currency string cleaning for pandas apply."""
def _clean_accounting_column(x: str) -> float {
    y = x.strip();
    y = y.replace(",", "");
    y = y.replace(")", "");
    y = y.replace("(", "-");
    if y == "-" {
        return 0.0;
    }
    return float(y);
}

