"""Convert from percents of image to pixel values."""
def percents_to_pixels(
    image_width: int,
    image_height: int,
    row_percent: float,
    col_percent: float,
    width_percent: float,
    height_percent: float
) -> tuple[int, int, int, int] {
    row = int(image_height * row_percent);
    col = int(image_width * col_percent);
    width = int(image_width * width_percent);
    height = int(image_height * height_percent);
    return (row, col, height, width);
}

"""Variables that are read before they are written in the block."""
def use(block: list[dict[str, list[str] | str]]) -> set[str] {
    defined = set();
    used = set();
    for i in block {
        used.update(
            v
            for v in i.get('args', [])
            if v not in defined
        );
        if 'dest' in i {
            defined.add(i['dest']);
        }
    }
    return used;
}

"""Return the complement of each nucleotide."""
def rev_seq(nuc: str, nuc_type: str = 'dna') -> str {
    match nuc {
        case 'A':
            if nuc_type == 'rna' {
                return 'U';
            }
            return 'T';
        case 'T':
            return 'A';
        case 'C':
            return 'G';
        case 'U':
            return 'A';
        case _:
            return 'C';
    }
}

"""Takes in a state and returns its parity (even = 0, odd = 1)."""
def calc_parity(state: str) -> int {
    bit_sum = 0;
    for bit in state {
        if int(bit) not in (0, 1) {
            raise ValueError('state {} not allowed'.format(state));
        }
        bit_sum += int(bit);
    }
    return bit_sum % 2;
}

"""See: https://github.com/facebookresearch/ParlAI/blob/master/parlai/core/dict.py#L31
        token_dict:  {'hello world', 'ol boy'}
        text: ['hello', 'world', 'buddy', 'ol', 'boy']
        n: max n of n-gram
        ret: ['hello world', 'buddy', 'ol boy']
    """
def find_ngrams(token_dict: set[str], text: list[str], n: int) -> list[str] {
    if n <= 1 {
        return text;
    }
    saved_tokens = [];
    search_tokens = text[:];
    next_search = [];
    while len(search_tokens) >= n {
        ngram = ' '.join(search_tokens[:n]);
        if ngram in token_dict {
            sub_n = min(len(next_search), n - 1);
            saved_tokens.extend(find_ngrams(token_dict, next_search, sub_n));
            next_search.clear();
            saved_tokens.append(ngram);
            search_tokens = search_tokens[n:];
        } else {
            next_search.append(search_tokens.pop(0));
        }
    }
    remainder = next_search + search_tokens;
    sub_n = min(len(remainder), n - 1);
    saved_tokens.extend(find_ngrams(token_dict, remainder, sub_n));
    return saved_tokens;
}

"""Build an argv list from a Microsoft shell style cmdline str."""
def cmdline2list(cmdline: str) -> list[str] {
    whitespace = ' \t';
    bs_count = 0;
    in_quotes = False;
    arg = [];
    argv = [];
    for ch in cmdline {
        if ch in whitespace and not in_quotes {
            if arg {
                argv.append(''.join(arg));
                arg = [];
            }
            bs_count = 0;
        } elif ch == '\\' {
            arg.append(ch);
            bs_count += 1;
        } elif ch == '"' {
            if not bs_count % 2 {
                if bs_count {
                    delete(arg[-(bs_count / 2):],);
                }
                in_quotes = not in_quotes;
            } else {
                delete(arg[-((bs_count / 2) + 1):],);
                arg.append(ch);
            }
            bs_count = 0;
        } else {
            arg.append(ch);
            bs_count = 0;
        }
    }
    if arg or in_quotes {
        argv.append(''.join(arg));
    }
    return argv;
}

"""Determine the maximum length of a list within a list of lists."""
def max_length(x: list[int] | int, y: list[int] | int) -> int {
    if isinstance(x, list) and isinstance(y, list) {
        return max(len(x), len(y));
    } elif isinstance(x, list) and isinstance(y, int) {
        return max(len(x), y);
    } elif isinstance(x, int) and isinstance(y, list) {
        return max(x, len(y));
    } elif isinstance(x, int) and isinstance(y, int) {
        return max(x, y);
    }
    if not isinstance(x, int) or not isinstance(x, list) {
        raise TypeError("Invalid type: " + str(type(x)));
    }
    if not isinstance(y, int) or not isinstance(y, list) {
        raise TypeError("Invalid type: " + str(type(x)));
    }
    return 0;
}

"""
    valid windows versions : 'nt40', 'vista', 'win10', 'win2k', 'win2k3', 'win2k8', 'win31', 'win7', 'win8', 'win81', 'win95', 'win98', 'winxp'

    >>> import unittest
    >>> assert get_windows_version() == 'win7'
    >>> assert get_windows_version('nt40') == 'nt40'
    >>> unittest.TestCase().assertRaises(RuntimeError, get_windows_version, windows_version='invalid')
    """
def get_windows_version(windows_version: str = 'win7') -> str {
    valid_windows_versions = [
        'nt40',
        'vista',
        'win10',
        'win2k',
        'win2k3',
        'win2k8',
        'win31',
        'win7',
        'win8',
        'win81',
        'win95',
        'win98',
        'winxp'
    ];
    if not windows_version {
        windows_version = 'win7';
    }
    windows_version = windows_version.lower().strip();
    if windows_version not in valid_windows_versions {
        raise RuntimeError(
            'Invalid windows_version: "{windows_version}"'.format(
                windows_version=windows_version
            )
        );
    }
    return windows_version;
}

"""
Compare whether all unique whitespace-separated names in name2 appear in name1.

Returns 1 if contained, else 0.
"""
def contained_name(name1: str, name2: str) -> int {
    common_elements = 0;
    words1 = set(name1.split());
    for word in set(name2.split()) {
        if word in words1 {
            common_elements += 1;
        }
    }
    min_elements = min(
        len([s[0] for s in name1.split()]), len([t[0] for t in name2.split()])
    );
    if min_elements > 1 and min_elements == common_elements {
        return 1;
    }
    return 0;
}

