}

"""Tries to read an option from a dictionary. If not found, a
    standard value is returned instead. If no standard value is
    informed, None is returned. Data can also be converted by
    a type cast.
    The given standard value is not converted by typecast.
    """
def read_optional_from_dict[T](
    input_dict: dict[str, T],
    key: str,
    standard_val: T | None = None,
    typecast: type | None = None
) -> T | None {
    try {
        val = input_dict[key];
    } except KeyError {
        return standard_val;
    }
    if typecast is None {
        return val;
    }
    return typecast(val);
}

"""rol(int_type, size, offset) -> int

    Returns the value of int_type rotated left by (offset mod size) bits.
    """
def rol(int_type: int, size: int, offset: int) -> int {
    mask = (1 << size) - 1;
    offset %= size;
    left = (int_type << offset) & mask;
    circular = (int_type & mask) >> (size - offset);
    return left | circular;
}

"""Equation: x = a(y-h)^2 + k"""
def path(y: float) -> tuple[float, float] {
    a = 110.0 / (160.0 ** 2);
    x = a * (y ** 2) + 0.0;
    return (x, y);
}

"""
    modules is dict of otus, metadata is a dictionary of dictionaries where outer dict keys
    are features, inner dict keys are metadata names and values are metadata values
    """
def add_modules_to_metadata(modules: dict[str, list], metadata: dict[str, dict[str, str]]) -> dict[str, dict[str, str]] {
    for (module_, otus) in modules.items() {
        for otu in otus {
            if str(otu) in metadata {
                metadata[str(otu)]['module'] = module_;
            } else {
                metadata[str(otu)] = dict();
                metadata[str(otu)]['module'] = module_;
            }
        }
    }
    return metadata;
}

"""
Extract include paths from command-line arguments.
Recognizes two argument "-I path" and one argument "-Ipath".
"""
def extract_include_paths(args: list[str]) -> list[str] {
    prefixes = ["-I", "-isystem"];
    include_paths = [];
    prefix = "";
    for a in args {
        if a in prefixes {
            prefix = a;
        } elif prefix in prefixes {
            include_paths += [a];
            prefix = "";
        } elif a[0:2] == "-I" {
            include_paths += [a[2:]];
        }
    }
    return include_paths;
}

"""Helper for binary_bracketings_count(n)."""
def catalan(n: int) -> float {
    if n <= 1 {
        return 1;
    }
    return catalan(n - 1) * 2 * (2 * n - 1) / (n + 1);
}

"""Remove trailing ALGOL-style parameters from a target name;
       e.g. foo(bar, baz) -> foo."""
def strip_parameters(target: str) -> str {
    if not target.endswith(")") {
        return target;
    }
    starting_index = target.rfind("(");
    if starting_index == -1 {
        return target;
    }
    return target[0:starting_index];
}

"""Determine the minimum cost of a string."""
def calc_min_cost(string: str) -> int {
    cost = 0;
    if not string {
        return 0;
    }
    characters = set();
    for char in string {
        if char not in characters {
            cost += 1;
            characters.add(char);
        }
    }
    return cost;
}

"""Compute gcd of two positive integers x and y"""
def compute_gcd(x: int, y: int) -> int {
    if x < y {
        return compute_gcd(y, x);
    }
    residual = x % y;
    if residual == 0 {
        return y;
    }
    if residual == 1 {
        return 1;
    }
    return compute_gcd(y, residual);
}

"""Find the correct cluster. Above the last cluster goes into "excluded (together with the ones from kitti cat"""
def find_cluster(dd: int | float, clusters: list[int | str]) -> int | str {
    for (idx, clst) in enumerate(clusters[:-1]) {
        if int(clst) < dd <= int(clusters[idx + 1]) {
            return clst;
        }
    }
    return 'excluded';
}

"""
    Convert axial coordinate to its cubic equivalent.
    """
def axial_to_cubic(col: int, slant: int) -> tuple[int, int, int] {
    x = col;
    z = slant;
    y = -x - z;
    return (x, y, z);
}

"""Merge the first provided dict`` into the second."""
def deepmerge(source: dict[str, object], destination: dict[str, object]) -> dict[str, object] {
    for (key, value) in source.items() {
        if isinstance(value, dict) {
            `node = destination.setdefault(key, {});
            deepmerge(value as dict[str, object], `node as dict[str, object]);
        } else {
            destination[key] = value;
        }
    }
    return destination;
}

"""Mapping (row, column, spin-type) to Jordan-Wigner encoding."""
def map_rcs_to_JW(nh: int, nv: int, row: int, col: int, spin: int) -> int {
    col_adjust = col;
    if row % 2 == 1 {
        col_adjust = nh - 1 - col;
    }
    return row * nh + col_adjust + nh * nv * spin;
}

"""Return True if ``d[k,j] = 0`` for ``0 <= k < i``

    Here ``d`` is a bit matrix implemented as an array of integers.
    """
def zero_column(d: list[int], j: int, i: int) -> bool {
    s = 0;
    for k in range(i) {
        s |= d[k];
    }
    return (s & (1 << j)) == 0;
}

