"""Returns all text from the start of the input string up to the
occurence of the delimiter."""
def parsenext(string: str, delimiter: str) -> str {
    delimlen = len(delimiter);
    i = 0;
    strlen = len(string);
    while i < strlen {
        if string[i:(i + delimlen)] == delimiter {
            break;
        }
        i += 1;
    }
    return string[0:i];
}

"""Convert the temperature from Kelvin to Rankine scale."""
def convert_kelvin_to_rankine(temp: float) -> float {
    return (temp * 9) / 5;
}

"""
      diff(a:iterable, b: iterable)
          a - b; elements in a but not in b

      args:
          a: iterable, b: iterable => eg: [1,2,3], [1]
      return:
          a list of (a - b)        => eg: [2,3]
    """
def diff(a: list[int], b: list[int]) -> list[int] {
    sb = set(b);
    return [e for e in a if e not in sb];
}

"""
    Return minimum number of precincts that could be "bad".
       L = list of n precincts: n (size,name) pairs
       M = margin of victory as number of votes separating winner
           from runner-up
       s = maximum within-precinct miscount
    """
def bmin(L: list[tuple[int, str]], M: int, s: float = 0.2) -> int {
    assert 0 <= M <= sum(x[0] for x in L);
    votes_so_far = 0.0;
    k = 0;
    while votes_so_far < M and k < len(L) {
        votes_so_far += 2.0 * s * L[k][0];
        k += 1;
    }
    return k;
}

