"""bubble sorter."""
def bubsort(a: list[int]) -> list[int] {
    need = True;
    while need {
        need = False;
        for i in range(len(a) - 1) {
            if a[i] > a[i + 1] {
                (a[i], a[i + 1]) = (a[i + 1], a[i]);
                need = True;
            }
        }
    }
    return a;
}

"""
    Runtime: O(n)
    """
def largest_continous(l: list[int]) -> int {
    max_sum = 0;
    start = 0;
    end = 1;
    while end < len(l) {
        if l[start] + l[start + 1] > 0 {
            curr_sum = sum(l[start:end]);
            max_sum = max(curr_sum, max_sum);
            end += 1;
        } else {
            start = end + 1;
            end = start + 1;
        }
    }
    return max_sum;
}

"""Returns sizes in human-readable units. Input is kbytes"""
def humanreadablesize(kbytes: float | str | int) -> str | None {
    try {
        kbytes = float(kbytes);
    } except (TypeError, ValueError, UnicodeDecodeError) {
        return "unknown";
    }
    units = [
        (" KB", 2 ** 10),
        (" MB", 2 ** 20),
        (" GB", 2 ** 30),
        (" TB", 2 ** 40)
    ];
    for (suffix, limit) in units {
        if kbytes > limit {
            continue;
        } else {
            return str(round(kbytes / float(limit / 2 ** 10), 1)) + suffix;
        }
    }
}

