    name : str, name of current package
    """
def add_alternatives(status: dict[str, dict[str, list[str]]], unsure: dict[str, list[str]], names: list[str], name: str) -> dict[str, dict[str, list[str]]] {
    leftovers = [];
    try {
        for d in unsure[name] {
            d = d.split()[0];
            if d in names {
                status[name]["Dependencies"].append(d);
