"""Recursively determine number of spaces at each height."""
def _get_spaces_array_helper(n: int, memo: list[int]) -> int {
    if n == 1 {
        return memo[n - 1];
    }
    if memo[n - 1] != 0 {
        return memo[n - 1];
    }
    prev = _get_spaces_array_helper(n - 1, memo);
    next_val = 2 * prev + 1;
    memo[n - 1] = next_val;
    return next_val;
}

"""
Sticks the given `box`, which is a `(l, t, w, h)`-tuple to the given bounds
which are also expressed as `(l, t, w, h)`-tuple.
"""
def stick_to_bounds(
    box: tuple[int, int, int, int],
    bounds: tuple[int, int, int, int] | None = (0, 0, 1, 1)
) -> tuple[int, int, int, int] {
    if bounds is None {
        return box;
    }
    (l, t, w, h) = box;
    (bl, bt, bw, bh) = bounds;
    l += max(bl - l, 0);
    l -= max((l + w) - (bl + bw), 0);
    t += max(bt - t, 0);
    t -= max((t + h) - (bt + bh), 0);
    return (l, t, w, h);
}

"""Calculates the position of a scanner within its range at a given time step."""
def calc_scanner_pos(scanner_height: int, time_step: int) -> int {
    cycle_midpoint = scanner_height - 1;
    full_cycle = cycle_midpoint * 2;
    cycle_position = time_step % full_cycle;
    return cycle_position if cycle_position <= cycle_midpoint else full_cycle - cycle_position;
}

"""
hsv: [h, s, v]
    h in [0, 360]
    s in [0, 1]
    v in [0, 1]
return [r, g, b]
    r, g, b in [0, 1]
"""
def hsv2rgb(hsv: list[float]) -> list[float] {
    h = hsv[0];
    s = hsv[1];
    v = hsv[2];
    hd = h / 60;
    r = v;
    g = v;
    b = v;
    if s > 0 {
        hdi = max(0, min(5, int(hd)));
        f = hd - hdi;
        if hdi == 0 {
            g *= 1 - s * (1 - f);
            b *= 1 - s;
        } elif hdi == 1 {
            r *= 1 - s * f;
            b *= 1 - s;
        } elif hdi == 2 {
            r *= 1 - s;
            b *= 1 - s * (1 - f);
        } elif hdi == 3 {
            r *= 1 - s;
            g *= 1 - s * f;
        } elif hdi == 4 {
            r *= 1 - s * (1 - f);
            g *= 1 - s;
        } elif hdi == 5 {
            g *= 1 - s;
            b *= 1 - s * f;
        }
    }
    return [r, g, b];
}

"""Re-keys a dict of custom formatters to only use column indices.

  Args:
    formatters: A dict of formatters, keyed by column index or name.
    columns: The list of columns names.

  Returns:
    A dict of formatters keyed only by column index.
  """
def _process_custom_formatters(
    formatters: dict[int | str, Callable[[str], str]],
    columns: list[str]
) -> dict[int, Callable[[str], str]] {
    if not formatters {
        return {};
    }
    column_set = set(columns);
    for col in formatters {
        if isinstance(col, int) and col >= len(columns) {
            print(
                (
                    "Warning: Custom formatter column index %d exceeds total number "
                    "of columns (%d)"
                    % (col, len(columns))
                )
            );
        }
        if not isinstance(col, int) and col not in column_set {
            print(
                (
                    "Warning: Custom formatter column name %s not present in column "
                    "list"
                    % col
                )
            );
        }
    }
    output_formatters = {
        k: v
        for (k, v) in formatters.items()
        if isinstance(k, int)
    };
    for (i, name) in enumerate(columns) {
        if name in formatters {
            if i in output_formatters {
                print(
                    (
                        "Warning: Custom formatter for column index %d present, "
                        "ignoring formatter for column name %s"
                        % (i, name)
                    )
                );
            } else {
                output_formatters[i] = formatters[name];
            }
        }
    }
    return output_formatters;
}

