"""
    Pad message with space to the nearest length of multiple of 16.

    Parameters
    ----------
    msg : bytes
        The original message.

    Returns
    -------
    bytes
        Padded message to the nearest length of multiple of 16.
    """
def pad_msg16(msg: bytes) -> bytes {
    segs = len(msg) // 16;
    if len(msg) % 16 != 0 {
        segs += 1;
    }
    return msg.ljust(segs * 16);
}

"""Helper method: returns total of string sequence."""
def tot(sequence: str, total: int = 0) -> int {
    total = 0;
    counter = 0;
    temp = '';
    plus_minus = 1;
    while counter < len(sequence) {
        try {
            int(sequence[counter]);
            temp += sequence[counter];
        } except ValueError {
            total += int(temp) * plus_minus;
            temp = '';
            if sequence[counter] == '-' {
                plus_minus = -1;
            }
            if sequence[counter] == '+' {
                plus_minus = 1;
            }
        }
        counter += 1;
    }
    total += int(temp) * plus_minus;
    return total;
}

