}

"""
    Find outer-most last parenthesis of a line statement
    Used to identify the argument list in a function call
    """
def find_outer_most_last_parenthesis(line: str) -> str {
    end = 0;
    if line[-1] == ')' {
        start = len(line) - 1;
    } else {
        start = line.rfind(')');
        end = start;
        if start == '-1' {
            assert True, "Could not find right-most closing parenthesis in\n" + line;
        }
    }
    close_bracket_count = -1;
    for pos in range(start - 1, 0, -1) {
        char = line[pos];
        if char == ')' {
            close_bracket_count -= 1;
        } elif char == '(' {
            close_bracket_count += 1;
        }
        if close_bracket_count == 0 {
            start = pos;
            break;
        }
    }
    if end == 0 {
        return line[start:];
    }
    return line[start:end + 1];
}

"""
    Take a dictionary of test data (suitable for comparison to an instance) and return a dict suitable for POSTing.
    """
def post_data(data: dict[str, str | int | float | bool | None | list | tuple]) -> dict[str, str | int | list | tuple] {
    ret: dict[str, str | int | list | tuple] = {};
    for (key, value) in data.items() {
        if value is None {
            ret[key] = '';
        } elif type(value) in (list, tuple) {
            if value and hasattr(value[0], 'pk') {
                ret[key] = [getattr(v, 'pk') for v in value];
            } else {
                ret[key] = value as list | tuple;
            }
        } elif hasattr(value, 'pk') {
            ret[key] = getattr(value, 'pk');
        } else {
            ret[key] = str(value);
        }
    }
    return ret;
}

"""Return left_x and width of overlapping x of two rects."""
def find_x_overlap(
    rect1: dict[str, int | float],
    rect2: dict[str, int | float]
) -> tuple[int | float, int | float] | None {
    r1left = rect1['left_x'];
    r1right = r1left + rect1['width'];
    r2left = rect2['left_x'];
    r2right = r2left + rect2['width'];
    highest_start_point = r1left if r1left >= r2left else r2left;
    lowest_end_point = r1right if r1right <= r2right else r2right;
    if highest_start_point < lowest_end_point {
        return (highest_start_point, lowest_end_point - highest_start_point);
    }
    return None;
}

"""Returns whether the first sequence is a subsequence of the second sequence."""
def subsequence(first_sequence: list[str], second_sequence: list[str]) -> bool {
    for startidx in range(len(second_sequence) - len(first_sequence) + 1) {
        if second_sequence[startidx:startidx + len(first_sequence)] == first_sequence {
            return True;
        }
    }
    return False;
}

"""Makes sure items are not in alphabetical order or any other kind of order."""
def _shuffle(items: list[object]) -> list[object] {
    items = sorted(items);
    return [items[1], items[0]] + items[2:];
}

"""Represent a float in general form using the 'g' format specifier."""
def general(x: str | int | float, n: str | int) -> str {
    n = int(n);
    x = float(x);
    if n < 1 {
        raise ValueError("1+ significant digits required.");
    }
    return ''.join(('{:#.', str(n), 'g}')).format(x);
}

"""Concatenate responses with alternating __p1__ / __p2__ speaker tags."""
def add_person_tokens(
    responses: list[str], first_speaker: int | None = None, last_speaker: int = 1
) -> str {
    if first_speaker is None {
        first_speaker = ((last_speaker + len(responses)) % 2) + 1;
    }
    speaker = first_speaker;
    text = '';
    for response in responses {
        tag = f"__p{speaker}__";
        text += ' ' + tag + ' ' + response;
        speaker = 1 if speaker == 2 else 2;
    }
    return text.strip();
}

