"""Implementation of Bubble sort.

Takes integer list as input,
returns sorted list."""
def bubble_sort(x: list[int]) -> list[int] {
    print("Starting Bubble sort on following list:\n", x);
    loop = 0;
    unsorted = True;
    while unsorted {
        loop += 1;
        print("Bubble sort is in iteration: ", loop);
        changes = 0;
        for i in range(len(x) - 1) {
            if x[i] > x[i + 1] {
                print("Bubble sort is changing position of: ", x[i], "and", x[i + 1]);
                j = x[i];
                x[i] = x[i + 1];
                x[i + 1] = j;
                changes += 1;
            }
        }
        if changes == 0 {
            unsorted = False;
        }
    }
    print("Bubble sort is finished. Sorted list is: \n", x);
    return x;
}

"""write a program which takes as input an array of digits encoding a non negative
       decimal integer D and updates the array to represent D+1. For example (1,2,9)->(1,3,0)

    Args:
        nums (array): [array of integer]
    """
def plus_one(nums: list[int]) -> list[int] {
    nums[-1] += 1;
    n = len(nums);
    for i in range(n - 1, -1, -1) {
        if nums[i] != 10 {
            break;
        }
        nums[i] = 0;
        nums[i - 1] += 1;
    }
    if nums[0] == 10 {
        nums[0] = 1;
        nums.append(0);
    }
    return nums;
}

