"""Get D runs."""
def get_d_runs(ex_stat: list[str]) -> list[list[int]] {
    d_inds = [
        n
        for (n, v) in enumerate(ex_stat)
        if v in ("D", "mD")
    ];
    if len(d_inds) <= 1 {
        return [];
    }
    result = [];
    curr_list = [d_inds[0]];
    for elem in d_inds[1:] {
        prev_elem = curr_list[-1];
        if prev_elem + 1 == elem {
            curr_list.append(elem);
        } else {
            result.append(curr_list.copy());
            curr_list = [elem];
        }
    }
    result.append(curr_list);
    return [x for x in result if len(x) > 1];
}

"""Helper function to parse atom strings given on the command line:
resid, resname/resid, chain/resname/resid, resname/resid/atom,
chain/resname/resid/atom, chain//resid, chain/resname/atom."""
def str2atom(a: str) -> tuple[str | None, str | None, int, str | None] {
    parts = a.split("/");
    match len(parts) {
        case 1:
            return (None, None, int(parts[0]), None);
        case 2:
            return (None, parts[0], int(parts[1]), None);
        case 3:
            if parts[2].isdigit() {
                return (None, parts[1], int(parts[2]), parts[0]);
            } else {
                return (parts[2], parts[0], int(parts[1]), None);
            }
        case _:
            return (parts[3], parts[1], int(parts[2]), parts[0]);
    }
}

