"""Return a string of Newman Conway numbers for the given value."""
def newman_conway(num: int) -> str {
    if num <= 0 {
        raise ValueError("num cannot be less than 1");
    }
    memo = [0] * (num + 1);
    memo[0] = 0;
    memo[1] = 1;
    if num > 1 {
        memo[2] = 1;
    }
    x = 3;
    while x <= num {
        memo[x] = memo[memo[x - 1]] + memo[x - memo[x - 1]];
        x += 1;
    }
    memo.pop(0);
    parts = [str(n) for n in memo];
    return " ".join(parts);
}

"""Evaluates the predicted chunk accuracy."""
def eval(predicted: list[list[dict[str, str]]]) -> float {
    word_cnt = 0;
    correct = 0;
    for sentence in predicted {
        for row in sentence {
            word_cnt += 1;
            if row['chunk'] == row['pchunk'] {
                correct += 1;
            }
        }
    }
    return correct / word_cnt;
}

"""Return a list of ids given either objects with ids or a list of ids."""
def extract_ids(objects_or_ids: list) -> list {
    try {
        ids = [`obj.id for `obj in objects_or_ids];
    } except Exception {
        ids = objects_or_ids;
    }
    return ids;
}

"""Determine whether any cells are in common between two lists of cells."""
def common_cells(region_one: list[str] | str, region_two: list[str] | str) -> bool {
    r1 = region_one if isinstance(region_one, list) else [region_one];
    r2 = region_two if isinstance(region_two, list) else [region_two];
    for cell in r1 {
        if cell in r2 {
            return True;
        }
    }
    return False;
}

"""Encode a string assuming UTF-8 encoding."""
def encode(val: str | bytes | list[str | bytes] | tuple[str | bytes, ...]) -> bytes | list[bytes] {
    if isinstance(val, (list, tuple)) {
        return [encode(v) for v in val] as list[bytes];
    } elif isinstance(val, str) {
        return val.encode('utf-8');
    } else {
        return val;
    }
}

"""get number of groups used by GroupNorm, based on number of channels."""
def get_group_gn(dim: int, dim_per_gp: int, num_groups: int) -> int {
    assert dim_per_gp == -1 or num_groups == -1, "GroupNorm: can only specify G or C/G.";
    if dim_per_gp > 0 {
        assert dim % dim_per_gp == 0, "dim: {}, dim_per_gp: {}".format(dim, dim_per_gp);
        group_gn = dim // dim_per_gp;
    } else {
        assert dim % num_groups == 0, "dim: {}, num_groups: {}".format(dim, num_groups);
        group_gn = num_groups;
    }
    return group_gn;
}

"""Performs "plus" replacement."""
def plus_replacement(
    random: int,
    population: list[int],
    parents: list[int],
    offspring: list[int],
    args: dict[str, object]
) -> list[int] {
    _ = random;
    _ = args;
    pool = list(offspring);
    pool.extend(parents);
    pool.sort(reverse=True);
    return pool[:len(population)];
}

"""Replace null or empty values with a replacement value."""
def replace_null_values(dictionary: dict[str, str | None] | None, replacement_value: str) -> dict[str, str | None] {
    clean_dictionary = {};
    if dictionary is None and not dictionary {
        return clean_dictionary;
    }
    for key in dictionary {
        if dictionary[key] in ('null', 'UNKNOWN', 'unknown', None, 'None') {
            clean_dictionary[key] = replacement_value;
        } else {
            clean_dictionary[key] = dictionary[key];
        }
    }
    return clean_dictionary;
}

"""Return bucket and prefix from full s3 path."""
def parse_path(s3_datapath: str) -> tuple[str, str] {
    bucket_path = str(s3_datapath).split("//")[1];
    parts = bucket_path.split("/");
    bucket = parts[0].strip("/");
    prefix = "/".join(parts[1:]);
    return (bucket, prefix);
}

"""Determine if year is a leap year."""
def leap_year(year: int, calendar: str = 'standard') -> bool {
    leap = False;
    if calendar in ('standard', 'gregorian', 'proleptic_gregorian', 'julian') and year % 4 == 0 {
        leap = True;
        if calendar == 'proleptic_gregorian' and year % 100 == 0 and year % 400 != 0 {
            leap = False;
        } elif calendar in ('standard', 'gregorian') and year % 100 == 0 and year % 400 != 0 and year < 1583 {
            leap = False;
        }
    }
    return leap;
}

"""Get boolean value from M$ INI style configuration."""
def get_bool_from_ini(ini_param: int | str | float | bool | None) -> bool | None {
    if not isinstance(ini_param, str) {
