"""Forms a string with the full url from a filename and base url.

    Keyword arguments:
    f - filename
    baseUrl - address of the root of the website
    dropExtension - true to drop extensions of .html from the filename in urls
    """
def urlstring(f: str, baseUrl: str, dropExtension: bool = False) -> str {
    if f[0] == "." {
        u = f[1:];
    } else {
        u = f;
    }
    if len(u) >= 11 and u[-11:] == "/index.html" {
        u = u[:-10];
    } elif u == "index.html" {
        u = "";
    } elif dropExtension and len(u) >= 5 and u[-5:] == ".html" {
        u = u[:-5];
    }
    if len(u) >= 1 and u[0] == "/" and len(baseUrl) >= 1 and baseUrl[-1] == "/" {
        u = u[1:];
    } elif (len(u) == 0 or u[0] != "/") and (len(baseUrl) == 0 or baseUrl[-1] != "/") {
        u = "/" + u;
    }
    return baseUrl + u;
}

"""Determine year tick positions for a graph axis from a list of years."""
def __get_years_tickvals(years: list[int]) -> list[int] {
    min_year = int(min(years));
    max_year = int(max(years));
    delta = max_year - min_year;
    if delta >= 80 {
        stepsize = 10;
    } elif delta >= 40 {
        stepsize = 5;
    } elif delta >= 16 {
        stepsize = 2;
    } else {
        stepsize = 1;
    }
    return list(range(min_year, max_year + stepsize, stepsize));
}

"""Return the secret number hidden by isMyNumber."""
def jumpAndBackpedal(isMyNumber: callable) -> int {
    guess = 0;
    if isMyNumber(guess) == 0 {
        return guess;
    }
    foundNumber = False;
    while not foundNumber {
        if isMyNumber(guess) == 1 {
            guess = guess - 1;
        } elif isMyNumber(guess) == -1 {
            guess = guess + 1;
        } else {
            foundNumber = True;
        }
    }
    return guess;
}

"""unionWith for Python, but modifying first dictionary instead of returning result"""
def update_with(
    left: dict[str, list],
    right: dict[str, list],
    default_value: list,
    upd_fn: Callable[[list, list], list]
) -> dict[str, list] {
    for (k, val) in right.items() {
        if k not in left {
            left[k] = default_value[:];
        }
        left[k] = upd_fn(left[k], val);
    }
    return left;
}

