    steps = [];
    current = 0.0;
    for i in range(0, num_of_steps) {
        if i == num_of_steps - 1 {
            steps.append(int(round(limit)));
        } else {
            steps.append(int(round(current)));
        }
        current += float(limit) / float(num_of_steps - 1);
    }
    return steps;
}

