"""
    Reduce Function, sums each coordinate of 2 items
    p,q: tuples of (tuple of floats: coordinates,int)
    Returns tuple of (tuple of summed floats, summed int)
    """
def sum_by_elem(p: tuple[tuple[float, ...], int], q: tuple[tuple[float, ...], int]) -> tuple[tuple[float, ...], int] {
    (coords_p, num1) = p;
    (coords_q, num2) = q;
    tup = map(sum, zip(coords_p, coords_q));
    return (tuple(tup), num1 + num2);
}

"""This method predicts the accuracy percentage."""
def accuracy_score(actual: list[int], predicted: list[int]) -> float {
    correct = 0;
    for (a, p) in zip(actual, predicted) {
        if a == p {
            correct += 1;
        }
    }
    return correct / float(len(actual)) * 100.0;
}

"""Deeply merge dictionary2 and dictionary1 then return a new dictionary"""
def deep_merge(dict1: dict, dict2: dict) -> dict {
    if (`type(dict1) is dict) and (`type(dict2) is dict) {
        dict1_copy = dict1.copy();
        for key in dict2.keys() {
            if key in dict1 and `type(dict1[key]) is dict and `type(dict2[key]) is dict {
                dict1_copy[key] = deep_merge(dict1[key], dict2[key]);
            } else {
                dict1_copy[key] = dict2[key];
            }
        }
        return dict1_copy;
    }
    return dict1;
}

"""Product of a list of numbers."""
def _prod(iterable: list[int]) -> int {
    product = 1;
    for x in iterable {
