}

"""Find the sum of n terms in an arithmetic progression."""
def sum_of_series(first_term: float, common_diff: float, num_of_terms: int) -> float {
    return (num_of_terms / 2) * (2 * first_term + (num_of_terms - 1) * common_diff);
}

