"""For scalar input, duplicate it into a sequence of rank length. For
    sequence input, check for correct length.
    """
def normalize_sequence(value: int | float | list[int] | list[float] | tuple[int, ...] | tuple[float, ...], rank: int) -> list[int | float] {
    try {
        lst = list(value);
    } except TypeError {
        lst = [value] * rank;
    }
    if len(lst) != rank {
        raise ValueError('Invalid sequence length.');
    }
    return lst;
}

