""" Merge adjacent numbers in an iterable of numbers.

        Return:
            list of str: Condensed sequence with either ranges or isolated numbers.
    """
def merge_adjacent(
    numbers: list[int | str], indicator: str = '..', base: int = 0
) -> list[str] {
    integers = list(sorted([(int("%s" % i, base), i) for i in numbers]));
    idx = 0;
    result = [];
    while idx < len(numbers) {
        end = idx + 1;
        while end < len(numbers) and integers[end - 1][0] == integers[end][0] - 1 {
            end += 1;
        }
        result.append(
            ("%s%s%s" % (integers[idx][1], indicator, integers[end - 1][1]))
                if end > idx + 1
                else ("%s" % integers[idx][1])
        );
        idx = end;
    }
    return result;
}

"""Recursively update a dictionary. Taken from jupytext.header."""
def recursive_update(target: dict[str, object], update: dict[str, object]) -> dict[str, object] {
    for key in update {
        value = update[key];
        if value is None {
            target.pop(key, None);
        } elif isinstance(value, dict) {
            target[key] = recursive_update(
                target.get(key, {}) as dict[str, object], value as dict[str, object]
            );
        } else {
            target[key] = value;
        }
    }
    return target;
}

