    start_x = startxy[0];
    start_y = startxy[1];
    end_x = endxy[0];
    end_y = endxy[1];
    if start_x < end_x {
        return 270;
    } elif start_x > end_x {
        return 90;
    } elif start_y < end_y {
        return 180;
    } else {
        return 0;
    }
}

"""Returns the size n in human readable form, i.e. as bytes, KB, MB, GB, ..."""
def show_size(n: int | float) -> str {
    size = n;
    if size < 1024 {
        return "{} bytes".format(size);
    }
    for dim in ['KB', 'MB', 'GB', 'TB', 'PB'] {
        size = size / 1024.0;
        if size < 1024 {
            return "{:.3f} {}".format(size, dim);
        }
    }
    return "{} bytes".format(n);
}

"""Snowfall accumulation calculation (STICS SnowAccumulation v1.0)."""
def model_snowaccumulation(
    tsmax: float = 0.0, tmax: float = 0.0, trmax: float = 0.0, precip: float = 0.0
) -> float {
    fs = 0.0;
    if tmax < tsmax {
        fs = 1.0;
    }
    if tmax >= tsmax and tmax <= trmax {
        fs = (trmax - tmax) / (trmax - tsmax);
    }
    return fs * precip;
}

