"""Diff the newest API response with the stored one."""
def diff_weather(new: dict[str, dict[str, int | float | str]], stored: dict[str, dict[str, int | float | str]] | None) -> dict[str, dict[str, int | float | str]] {
    diff = {};
    changed = False;
    for t in new {
        if stored and t in stored {
            if new[t]["max"] != stored[t]["max"] or new[t]["min"] != stored[t]["min"] {
                changed = True;
                diff[t] = {};
                diff[t]["date_str"] = new[t]["date_str"];
                diff[t]["old"] = {};
                diff[t]["old"]["min"] = stored[t]["min"];
                diff[t]["old"]["max"] = stored[t]["max"];
                diff[t]["new"] = {};
                diff[t]["new"]["min"] = new[t]["min"];
                diff[t]["new"]["max"] = new[t]["max"];
                continue;
            }
        }
        diff[t] = {};
        diff[t]["date_str"] = new[t]["date_str"];
        diff[t]["new"] = {};
        diff[t]["new"]["min"] = new[t]["min"];
        diff[t]["new"]["max"] = new[t]["max"];
    }
    return diff if changed or not stored else {};
}

"""Calculates the Simpson index."""
def simpson_index(H: int, P: list[float]) -> float {
    index = 0.0;
    for i in range(0, H) {
        index += float(P[i]) * float(P[i]);
    }
    return index;
}

