"""Check file delimiters; default is tab."""
def check_delim(argument: str | None, `default: str = "\t") -> str {
    assert argument in [
        None,
        ':',
        '|',
        ';',
        '-',
        '\\',
        '/',
        '\\t',
        ',',
        "\t",
        "'\t'",
        "':'",
        "'|'",
        "';'",
        "'-'",
        "'\\'",
        "'/'",
        "'\\t'",
        "','"
    ], "The delimiter given is not accepted.";
    if argument == None {
        return `default;
    } elif argument in [':', '|', ';', '-', '\\', '/', ','] {
        return argument;
    } elif argument in ["':'", "'|'", "';'", "'-'", "'\\'", "'/'", "','"] {
        return argument.strip("'");
    } elif argument in ['\\t', "'\\t'", "\t", "'\t'"] {
        return "\t";
    } else {
        return `default;
    }
}

