"""In : N (consistent NFA)
            q (state in N)
            c (symbol in N's sigma or "")
       Out: The set of states reached via N's Delta.
       EClosure is NOT performed.
       If the move is not defined, return {}.
    """
def step_nfa(N: dict[str, object], q: object, c: str) -> set[object] {
    assert c in (N["Sigma"] | {""}), "c given to step_nfa not in Sigma.";
    assert q in N["Q"], "q given to step_nfa not in Q.";
    if (q, c) in N["Delta"] {
        return N["Delta"][(q, c)] as set[object];
    }
    return set();
}

"""
    source: https://stackoverflow.com/questions/1094841/reusable-library-to-get-human-readable-version-of-file-size
    """
def add_unit_prefix(num: float, unit: str = 'B') -> str {
    for prefix in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi'] {
        if abs(num) < 1024.0 {
            return "%3.1f%s%s" % (num, prefix, unit);
        }
        num /= 1024.0;
    }
    return "%.1f%s%s" % (num, 'Yi', unit);
}

