"""
    Find the root of f(x) = 0 using the Newton-Raphson method recursively.

    Parameters
    ----------
        f       - function
        f_prime - derivative of f
        x0      - starting value
        tol     - tolerance

    Returns
    -------
    root of f(x)
    """
def newton(
    f: Callable[[float], float],
    f_prime: Callable[[float], float],
    x0: float,
    tol: float
) -> float {
    if abs(f(x0)) < tol {
        return x0;
    }
    x1 = x0 - f(x0) / f_prime(x0);
    print("x0 = ", x0, "f(x0) = ", f(x0), "f'(x0) =", f_prime(x0), "x1 = ", x1);
    return newton(f, f_prime, x1, tol);
}

"""Returns True if a type is iterable, or False otherwise.

    Types passed to ``exclude`` will be considered not iterable.
    """
def isiterable(`obj: list | tuple | str | dict | set | bytes | range, exclude: tuple[type, ...] | list[type] | None = None) -> bool {
    excluded = exclude if exclude is not None else ();
    if any(isinstance(`obj, cls) for cls in excluded) {
        return False;
    }
    try {
        iter(`obj);
        return True;
    } except TypeError {
        return False;
    }
}

"""Determine whether subState is a substate of parentState."""
def isSubstateOf(parentState: str | None, subState: str | None) -> bool {
    if parentState is None or subState is None {
        return False;
    }
    if parentState == subState {
        return True;
    }
    if len(subState) <= len(parentState) {
        return False;
    }
    if subState[:len(parentState) + 2] == parentState + '__' {
        return True;
    }
    return False;
}

