"""Varify if given number is a valid ISBN 10 number"""
def is_valid(isbn: str) -> bool {
    digits = [int(n) for n in isbn if n.isnumeric()];
    if len(digits) == 9 and isbn[-1].upper() == "X" {
        digits.append(10);
    }
    if len(digits) != 10 {
        return False;
    }
    sum_ = sum((len(digits) - i) * v for (i, v) in enumerate(digits));
    return sum_ % 11 == 0;
}

"""Return the parent directory path, PHP dirname semantics."""
def php_dirname(_path: str, _levels: int = 1) -> str {
    if _path == "." {
        return ".";
    }
    if _path.endswith("/") {
        _path = _path[:-1];
    }
    parts = _path.split("/");
    if len(parts) == 1 {
        return "/";
    }
    rs = "/".join(parts[:(len(parts) - _levels)]);
    if rs == "" {
        return "/";
    }
    return rs;
}

"""
    Split data from ``iterable`` into two lists.
    Each element is passed to function ``pred``; elements
    for which ``pred`` returns True are put into ``yes`` list,
    other elements are put into ``no`` list.
    """
def split_data[T](iterable: Iterable[T], pred: Callable[[T], bool]) -> tuple[list[T], list[T]] {
    yes: list[T] = [];
    no: list[T] = [];
    for d in iterable {
        if pred(d) {
            yes.append(d);
        } else {
            no.append(d);
        }
    }
    return (yes, no);
}

