"""Calculate the check digit. The number passed should not have the
check digit included."""
def calc_check_digit(number: str) -> str {
    check = 11 - sum((8 - i) * int(n) for (i, n) in enumerate(number)) % 11;
    return '0' if check == 10 else str(check);
}

"""Convert a variable to a list."""
def asList(x: object) -> list[object] {
    if isinstance(x, list) {
        return x;
    } elif isinstance(x, tuple) {
        return list(x);
    } elif not hasattr(x, '__iter__') {
        return [x];
    } else {
        raise ValueError('Could not convert {} to a list'.format(str(x)));
    }
}

"""
Formats an ordinal.
Doesn't handle negative numbers.
"""
def int_nthstr(n: int) -> str {
    assert n >= 0;
    if n % 100 in [11, 12, 13] {
        return '%sth' % n;
    }
    match n % 10 {
        case 1:
            return '%sst' % n;
        case 2:
            return '%snd' % n;
        case 3:
            return '%srd' % n;
        case _:
            return '%sth' % n;
    }
}

"""Replace punctuation with html entities."""
def replace_punctuation(html_str: str) -> str {
    html_str = html_str.replace('.', '&#46;');
    html_str = html_str.replace(',', '&#44;');
    html_str = html_str.replace('!', '&#33;');
    html_str = html_str.replace('?', '&#63;');
    html_str = html_str.replace('(', '&#40;');
    html_str = html_str.replace(')', '&#41;');
    html_str = html_str.replace('[', '&#91;');
    html_str = html_str.replace(']', '&#93;');
    html_str = html_str.replace('{', '&#123;');
    html_str = html_str.replace('}', '&#125;');
    html_str = html_str.replace('<', '&lt;');
    html_str = html_str.replace('>', '&gt;');
    html_str = html_str.replace('"', '&quot;');
    html_str = html_str.replace("'", '&#39;');
    return html_str;
}

