"""Index where t should be inserted in sorted arr (left/right of dups)."""
def bsearch_ins_pos(arr: list[int], t: int, left: bool) -> int {
    low = 0;
    high = len(arr);
    while low < high {
        mid = low + (high - low) // 2;
        if arr[mid] < t {
            low = mid + 1;
        } elif arr[mid] > t {
            high = mid;
        } elif left {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

"""Extract a slice of s from start to stop, taking every step characters."""
def filter_slice(
    s: str,
    start: str | int | None = None,
    stop: str | int | None = None,
    step: str | int | None = None
) -> str {
    xstart = None;
    xstop = None;
    xstep = None;
    if start {
        try {
            xstart = int(start);
        } except ValueError as e {
            xstart = 0;
        }
    }
    if stop {
        try {
            xstop = int(stop);
        } except ValueError as e {
            xstop = -1;
        }
    }
    if step {
        try {
            xstep = int(step);
        } except ValueError as e {
            xstep = 1;
        }
    }
    return s[slice(xstart, xstop, xstep)];
}

