"""Perm function 0, D, BETA defined as:
    $$ f(x) = \sum_{i=1}^n (\sum_{j=1}^n (j+\beta) (x_j^i - \frac{1}{j^i}) )^2$$
    with a search domain of $-n < x_i < n, 1 \leq i \leq n$.
    The global minimum is at $f(x_1, ..., x_n) = f(1, 2, ..., n) = 0.
    """
def perm0db(ind: list[float], beta: float = 10.0) -> tuple[float] {
    return (
        sum(
            (
                sum(
                    (
                        (j + 1.0 + beta)
                        * (
                            ind[j] ** float(i + 1)
                            - 1.0 / (float(j + 1) ** float(i + 1))
                        )
                    ) for j in range(len(ind))
                )
                ** 2.0
            ) for i in range(len(ind))
        ),
    );
}

"""Swap the first two dimensions of a two (or more) dimensional list."""
def transpose(lst: list[list[float]]) -> list[list[float]] {
    t_lst = [];
    for row in lst {
        for (i_col, value) in enumerate(row) {
            if i_col >= len(t_lst) {
                t_lst.append([]);
            }
            t_lst[i_col].append(value);
        }
    }
    return t_lst;
}

"""Recursive implementation of factorial: O(n) runtime, O(n) max stack frames."""
def factorial_rec(n: int) -> int {
    if n == 0 {
        return 1;
    }
    return n * factorial_rec(n - 1);
}

