}

"""
  Slightly improved insertion sort

  Complexity: O(n ** 2)

  """
def insertion_sort2(L: list[int]) -> list[int] {
    for i in range(len(L)) {
        key = L[i];
        j = i - 1;
        while j > -1 and L[j] > key {
            L[j + 1] = L[j];
            j -= 1;
        }
        L[j + 1] = key;
    }
    return L;
}

"""
    Finds the maximum length of a bucket in buckets (dict as returned by bucket_sort)
    """
def max_bucket_len(buckets: dict[int, list[int]]) -> int {
    m = 1;
    for v in buckets.values() {
        m = max(m, len(v));
    }
    return m;
}

"""Calculates evenly distributed byte reads for given file size."""
def byte_lengths(n_bytes: int, n_partitions: int) -> tuple[int, ...] {
    chunk_size = n_bytes // n_partitions;
    byte_reads = [chunk_size] * n_partitions;
    for ix in range(n_bytes % n_partitions) {
        byte_reads[ix] += 1;
    }
    return tuple(byte_reads);
}

"""Quote a value if it isn't quoted yet."""
