"""Bubble sort in place and return the sorted list."""
def bubble_sort(nums_array: list[int]) -> list[int] {
    is_sorted = True;
    for i in range(len(nums_array) - 1) {
        for j in range(len(nums_array) - i - 1) {
            if nums_array[j] > nums_array[j + 1] {
                is_sorted = False;
                temp = nums_array[j];
                nums_array[j] = nums_array[j + 1];
                nums_array[j + 1] = temp;
            }
        }
        if is_sorted {
            break;
        }
    }
    return nums_array;
}

"""Converts 8-bit signed data initally read as unsigned data back to its original relative position."""
def signed_to_unsigned_8bit(data: bytes) -> bytearray {
    converted = bytearray();
    for byte in data {
        if byte > 127 {
            signed = byte - 128;
        } else {
            signed = byte + 128;
        }
        converted.append(signed);
    }
    return converted;
}

"""Lower and AND-searching."""
def search_func(strlist: list[str], queries_by_str: str) -> list[str] {
    queries = queries_by_str.split(' ');
    if len(queries) == 0 {
        return strlist;
    }
    firstq = queries[0];
    if len(firstq) == 0 {
        return strlist;
    }
    if firstq[0] == ' ' {
        return strlist;
    }
    ret = [];
    for original_line in strlist {
        line = original_line.lower();
        is_matched = True;
        for query in queries {
            if line.find(query) == -1 {
                is_matched = False;
                break;
            }
        }
        if is_matched {
            ret.append(original_line);
        }
    }
    return ret;
}

