                }
            }
        }
        return value;
    }
    cleaned = dict();
    for (key, value) in param_dict.items() {
        if isinstance(value, dict) {
            if value['to'] == '' and value['from'] == '' {
                ;
            } else {
                cleaned[key] = {'from': 0, 'to': 0};
                cleaned[key]['from'] = generate_number_from_type(
