    res: str | int | float | bool | None = None;
    if "constant" in val_info {
        constant = val_info["constant"] as dict[str, object];
        res = constant["value"] as str | int | float | bool;
    } elif "constant_reference" in val_info {
        val_list: list[str] = [];
        constant_ref = val_info["constant_reference"] as dict[str, object];
        for source_info in constant_ref["source_name"] as list[object] {
            val_list.append((source_info as dict[str, object])["text"] as str);
        }
        res = ".".join(val_list);
        if yaml_dict is not None {
            structs = yaml_dict["structs"] as dict[str, object];
            if val_list[0] in structs and val_list[1] in (structs[val_list[0]] as dict[str, object])["fields"] as dict[str, object] {
                res_temp = structs[val_list[0]] as dict[str, object];
                res = ((res_temp["fields"] as dict[str, object])[val_list[1]] as dict[str, object])["value"] as str | int | float | bool;
            }
        }
    }
    return res;
}

