"""Convert a map from group -> counter name -> amount to a message
    similar to that printed by the Hadoop binary, with no trailing newline.
    """
def _format_counters(counters: dict[str, dict[str, int]], indent: str = '\t') -> str {
    num_counters = sum(
        len(counter_to_amount) for (group, counter_to_amount) in counters.items()
    );
    message = 'Counters: %d' % num_counters;
    for (group, group_counters) in sorted(counters.items()) {
        if group_counters {
            message += '\n%s%s' % (indent, group);
            for (counter, amount) in sorted(group_counters.items()) {
                message += '\n%s%s%s=%d' % (indent, indent, counter, amount);
            }
        }
    }
    return message;
}

"""
Given a window and a set of disjoint subintervals, return the
"holes", which are the intervals of the refWindow not covered by
the given subintervals.
"""
def holes(refWindow: tuple[int, int, int], intervals: list[tuple[int, int]]) -> list[tuple[int, int]] {
    (_, win_start, win_end) = refWindow;
    output = [];
    intervals = sorted(intervals);
    last_e = win_start;
    for (s, e) in intervals {
        if s > last_e {
            output.append((last_e, s));
        }
        last_e = e;
    }
    if last_e < win_end {
        output.append((last_e, win_end));
    }
    return output;
}

