    }
    if (submission[3] == '-1' and submission[4] != '-1') or (submission[3] != '-1' and submission[4] == '-1') {
        return False;
    }
    if int(submission[1]) >= int(submission[2]) or int(submission[3]) > int(submission[4]) {
