"""Takes in a list of unsorted scores and the highest possible scores and returns a list of sorted scores"""
def sort_player_scores(unsorted_scores: list[int], highest_possible_score: int) -> list[int] {
    tracker: dict[int, int] = {};
    sorted_scores: list[int] = [];
    if type(unsorted_scores) != list {
        raise TypeError(
            "The first argument for sort_player_scores must be of type list."
        );
    } elif type(highest_possible_score) != int {
        raise TypeError(
            "The second argument for sort_player_scores must be of type int."
        );
    } elif len(unsorted_scores) < 1 {
        return sorted_scores;
    }
    for score in unsorted_scores {
        if score in tracker {
            tracker[score] += 1;
        } else {
            tracker[score] = 1;
        }
    }
    for i in range(highest_possible_score, -1, -1) {
        if i in tracker {
            sorted_scores += [i] * tracker[i];
        }
    }
    return sorted_scores;
}

"""
:param bbox1:
:param bbox2:
:return:
Assumption: One bounding box is contained inside another
"""
def get_bigger_bbox(bbox1: list[tuple[float, float]], bbox2: list[tuple[float, float]]) -> list[tuple[float, float]] {
    min_x_1 = min([p[0] for p in bbox1]);
    min_y_1 = min([p[1] for p in bbox1]);
    max_x_1 = max([p[0] for p in bbox1]);
    max_y_1 = max([p[1] for p in bbox1]);
    min_x_2 = min([p[0] for p in bbox2]);
    min_y_2 = min([p[1] for p in bbox2]);
    max_x_2 = max([p[0] for p in bbox2]);
    max_y_2 = max([p[1] for p in bbox2]);
    if min_x_1 < min_x_2 or min_y_1 < min_y_2 {
        return bbox1;
    }
    if max_x_2 < max_x_1 or max_y_2 < max_y_1 {
        return bbox1;
    }
    return bbox2;
}

