def stop_if_mostly_diverging(errdata: list[float]) -> int {
    n_increases = sum([abs(y) > abs(x) for (x, y) in zip(errdata, errdata[1:])]);
    return 0 if len(errdata) * 0.5 < n_increases else -1;
}

"""
    Jaccard similarity of sets a and b
    """
def jaccard_index(a: list[int], b: list[int]) -> float | int {
    intsize = len(set.intersection(a, b));
    unionsize = len(set.union(a, b));
    if unionsize == 0 {
        return 1;
    }
    return float(intsize) / float(unionsize);
}

"""
  Finds the smallest positive integer not in array.
  The smallest possible answer is 1.
  """
def solution(array: list[int]) -> int {
    i = 1;
    visited = [];
    for value in array {
        visited.append(value);
        if value == i {
            while True {
                value += 1;
                if value not in visited {
                    break;
                }
            }
