            return False;
        }
    }
    return True;
}

"""Calculate the largest product from continuous
    substring of given length."""
def largest_product(number: str, series: int) -> int {
    if len(number) < series or series < 0 {
        raise ValueError;
    }
    if not series {
        return 1;
    }
    maximum = 0;
    for i in range(len(number) + 1 - series) {
        partial_sum = int(number[i]);
        for j in number[i + 1:i + series] {
            partial_sum *= int(j);
        }
        maximum = max(maximum, partial_sum);
    }
    return maximum;
}

"""Calculate the Gini index for a split dataset (0 is perfect split)."""
def gini_index(groups: list[list[int]], class_values: list[int]) -> float {
    gini = 0.0;
    for class_value in class_values {
        for group in groups {
            size = len(group);
            if size == 0 {
                continue;
            }
            proportion = [row[-1] for row in group].count(class_value) / float(size);
            gini += proportion * (1.0 - proportion);
        }
    }
    return gini;
}

