"""Returns midpoint values of the quadrant for each RGB component."""
def _adjust_component(r: int, g: int, b: int) -> tuple[int, int, int] {
    mid1 = 31;
    mid2 = 95;
    mid3 = 159;
    mid4 = 223;
    color_list = [];
    for x in (r, g, b) {
        if x < 64 {
            color_list.append(mid1);
        } elif x > 63 and x < 128 {
            color_list.append(mid2);
        } elif x > 127 and x < 192 {
            color_list.append(mid3);
        } else {
            color_list.append(mid4);
        }
    }
    return tuple(color_list);
}

"""Creates a lighter version of a color given by an RGB triplet.

    This is done by mixing the original color with white using the given
    ratio. A ratio of 1.0 will yield a completely white color, a ratio
    of 0.0 will yield the original color.
    """
def lighten(color: tuple[float, float, float, float], ratio: float = 0.5) -> tuple[float, float, float, float] {
    (red, green, blue, alpha) = color;
    return (
        red + (1.0 - red) * ratio,
        green + (1.0 - green) * ratio,
        blue + (1.0 - blue) * ratio,
        alpha
    );
}

"""Reads keyword arguments from input_dict using type_dict casts."""
def read_kwargs_from_dict(
    input_dict: dict[str, str | int | float],
    type_dict: dict[str, Callable[[str | int | float], str | int | float] | None]
) -> dict[str, str | int | float] {
    kwargs = dict();
    for (key, cast) in type_dict.items() {
        try {
            if cast is None {
                kwargs[key] = input_dict[key];
            } else {
                kwargs[key] = cast(input_dict[key]);
            }
        } except KeyError {
            ;
        }
    }
    return kwargs;
}

"""Assume all questions have at least one answer."""
def computeF1(goldList: list[str], predictedList: list[str]) -> tuple[float, float, float] {
    if len(goldList) == 0 {
        if len(predictedList) == 0 {
            return (1, 1, 1);
        }
        return (0, 0, 0);
    }
    if len(predictedList) == 0 {
        return (0, 1, 0);
    }
    precision = float(sum(1 for entity in predictedList if entity in goldList)) / len(predictedList);
    recall = float(sum(1 for entity in goldList if entity in predictedList)) / len(goldList);
    f1 = 0.0;
    if precision + recall > 0 {
        f1 = (2 * recall * precision) / (precision + recall);
    }
    return (recall, precision, f1);
}

