"""Update upper bound

    Args:
        update_model (bool)      : True : update model.
                                   False: do not update model.
        Ediffs (dict)            : Differences of error
                                   for increasing(or decreasing) upper bound of thresholds
        thresholds (dict)        : Pruning error thresholds
        upper_bound (float)      : Upper bound of 'thresholds'
        scaling_factor (float)   : Scaling factor for 'upper_bound'
        upper_bound_limit (float): upper limit for 'upper_bound'

    Returns:
        upper_bound(float) : Updated upper bound of thresholds
    """
def update_upper_bound(
    update_model: bool,
    Ediffs: dict[object, float],
    thresholds: dict[object, float],
    upper_bound: float,
    scaling_factor: float,
    upper_bound_limit: float
) -> float {
    if update_model {
        Qscale: dict[object, float] = {};
        for k in Ediffs.keys() {
            Qscale[k] = 1 + (Ediffs[k] / thresholds[k]);
            if Qscale[k] == 0 {
                Qscale[k] = 1;
            }
        }
        upper_bound *= max(scaling_factor, min(Qscale.values()));
        upper_bound = min(upper_bound, upper_bound_limit);
    } else {
        Qscale: dict[object, float] = {};
        for k in Ediffs.keys() {
            Qscale[k] = 1 - (Ediffs[k] / thresholds[k]);
        }
        upper_bound *= min(1 / scaling_factor, max(Qscale.values()));
        upper_bound = min(upper_bound, upper_bound_limit);
    }
    return upper_bound;
}

"""
    Simplify a string representation of a circuit.

    The simplified string should evaluate to the same operation label tuple
    as the original.

    Parameters
    ----------
    circuit_str : string
        the string representation of a circuit to be simplified.
        (e.g. "Gx{}", "Gy^1Gx")

    Returns
    -------
    string
        the simplified string representation.
    """
def _simplify_circuit_string(circuit_str: str) -> str {
    s = circuit_str.replace("{}", "");
    s = s.replace("^1G", "G");
    s = s.replace("^1(", "(");
    s = s.replace("^1{", "{");
    if s.endswith("^1") {
        s = s[:-2];
    }
    return s if len(s) > 0 else "{}";
}

"""
Objects that wraps function should provide a "__numba__" magic attribute
that contains a name of an attribute that contains the actual python
function object.
