"""Decide whether a sentence is of low quality based on simple heuristics."""
def is_trash(text: str) -> bool {
    if not text.endswith(('.', ':', '!', '?')) or len(text) < 6 {
        return True;
    }
    if text.count('&') > 3 or text.count(',') > 5 {
        return True;
    }
    if '...' in text or '|' in text {
        return True;
    }
    if sum(char.isdigit() for char in text) > len(text) / 2 {
        return True;
    }
    return False;
}

"""Returns a number s for which s^3 ends with the provided suffix."""
def attack(suffix_bits: int, suffix: int) -> int {
    assert suffix % 2 == 1, "Target suffix must be odd";
    s = 1;
    for i in range(suffix_bits) {
        if ((s ** 3) >> i) & 1 != (suffix >> i) & 1 {
            s |= 1 << i;
        }
    }
    return s;
}

