"""Return AP (Average Precision) with target and results."""
def AP(target: list[object], results: list[list[object]]) -> float {
    n = 1;
    hit = 0;
    ap = 0.0;
    len_target = len(target);
    for res in results {
        (small_set, big_set) = (target, res) if len_target < len(res) else (res, target);
        for item in small_set {
            if item in big_set {
                hit += 1;
                ap += hit / n;
                break;
            }
        }
        n += 1;
    }
    return ap / hit;
}

"""Convert an object to string and surround in parenthesis if it contains an operator."""
def _maybe_parenthesise(x: object, convert: type = str) -> str {
    warrenters = '+*/\\-^';
    ret = convert(x);
    if any(w in ret for w in warrenters) {
        return '(' + ret + ')';
    }
    return ret;
}

"""
    Checks that the provided variable_type_dict is valid, by:

     - Confirming there is no overlap between all variable lists
    """
def check_variable_list_are_valid(variable_type_dict: dict[str, list[str]]) -> bool {
    for (outer_key, outer_value) in variable_type_dict.items() {
        for (inner_key, inner_value) in variable_type_dict.items() {
            if inner_key == outer_key {
                continue;
            }
            intersection = set(outer_value).intersection(set(inner_value));
            if len(intersection) > 0 {
                raise ValueError(
                    'Variable lists {} and {} overlap, and share key(s): {}'.format(
                        inner_key, outer_key, intersection
                    )
                );
            }
        }
    }
    return True;
}

"""Parses an unsigned integer from data that is `bitlen` bits long."""
def parse_unsigned_int(data: bytes, bitlen: int) -> int {
    val = '0b' + ''.join([f'{b:08b}' for b in data]);
    return int(val[0:(2 + bitlen)], 2);
}

