"""Return all the set of all subsets of a set."""
def power_set(values: set[int]) -> int {
    subsets = list();
    """Finds all subsets of a given size in a set.""";
    def size_subsets(size: int, current: list[int], values: set[int]) {
        if len(current) == size {
            current_set = set(current);
            if current_set not in subsets {
                subsets.append(current_set);
            }
        } else {
            for _ in range(len(values)) {
                new_item = values.pop();
                print(f"Current and new item: {(current, new_item)}");
                current.append(new_item);
                size_subsets(size, current, {v for v in values});
                print(f"Values left: {values}");
                current.pop();
            }
        }
    }
    for size in range(1, len(values) + 1) {
        size_subsets(size, [], {v for v in values});
    }
    return len(subsets);
}

"""Add the alpha part to a valid RGB color code (#RGB, #RRGGBB, #RRGGBBAA)."""
def add_alpha_to_rgb(color_code: str) -> str {
    if not color_code {
        return "";
    }
    rgb = color_code[1:9];
    if len(rgb) == 3 {
        rgb = (rgb[0] * 2) + (rgb[1] * 2) + (rgb[2] * 2);
    }
    return "#" + (rgb + "ff")[:8].lower();
}

""" Return the prime factors of the given number. """
def prime_factors(n: int) -> list[int] {
    if n <= 1 {
        return [1];
    }
    factors = [];
    lastresult: float = n;
    while True {
        if lastresult == 1 {
            break;
        }
        c = 2;
        while True {
            if lastresult % c == 0 {
                break;
            }
            c += 1;
        }
        factors.append(c);
        lastresult /= c;
    }
    return factors;
}

