"""Format number to get the human readable presentation of it."""
def human_format(num: int | float) -> str {
    num = float("{:.3g}".format(num));
    magnitude = 0;
    while abs(num) >= 1000 {
        magnitude += 1;
        num /= 1000.0;
    }
    return "{}{}".format(
        "{:f}".format(num).rstrip("0").rstrip("."), ["", "k", "m", "b", "t"][magnitude]
    );
}

"""Reverse a dictionary, swapping keys and values."""
def inverse_dict(my_dict: dict[str, str]) -> dict[str, str] {
    result_dict = {};
    for (key, value) in my_dict.items() {
        if value not in result_dict {
            result_dict[value] = '';
        }
        result_dict[value] = key;
    }
    return result_dict;
}

"""Filter planes by removeDirection and percentile cutoff."""
def filter_planes(feature_dict: dict[str, float], removeDirection: str, percentile: int) -> set[str] {
    planes = list(feature_dict.keys());
    feat_value = [feature_dict[i] for i in planes];
    thresh = min(feat_value) + percentile * (max(feat_value) - min(feat_value));
    if removeDirection == 'Below' {
        keep_planes = [z for z in planes if feature_dict[z] >= thresh];
    } else {
        keep_planes = [z for z in planes if feature_dict[z] <= thresh];
    }
    return set(keep_planes);
}

"""Replace {{keys}} elements in template with the matching value in the kwargs dictionnary"""
def format_template(template: str | None, **kwargs: str | int | float | bool) -> str | None {
    if template is None {
        return None;
    }
    formated = template;
    for key in kwargs {
        replacement = kwargs.get(key, "");
        formated = formated.replace("{{{{{}}}}}".format(key), str(replacement));
    }
    return formated;
}

"""trapez method for numerical integration; same result for n = 10000"""
def trapezoidal(
    f: Callable[[float | int], float | int],
    a: float | int,
    b: float | int,
    n: int = 10000
) -> float {
    s = 0.0;
    h = (b - a) / n;
    for i in range(0, n) {
        s += f(a + (i * h));
    }
    return h * (s + (0.5 * (f(a) + f(b))));
}

