"""Return the hexadecimal figure of `n`."""
def hex_fig(n: int, uppercase: bool = True) -> str {
    assert isinstance(n, int) , `type(n);
    assert 0 <= n < 16;
    assert isinstance(uppercase, bool) , `type(uppercase);
    return str(n) if n < 10 else chr(ord('A' if uppercase else 'a') + n - 10);
}

"""
Calculate list of precision and recall values from lists of true pos.,
false pos., false neg. values.
"""
def calculate_precision_recall(
    tp_totals: list[int], fp_totals: list[int], fn_totals: list[int]
) -> tuple[list[float], list[float]] {
    precision = [
        tp / (tp + fp) if tp + fp > 0 else 0
        for (tp, fp) in zip(tp_totals, fp_totals)
    ];
    recall = [
        tp / (tp + fn) if tp + fn > 0 else 0
        for (tp, fn) in zip(tp_totals, fn_totals)
    ];
    return (precision, recall);
}

"""Returns a len(y) + 1 by len(x) + 1 matrix, where the first row and column
    are filled with 0s and the rest is filled with -1s."""
def _get_edit_distance_matrix(x: str, y: str) -> list[list[int]] {
    matrix = [[-1 for _ in range(len(y) + 1)] for _ in range(len(x) + 1)];
    for j in range(len(matrix[0])) {
        matrix[0][j] = j;
    }
    for (i, _) in enumerate(matrix) {
        matrix[i][0] = i;
    }
    return matrix;
}

