"""
Given an array of integers, return a new array such that each element at index i of
the new array is the product of all the numbers in the original array except the one at i.
Solve it without using division and in O(n).
"""
def coding_problem_02(l: list[int]) -> list[int] {
    forward = [1] * len(l);
    backward = [1] * len(l);
    for idx in range(1, len(l)) {
        forward[idx] = forward[idx - 1] * l[idx - 1];
        backward[-idx - 1] = backward[-idx] * l[-idx];
    }
    return [f * b for (f, b) in zip(forward, backward)];
}

"""
Create a basic sequence with the given pieces.

Keyword arguments:

piece_dict -- The pieces dictionary with the quantity of each piece.
"""
def basic_sequence(piece_dict: dict[str, int]) -> list[str] {
    sequence = [];
    for (piece, number) in piece_dict.items() {
        if number < 1 {
            continue;
        }
        times = ("%s " % piece) * number;
        sequence.extend(times.split());
    }
    return sequence;
}

""" Returns True if the considered string is a valid RIPEMD160 hash. """
def is_hash160(s: str) -> bool {
    if not s or not isinstance(s, str) {
        return False;
    }
    if len(s) != 40 {
        return False;
    }
    for c in s {
        if (
            (c < '0' or c > '9')
            and (c < 'A' or c > 'F')
            and (c < 'a' or c > 'f')
        ) {
            return False;
        }
    }
    return True;
}

"""Computes and returns the elapsed time."""
def timer(start: float, end: float) -> str {
    (hours, rem) = divmod(end - start, 3600);
    (minutes, seconds) = divmod(rem, 60);
    return "{:02}:{:02}:{:05.2f}".format(int(hours), int(minutes), seconds);
}

"""Returns the nth Fibonacci number in the Fibonacci sequence."""
def fibonacci_recursive(number: int) -> int {
    if number in (0, 1) {
        return number;
    }
    return fibonacci_recursive(number - 1) + fibonacci_recursive(number - 2);
}

"""Helper method to process slice keys"""
def _global_to_local_key_slice(
    global_key: slice[int | None],
    globalshape: list[int],
    local_to_global_dict: dict[int, tuple[int, int]] | None,
    axis: int = 0
) -> slice[int | None] {
    if global_key == slice(None) {
        return global_key;
    }
    if local_to_global_dict is None {
        return global_key;
    }
    (global_start, global_stop, global_step) = global_key.indices(globalshape[axis]);
    (global_min, _) = local_to_global_dict[axis];
    global_start = global_start if global_start is not None else 0;
    global_stop = global_stop if global_stop is not None else globalshape[axis];
    local_start = global_start - global_min;
    local_stop = global_stop - global_min;
    return slice(local_start, local_stop, global_step);
}

""" Returns true if the node has connections that skip tiles.

    Most nodes are made up of wires that only touch adjcent tiles.  However
    some nodes fly over tiles.

    """
def weird_nodes(node_name: str) -> bool {
    (_, wire) = node_name.split('/');
    weird_prefixes = [
        'CLK_HROUTE',
        'CLK_HDISTR',
        'CLK_TEST_BUF',
        'CLK_VDISTR',
        'CLK_VROUTE',
        'HDIO_IOBPAIR',
        'HPIO_IOBPAIR',
        'HPIO_IOBSNGL',
        'GND_WIRE',
        'VCC_WIRE'
    ];
    return any(wire.startswith(prefix) for prefix in weird_prefixes);
}

"""Build network URI for NSX Proxy API."""
glob NETWORK_URL = '/network/edges/';
glob GATEWAY_API_URL = '/api/edgeGateway/';
glob GATEWAY_ADMIN_API_URL = '/api/admin/edgeGateway/';

def build_network_url_from_gateway_url(gateway_href: str) -> str | None {
    network_url = gateway_href;
    if gateway_href.find(GATEWAY_API_URL) > 0 or gateway_href.find(GATEWAY_ADMIN_API_URL) > 0 {
        network_url = network_url.replace(GATEWAY_API_URL, NETWORK_URL);
        return network_url.replace(GATEWAY_ADMIN_API_URL, NETWORK_URL);
    }
    return None;
}

