"""Blends a and b with weight alpha in [0, 1]."""
def alpha_blend(a: float, b: float, alpha: float) -> float {
    return b * alpha + (1.0 - alpha) * a;
}

"""Define how many cell switches (DCell) and PODs (FatTree) wil be created on each cluster node or worker."""
def arrayNetworkLength(networkLength: int, clusterNodesLength: int) -> list[float] {
    lengths = [networkLength / clusterNodesLength] * clusterNodesLength;
    rest_network_length = networkLength % clusterNodesLength;
    for i in range(rest_network_length) {
        lengths[i] = lengths[i] + 1;
    }
    return lengths;
}

"""Insertion Sort. Complexity: O(n^2)."""
def insertion_sort(arr: list[int], simulation: bool = False) -> list[int] {
    for i in range(len(arr)) {
        cursor = arr[i];
        pos = i;
        while pos > 0 and arr[pos - 1] > cursor {
            arr[pos] = arr[pos - 1];
            pos = pos - 1;
        }
        arr[pos] = cursor;
    }
    return arr;
}

"""Time Complexity: O(n*k*k). Space Complexity: (n*k)."""
def egg_drop_problem(num_eggs: int, num_floors: int) -> int {
    dp = [[0] * (num_floors + 1) for _ in range(num_eggs + 1)];
    for floor in range(1, num_floors + 1) {
        dp[1][floor] = floor;
    }
    for eggs in range(1, num_eggs + 1) {
        dp[eggs][1] = 1;
    }
    for eggs in range(2, num_eggs + 1) {
        for floor in range(2, num_floors + 1) {
            drops = num_floors;
            for k in range(1, floor) {
                drops = min(drops, 1 + max(dp[eggs - 1][k - 1], dp[eggs][floor - k]));
            }
            dp[eggs][floor] = drops;
        }
    }
    return dp[num_eggs][num_floors];
}

"""Process a text line the pose format."""
def processPoseLine(line: str) -> tuple[float, float, str, float] {
    space_count = 0;
    x = "";
    y = "";
    id = "";
    time_stamp = "";
    for char in line {
        if char == "," {
            char = ".";
        }
        if char == " " {
            space_count += 1;
        } elif space_count == 0 {
            time_stamp += char;
        } elif space_count == 1 {
            x += char;
        } elif space_count == 2 {
            y += char;
        } elif space_count == 7 and char != "\n" {
            id += char;
        }
    }
    return (float(x), float(y), id, float(time_stamp));
}

"""find_lcs"""
def find_lcs(s1: str, s2: str) -> tuple[str, int] {
    m = [[0 for i in range(len(s2) + 1)] for j in range(len(s1) + 1)];
    mmax = 0;
    p = 0;
    for i in range(len(s1)) {
        for j in range(len(s2)) {
            if s1[i] == s2[j] {
                m[i + 1][j + 1] = m[i][j] + 1;
                if m[i + 1][j + 1] > mmax {
                    mmax = m[i + 1][j + 1];
                    p = i + 1;
                }
            }
        }
    }
    return (s1[p - mmax:p], mmax);
}

"""
    Searches through the boards and returns the id of the board if anyone has a full row or a full column.
    If no winner were found, it returns -1.
    """
def check_for_winner(board: list[list[bool]]) -> bool {
    for row in board {
        count = 5;
        for n in row {
            if n is True {
                count -= 1;
            }
        }
        if count < 1 {
            return True;
        }
    }
    for j in range(5) {
        count = 5;
        for k in range(5) {
            if board[k][j] is True {
                count -= 1;
            }
        }
        if count < 1 {
            return True;
        }
    }
    return False;
}

"""Implement the code required to make this function work.

    Write a function `remove_Es` that receives a string and removes all
    the characters `'e'` or `'E'`. Example:

    remove_Es('remoter')  # 'rmotr'
    remove_Es('eEe')      # ''
    remove_Es('abc')      # 'abc'
    """
def remove_Es(a_string: str) -> str {
    return ''.join(char for char in a_string if char not in ('e', 'E'));
}

"""Convert URL und UNC."""
def url_to_unc(url: str) -> str {
    url = url.strip();
    url = url.replace("smb://", "\\\\");
    url = url.replace("file://", "\\\\");
    url = url.replace("/", "\\");
    url = url.replace("%20", " ");
    return url;
}

"""Tests if a hostname is a subdomain of a reference hostname
    e.g. www.domain.com is subdomain of reference
    """
def is_subdomain(domain: str, reference: str) -> bool {
    index_of_reference = domain.find(reference);
    if index_of_reference > 0 and domain[index_of_reference:] == reference {
        return True;
    }
    return False;
}

