}

"""Calculate the address class of the IP address based on bits of binary string."""
def getAddressClass(binaryString: str) -> str {
    addressClass = "";
    if binaryString[0] == "0" {
        addressClass = "A";
    } elif binaryString[0:2] == "10" {
        addressClass = "B";
    } elif binaryString[0:3] == "110" {
        addressClass = "C";
    } elif binaryString[0:4] == "1110" {
        addressClass = "D";
    } elif binaryString[0:4] == "1111" {
        addressClass = "E";
    }
    return addressClass;
}

"""Convert a MAC address to XX:XX:XX:XX:XX:XX format."""
def mac_addr_convert(mac_address: str = "") -> str {
    try {
        mac = mac_address.replace(".", "");
        parts = [mac[i:i + 2].upper() for i in range(0, len(mac), 2)];
        return ":".join(parts);
    } except Exception {
        return mac_address;
    }
}

"""
HSW (Hamaus-Sutter-Wendelt) function for the universal void density profile
See: Hamaus et al. (2014)
"""
def HSW_offset(
    r: float, rs: float, alpha: float, Rv: float, beta: float, deltac: float, offset: float
) -> float {
    numerator = 1 - (r / rs) ** alpha;
    denominator = 1 + (r / Rv) ** beta;
    return deltac * numerator / denominator + offset;
}

"""BizzFuzz template tag."""
def bizz_fuzz(num: int) -> str | int {
    output = '';
    if num % 3 == 0 {
        output += 'Bizz';
    }
    if num % 5 == 0 {
        output += 'Fuzz';
    }
    return output or num;
}

"""A unicode-safe version of urllib2.parse_http_list."""
def parse_http_list(s: str) -> list[str] {
    res = [];
    part = '';
    escape = quote = False;
    for cur in s {
        if escape {
            part += cur;
            escape = False;
            continue;
        }
        if quote {
            if cur == '\\' {
                escape = True;
                continue;
            } elif cur == '"' {
                quote = False;
            }
            part += cur;
            continue;
        }
        if cur == ',' {
            res.append(part);
            part = '';
            continue;
        }
        if cur == '"' {
            quote = True;
        }
        part += cur;
    }
    if part {
        res.append(part);
    }
    return [item.strip() for item in res];
}

"""Change a temp section into its original. If it is its original it will return what was given."""
def temp_to_orig_section(temp_sec: str) -> str {
    section = temp_sec;
    if temp_sec.startswith(('1', '2', '3', '4', '5', '6', '7', '8', '9')) and '~|~' in temp_sec {
        section = temp_sec.split('~|~', 1)[1];
    }
    return section;
}

"""get eculidien distance"""
def distance(x: float, y: float, i: float, j: float) -> float {
    return (x - i) ** 2 + (y - j) ** 2;
}

"""Format time in a human-readable format."""
def get_dhm(timediff: float) -> str {
    d = int(timediff / 86400);
    timediff %= 86400;
    h = int(timediff / 3600);
    timediff %= 3600;
    m = int(timediff / 60);
    return f"{d}`{h:02}:{m:02}";
}

"""Read values from a string."""
def read_values(xs: str, sep: str, *values: str) -> dict[str, int] {
    parts = [x.strip() for x in xs.split(sep)];
    if len(parts) != len(values) {
        raise ValueError(f"Expected {len(values)} values, but got {len(parts)}.");
    }
    return {v: int(x) for (v, x) in zip(values, parts)};
}

"""
Computes and returns the new applicable steps and the no longer
applicable steps from previous and current list of applicable steps.
"""
def compute_applicable_changes(
    previous_applicable_steps: list[str], applicable_steps: list[str]
) -> tuple[list[str], list[str]] {
    return (
        [step for step in applicable_steps if step not in previous_applicable_steps],
        [step for step in previous_applicable_steps if step not in applicable_steps]
    );
}

"""Helper function. Decreases index from cur while condition is satisfied."""
def step_back_while(cur_index: int, condition: Callable[[int], bool]) -> int {
    while cur_index >= 0 and condition(cur_index) {
        cur_index -= 1;
    }
    return cur_index;
}

"""Returns whether a cell is a Markdown cell"""
def is_markdown_cell(cell: dict[str, str]) -> bool {
    return cell["cell_type"] == "markdown";
}

"""Generate a sliding baseline of an iterable."""
def generate_baseline(_iterable: list[int], window_length: int) -> list[list[int]] {
    if len(_iterable) <= window_length {
        return [_iterable];
    }
    num_windows = len(_iterable) - window_length;
    return [
        _iterable[window:(window + window_length + 1)] for window in range(num_windows)
    ];
}

"""Rounds a float value off to the desired precision"""
def _saferound(value: str | int | float, decimal_places: int) -> str {
    try {
        f = float(value);
    } except ValueError {
        return '';
    }
    format = '%%.%df' % decimal_places;
    return format % f;
}

"""Return a number from a string."""
def num_from_str(s: str) -> int | float {
    try {
        return int(s);
    } except ValueError {
        try {
            return float(s);
        } except ValueError {
            raise ValueError(
                ('Can not convert the string "' + s + '" into a numeric value.')
            );
        }
    }
}

"""Normalize value by replacing periods, commas, semi-colons, and colons."""
def normalize(value: str) -> str | None {
    if value {
        return value.replace('.', '').strip(',:/; ');
    }
