"""Fold dict `data`.

Turns dictionary keys, e.g. 'level1/level2/level3', into sub-dicts.
"""
def fold_dict(data: dict[str, object], nb_level: int = (10 ** 5)) -> dict[str, object] {
    if nb_level <= 0 {
        return data;
    }
    groups: dict[str, object] = dict();
    levels = set();
    for (key, value) in data.items() {
        idx = key.find('/');
        if idx > 0 {
            level = key[:idx];
            group_dict = groups.setdefault(level, dict()) as dict[str, object];
            group_dict[key[(idx + 1):]] = value;
            levels.add(level);
        } else {
            groups[key] = value;
        }
    }
    for level in levels {
        groups[level] = fold_dict(groups[level] as dict[str, object], nb_level - 1);
    }
    return groups;
}

"""
    Starting with the number 1 and moving to the right in a clockwise direction a 5 by 5 spiral is formed as follows:
    21 22 23 24 25
    20  7  8  9 10
    19  6  1  2 11
    18  5  4  3 12
    17 16 15 14 13
    It can be verified that the sum of the numbers on the diagonals is 101.
    What is the sum of the numbers on the diagonals in a 1001 by 1001 spiral formed in the same way?
    """
def euler_problem_28(n: int = 1001) -> int {
    def sum_corners(side_length: int) -> int {
        assert side_length % 2 == 1;
        if side_length == 1 {
            return 1;
        }
        return 4 * int((side_length ** 2) * (5 / 8) + ((side_length - 2) ** 2) * (3 / 8));
    }
    total = 0;
    for k in range(1, n + 1, 2) {
        total += sum_corners(k);
    }
    return total;
}

