    for pk in expected_peaks {
        closest_peak = min(observed_peaks, key=lambda (x: float) { abs(x - pk); });
        correspondance[pk] = closest_peak;
    }
    if len(set(correspondance.values())) == len(correspondance.values()) {
        return (True, correspondance);
    } else {
        return (False, None);
    }
}

