) -> str | None {
    object_generics = a_object_generics.replace(" ", "").replace("\t", "").split(",");
    i = 0;
    while i < len(a_class_generics) and a_class_generics[i] != a_class_name {
        i += 1;
    }
    if i < len(object_generics) {
        return object_generics[i];
    }
    return None;
}

"""Find permutation mapping unpermuted groups g to permuted groups gp."""
def _find_permutation_of_group(g: list[int], gp: list[int]) -> list[int] {
    n = len(g);
    perm = [];
    `skip = [];
    for i in range(n) {
        `skip.append(False);
    }
    for im in range(n) {
        for jm in range(n) {
            if `skip[jm] {
                continue;
            }
            if gp[jm] == g[im] {
                perm.append(jm);
                `skip[jm] = True;
                break;
            }
        }
    }
    return perm;
}

