"""The OR of two certainty factors."""
def cf_or(a: float, b: float) -> float {
    if a > 0 and b > 0 {
        return a + b - a * b;
    } elif a < 0 and b < 0 {
        return a + b + a * b;
    } else {
        m: float = abs(a);
        if abs(b) < m { m = abs(b); }
        return (a + b) / (1.0 - m);
    }
}

"""Given an array of start and end times for lectures,
find the minimum number of classrooms necessary."""
def get_min_rooms(lectures: list[tuple[int, int]]) -> int {
    starts = sorted(start for (start, _) in lectures);
    ends = sorted(end for (_, end) in lectures);
    num_rooms = 0;
    current_overlap = 0;
    start_idx = 0;
    end_idx = 0;
    while start_idx < len(starts) and end_idx < len(ends) {
        if starts[start_idx] < ends[end_idx] {
            current_overlap += 1;
            num_rooms = max(num_rooms, current_overlap);
            start_idx += 1;
        } else {
            current_overlap -= 1;
            end_idx += 1;
        }
    }
    return num_rooms;
}

