"""Attempts to take the arguments in arg and kwargs and return only those which can be used
       by the argspec given."""
def conform_to_argspec(
    args: tuple[object, ...],
    kwargs: dict[str, object],
    argspec: tuple[list[str], str | None, str | None, tuple[object, ...] | None]
) -> tuple[list[object], dict[str, object]] {
    (regargs, varargs, varkwargs, defaults) = argspec;
    N = len(regargs);
    newargs = list(args);
    newkwargs = kwargs.copy();
    if varargs is None {
        newargs = newargs[:N];
    }
    for varname in regargs[len(newargs):] {
        try {
            newargs.append(newkwargs[varname]);
            del newkwargs[varname];
        } except KeyError {
            break;
        }
    }
    if varkwargs is None {
        newkwargs = {};
    }
    return (newargs, newkwargs);
}

"""Calculate the total number of direct and indirect orbits in n_orbit_dict."""
def calc_tot_orbits(n_orbit_dict: dict[str, tuple[int, int]]) -> tuple[int, int] {
    n_direct_tot = sum(n_orbits[0] for n_orbits in n_orbit_dict.values());
    n_indirect_tot = sum(n_orbits[1] for n_orbits in n_orbit_dict.values());
    return (n_direct_tot, n_indirect_tot);
}

"""
Return relative degree of transfer function from zeros and poles.

This is simply len(p) - len(z), which must be nonnegative.
A ValueError is raised if len(p) < len(z).
"""
def _relative_degree(z: list[float], p: list[float]) -> int {
    degree = len(p) - len(z);
    if degree < 0 {
        raise ValueError(
            "Improper transfer function. " "Must have at least as many poles as zeros."
        );
    }
    return degree;
}

"""Get stage label."""
def get_stage_list(n_stages: int, stage_ratios: list[float]) -> list[int] {
    if n_stages == 3 {
        return [0, 1, 2];
    }
    stage_values = [];
    stage = 0;
    threshold = stage_ratios[stage] * n_stages;
    for x in range(n_stages) {
        if x >= threshold {
            stage += 1;
            threshold += stage_ratios[stage] * n_stages;
        }
        stage_values.append(stage);
    }
    return stage_values;
}

"""Remove title from text document."""
def remove_possible_title_from_text(
    text: str, title: str, min_title_length: int = 3, overlap_ratio: float = 0.5
) -> str {
    def _high_intersection(s1: set[str], s2: set[str]) -> bool {
        return len(s1.intersection(s2)) > overlap_ratio * len(s2);
    }
    title_tokens = set(title.lower().split(' '));
    if len(title_tokens) < min_title_length or len(text) <= len(title) {
        return text;
    }
    text_beginning_tokens = set(text.lower().split(' '));
    if _high_intersection(text_beginning_tokens, title_tokens) {
        text = text[len(title):];
    }
    return text;
}

"""Convert NLTK POS tags to SentiWordNet's POS tags."""
def convert_postag(pos: str) -> str {
    if pos in ['VB', 'VBD', 'VBG', 'VBN', 'VBP', 'VBZ'] {
        return 'v';
    } elif pos in ['JJ', 'JJR', 'JJS'] {
        return 'a';
    } elif pos in ['RB', 'RBR', 'RBS'] {
        return 'r';
    } elif pos in ['NNS', 'NN', 'NNP', 'NNPS'] {
        return 'n';
    } else {
        return '';
    }
}

