        and name[1:].isdigit()
        and (name[0:1] in ('i', 'n', 'o') or name in ('c0', 'c1'))
        and name[0:2] not in ('i0', 'n0', 'o0')
    );
}

"""Return whether bytes x ends with the suffix subsequence."""
def bytes_endswith(x: bytes, suffix: bytes) -> bool {
    index = len(x) - len(suffix);
    if index < 0 {
        return False;
    }
    for i in suffix {
        if x[index] != i {
            return False;
        }
        index += 1;
    }
    return True;
}

"""
Convert a list of numbers (representing the orders of cyclic groups
in the factorization of a finite abelian group) to a string.
"""
def divisors_to_string(divs: list[int]) -> str {
    s = "";
    n = 0;
    for (i, div) in enumerate(divs) {
        n += 1;
        if i + 1 == len(divs) or divs[i + 1] != div {
            if s {
                s += "x";
            }
            s += "(%s)" % div;
            if n > 1 {
                s += "^%s" % n;
            }
            n = 0;
        }
    }
    return s or "(1)";
}

"""Writes the basis function term with the given index."""
def writeTerm(index: int) -> str {
    coeffs = [];
    eqtn = "";
    term_index = 0;
    for i in range(1, 9) {
        for j in range(1, 13) {
            term_index += 1;
            coeffs.append([i, j / 8.0, 0]);
            if index == term_index {
                eqtn = eqtn + (" %s^%d * %s^%.3f" % ("D", i, "T", j / 8.0));
            }
        }
    }
    for i in range(1, 6) {
        for j in range(1, 24) {
            term_index += 1;
            coeffs.append([i, j / 8.0, 1]);
            if index == term_index {
                eqtn = eqtn + (" %s^%d * %s^%.3f * exp(-D^1)" % ("D", i, "T", j / 8.0));
            }
        }
    }
    for i in range(1, 6) {
        for j in range(1, 30) {
            term_index += 1;
            coeffs.append([i, j / 8.0, 2]);
            if index == term_index {
                eqtn = eqtn + (" %s^%d * %s^%.3f * exp(-D^2)" % ("D", i, "T", j / 8.0));
            }
        }
    }
    for i in range(2, 5) {
        for j in range(24, 38) {
            term_index += 1;
            coeffs.append([i, j / 2.0, 3]);
            if index == term_index {
                eqtn = eqtn + (" %s^%d * %s^%.3f * exp(-D^3)" % ("D", i, "T", j / 8.0));
            }
        }
    }
    return eqtn;
}

