"""Convert a nonnegative integer to an octet string."""
def integer_to_octet_string_primitive(length: int, integer: int) -> bytes {
    if integer >= 256 ** length {
        raise ValueError(f"{integer} >= 256 ** {length}");
    }
    index = 0;
    digits = [0] * length;
    while integer {
        digits[index] = integer % 256;
        integer //= 256;
        index += 1;
    }
    return bytes(reversed(digits));
}

"""Returns the most frequently occurring items in the given list, nums"""
def modes(nums: list[int]) -> list[int] {
    if len(nums) == 0 {
        return [];
    }
    frequencies: dict[int, int] = {};
    for num in nums {
        frequencies[num] = 1 + frequencies.get(num, 0);
    }
    max_occurrences = max(frequencies.values());
    return [num for (num, frequency) in frequencies.items() if frequency == max_occurrences];
}

"""Return True if word not in wordset, nor matched by wildcard.

    Note: accepts a wildcard (default '*') for '0 or more letters'.
    """
def wordinset_wild(word: str, wordset: set[str], wild: str = '*') -> bool {
    if word in wordset {
        return True;
    } else {
        if word[-1] != wild {
            word += wild;
        }
        while len(word) > 2 {
            if word in wordset {
                return True;
            } else {
                word = word[:-2] + wild;
            }
        }
    }
    return False;
}

