"""Find a deployment unit id associated with an ip."""
def find_du_based_on_ip(ip: str, functions: list[dict[str, str | dict[str, str | list[dict[str, str]]]]]) -> tuple[str | None, str | None] {
    for vnf in functions {
        if 'vnfr' not in vnf.keys() {
            continue;
        }
        vnfr = vnf['vnfr'] as dict[str, str | list[dict[str, str]]];
        dus: list[dict[str, str]] = [];
        if 'virtual_deployment_units' in vnfr.keys() {
            dus = vnfr['virtual_deployment_units'] as list[dict[str, str]];
        }
        if 'couldnative_deployment_units' in vnfr.keys() {
            dus = vnfr['cloudnative_deployment_units'] as list[dict[str, str]];
        }
        for du in dus {
            du_string = str(du);
            if ip in du_string {
                return (du['id'], vnf['id'] as str);
            }
        }
    }
    return (None, None);
}

"""Calculates the integration time in seconds."""
def calc_t_int(n_group: int, t_frame: float, n_frame: int, n_skip: int) -> float {
    return ((n_group * (n_frame + n_skip)) - n_skip) * t_frame;
}

"""Find integration error if Simpson method is used."""
def calculate_integration_error(
    max_forth_derivative: float, low: float, high: float, length: int
) -> float {
    step = (high - low) / length;
    return step ** 4 / 180 * max_forth_derivative * (high - low);
}

"""Merges two sorted sublists into a single sorted list."""
def merge(left: list[int], right: list[int]) -> list[int] {
    ret = [];
    li = ri = 0;
    while li < len(left) and ri < len(right) {
        if left[li] <= right[ri] {
            ret.append(left[li]);
            li += 1;
        } else {
            ret.append(right[ri]);
            ri += 1;
        }
    }
    if li == len(left) {
        ret.extend(right[ri:]);
    } else {
        ret.extend(left[li:]);
    }
    return ret;
}

"""Return substring between 'first' and 'last'."""
def find_between(string: str, first: str, last: str) -> str {
    try {
        start = string.index(first) + len(first);
        end = string.index(last, start);
        return string[start:end];
    } except ValueError {
        return "";
    }
}

"""Merges two sorted lists into a single sorted list.

Returns new list. lst1 and lst2 are destroyed in the process."""
def merge(lst1: list[int], lst2: list[int]) -> list[int] {
    result = [];
    while lst1 or lst2 {
        if not lst1 {
            return result + lst2;
        } elif not lst2 {
            return result + lst1;
        }
        if lst1[0] < lst2[0] {
            result.append(lst1.pop(0));
        } else {
            result.append(lst2.pop(0));
        }
    }
    return result;
}

"""parse an optional string"""
def parse_optionalString(value: str | None) -> str | None {
