}

"""A dict to show the new, changed and removed attributes between two states."""
def _state_diff(state: dict[str, str | int | float | bool | None], previous_state: dict[str, str | int | float | bool | None]) -> dict[str, dict[str, str | int | float | bool | None] | dict[str, dict[str, str | int | float | bool | None]]] | None {
    new = {k: v for (k, v) in state.items() if k not in previous_state};
    changed = {
        k: {"from": previous_state[k], "to": v}
        for (k, v) in state.items()
        if k in previous_state and v != previous_state[k]
    };
    removed = {k: v for (k, v) in previous_state.items() if k not in state};
    diff = {"new": new, "changed": changed, "removed": removed};
    result = {k: v for (k, v) in diff.items() if len(v) > 0};
    return result if len(result) > 0 else None;
}

"""Calculate mean of a sequence; return empty if the sequence is empty."""
def mean(values: Iterable[float], empty: float = 0) -> float {
    (n, mean_val) = (0, 0.0);
    for value in values {
        n += 1;
        mean_val += (value - mean_val) / n;
    }
    return mean_val if n > 0 else empty;
}

"""Find UTM zone for lon and lat values."""
