"""Multiply two matrices."""
def multiply(m1: list[list[int]], m2: list[list[int]]) -> tuple[tuple[int, ...], ...] {
    m1_rows = len(m1);
    m1_cols = len(m1[0]);
    m2_cols = len(m2[0]);
    assert m1_cols == len(m2), "Matrix multiplication not defined. Invalid dimensions.";
    new_rows = [];
    for i in range(m1_rows) {
        new_row = [];
        for k in range(m2_cols) {
            val = 0;
            for j in range(m1_cols) {
                val = val + m1[i][j] * m2[j][k];
            }
            new_row.append(val);
        }
        new_rows.append(tuple(new_row));
    }
    return tuple(new_rows);
}

"""
Get the bracket depth of index idx.

Raises ValueError if idx is not inside any bracket.
"""
def get_bracket_depth(
    idx: int,
    left_bracket_indices: list[int],
    right_bracket_indices: list[int]
) -> int {
    depth = -1;
    for (i, left_idx) in enumerate(left_bracket_indices) {
        if idx >= left_idx and idx <= right_bracket_indices[i] {
            depth += 1;
        }
    }
    if depth < 0 {
        raise ValueError("cannot find bracket depth");
    }
    return depth;
}

