"""
Precipitation routine of the HBV96 model.

If temperature is lower than TT [degree C], all precipitation is snow;
otherwise it is rainfall.
"""
def Precipitation(prec: float, temp: float, tt: float, rfcf: float, sfcf: float) -> tuple[float, float] {
