}

"""Add github-style ToC to start of md content."""
def add_toc(txt: str) -> str {
    lines = txt.split('\n');
    toc_lines = [];
    mindepth = None;
    for line in lines {
        if not line.startswith('#') {
            continue;
        }
        parts = line.split();
        hashblock = parts[0];
        if set(hashblock) != set(["#"]) {
            continue;
        }
        depth = len(hashblock);
        if mindepth is None {
            mindepth = depth;
        }
        depth -= mindepth;
        toc_lines.append(
            "%s- [%s](#%s)" % (
                ' ' * 4 * depth,
                ' '.join(parts[1:]),
                '-'.join(x.lower() for x in parts[1:])
            )
        );
    }
    if not toc_lines {
        return txt;
    }
    return '\n'.join(toc_lines) + "\n\n" + txt;
}

