    for (i, txt) in enumerate(text) {
        for word in words {
            if word in txt {
                total[i] = total[i] + 1;
            }
        }
    }
    return total;
}

"""
    Computes the size of the interval between points in a multiplot.
    """
def _multiplot_interval(from_date: float, to_date: float, points: int) -> float {
    if points < 2 {
        return 0.0;
    }
