"""Converts the input string from PascalCase to snake_case."""
def pascal_case_to_snake_case(input_string: str) -> str {
    output_list: list[str] = [];
    for (i, char) in enumerate(input_string) {
        if char.capitalize() == char {
            if i == 0 {
                output_list.append(char.lower() as str);
            } else {
                output_list.append('_');
                output_list.append(char.lower() as str);
            }
        } else {
            output_list.append(char);
        }
    }
    return ''.join(output_list);
}

"""Computes micro-average over @elems."""
def micro(S: dict[str, float], C: dict[str, float], T: dict[str, float]) -> tuple[float, float, float] {
    s_total = sum(S.values());
    c_total = sum(C.values());
    t_total = sum(T.values());
    P = c_total / s_total if s_total > 0.0 else 0.0;
    R = c_total / t_total if t_total > 0.0 else 0.0;
    F1 = 2 * P * R / (P + R) if c_total > 0.0 else 0.0;
    return (P, R, F1);
}

"""Split stream paths into worker batches by relative size."""
def split_dataset_sizes(stream_list: list[str], split_sizes: list[int]) -> list[list[str]] {
    out = [];
    start = 0;
    total = sum(split_sizes);
    for split_size in split_sizes[:-1] {
        num = int(split_size / total * len(stream_list));
        end = start + num;
        out.append(stream_list[start:end]);
        start = end;
    }
    out.append(stream_list[start:]);
    return out;
}

"""Process metadata arguments into a field-to-value dict."""
def clean_meta_args(args: Iterable[str]) -> dict[str, str] {
    results = {};
    for arg in args {
        parts = [x.strip() for x in arg.split("=", 1)];
        if len(parts) == 2 {
            if not parts[0] {
                raise ValueError("Empty field name");
            }
            (field, value) = parts;
        } else {
            raise ValueError("meta argument isn't in 'field=value' format");
        }
        if not value {
            continue;
        }
        results[field] = value;
    }
    return results;
}

