def build_tags_filter(tags: list[dict[str, str | list[str]]] | dict[str, str | list[str]]) -> list[dict[str, str | list[str]]] {
    filters = [];
    assert isinstance(tags, (list, dict)), 'tags must be either list or dict.';
    if isinstance(tags, list) {
        tags_dict = {tag['name']: tag['value'] for tag in tags};
    } else {
        tags_dict = tags;
    }
    for (name, raw_values) in tags_dict.items() {
        values = [raw_values] if isinstance(raw_values, str) else raw_values;
