    raw = gav.split(':');
    if len(raw) != 3 {
        raise ValueError(f"Not a valid GAV pattern: {gav}");
    }
    parts: list[str | None] = [];
    for (index, value) in enumerate(raw) {
        parts.append(defaults[index] if len(value) == 0 else value);
    }
    return tuple(parts);
}

