    for (i, num) in enumerate(nums) {
        pair = target - num;
        if pair in index_map {
            return [index_map[pair], i];
        }
        index_map[num] = i;
    }
    return None;
}

"""List of N-1 ratios from N proportions."""
def _unpack_proportions(values: list[float]) -> list[float] {
    if len(values) == 1 {
        return [];
    }
    half = len(values) // 2;
    (num, denom) = (sum(values[half:]), sum(values[:half]));
    assert num > 0 and denom > 0;
    ratio = num / denom;
    return [ratio] + _unpack_proportions(values[:half]) + _unpack_proportions(values[half:]);
}

"""Returns (g, a, b) such that g = gcd(x, y) = ax + by"""
def ext_euclid(x: int, y: int) -> tuple[int, int, int] {
    if y == 0 {
        return (x, 1, 0);
    }
    (g, a1, b1) = ext_euclid(y, x % y);
    return (g, b1, a1 - (x // y) * b1);
}

