    s = "";
    for (k1, d2) in ddic.items() {
        if s {
            s += " ";
        }
        s += "%s" % k1;
        s2 = "";
        for (k2, v2) in d2.items() {
            if s2 {
                s2 += " ";
            }
            s2 += "%s:%s;" % (k2, v2);
        }
        s += " {%s}" % s2;
    }
    return s;
}

