"""Clip the command with clip_ros_tolerance when close enough to valid ranges."""
def bound_ros_command(
    bounds: list[float],
    ros_pos: float,
    fail_out_of_range_goal: bool,
    clip_ros_tolerance: float = 0.001
) -> float | None {
    if ros_pos < bounds[0] {
        if fail_out_of_range_goal {
            return bounds[0] if bounds[0] - ros_pos < clip_ros_tolerance else None;
        } else {
            return bounds[0];
        }
    }
    if ros_pos > bounds[1] {
        if fail_out_of_range_goal {
            return bounds[1] if ros_pos - bounds[1] < clip_ros_tolerance else None;
        } else {
            return bounds[1];
        }
    }
    return ros_pos;
}

"""Return the dot product of vecA and vecB."""
