"""Determine whether brackets, braces, and parentheses are valid."""
def valid_parentheses_brackets(input_string: str) -> bool {
    open_stack: list[str] = [];
    map_close_to_open: dict[str, str] = {')': '(', '}': '{', ']': '['};
    for character in input_string {
        if character in map_close_to_open {
            if not open_stack or open_stack.pop() != map_close_to_open[character] {
                return False;
            }
        } else {
            open_stack.append(character);
        }
    }
    return not open_stack;
}

"""Insert '.thumb' into an image filename or URL."""
