"""
We can either take or leave the current number depending on previous max number
"""
def max_sum_naive(arr: list[int], length: int, index: int, prev_max: int) -> int {
    if index >= length {
        return 0;
    }
    cur_max = 0;
    if arr[index] > prev_max {
        cur_max = arr[index] + max_sum_naive(arr, length, index + 1, arr[index]);
    }
    return max(cur_max, max_sum_naive(arr, length, index + 1, prev_max));
}

"""Pearson Correlation Coefficient for 2 vectors
    """
def pcc_vector(v1: list[float], v2: list[float]) -> float | None {
    if len(v1) != len(v2) {
        return None;
    }
    avg1 = sum(v1) / len(v1);
    avg2 = sum(v2) / len(v2);
    dxy = [(v1[i] - avg1) * (v2[i] - avg2) for i in range(len(v1))];
    dx2 = [(v1[i] - avg1) ** 2 for i in range(len(v1))];
    dy2 = [(v2[i] - avg2) ** 2 for i in range(len(v1))];
    return sum(dxy) / (sum(dx2) * sum(dy2)) ** 0.5;
}

"""Computes absolute length difference between target and predicted sequences."""
def abs_length_diff(trg: str, pred: str) -> int {
    trg_length = len(trg.split(' '));
    pred_length = len(pred.split(' '));
    return abs(trg_length - pred_length);
}

"""Auxiliary function to sort the contributions for the compare_plot.
Returns the value of the maximum difference between values in contributions[0]."""
def maximum_difference_sort_value(contributions: list[list[float]]) -> float {
    vals = contributions[0];
    if len(vals) <= 1 {
        return vals[0];
    }
    return max([
        abs(contrib_i - contrib_j)
        for (i, contrib_i) in enumerate(vals)
        for (j, contrib_j) in enumerate(vals)
        if i <= j
    ]);
}

"""Based on project: https://github.com/chaeplin/dashmnb."""
def from_string_to_bytes(a: str | bytes) -> bytes {
