}

"""Recursively merge other into base; nested dict values merge in place."""
def merge_dict_recursive(base: dict[str, int | dict], other: dict[str, int | dict]) -> dict[str, int | dict] {
    for (key, value) in list(other.items()) {
        if isinstance(value, dict) and key in base and isinstance(base[key], dict) {
            base[key] = merge_dict_recursive(base[key], value);
        } else {
            base[key] = value;
        }
    }
    return base;
}

"""It returns given vocal with grave or acute accent"""
def getAccentedVocal(vocal: str, acc_type: str = "g") -> str {
