}

"""
>>> format_len('abc')
3
>>> format_len(('(', ('(', 'def', ')'), 'yz', ')'))
11
"""
def format_len(x: str | list | tuple) -> int {
    if not isinstance(x, (list, tuple)) {
        return len(x);
    }
    sep_len = 2 * (len(x) - 3) if len(x) > 3 else 0;
    return sum(map(format_len, x)) + sep_len;
}

"""Return the genome directory name from infra_id and optional arguments."""
def get_genome_dir(
    infra_id: str | int,
    genver: str | int | None = None,
    annver: str | int | None = None,
    key: str | int | None = None
) -> str {
    dirname = f"{infra_id}";
    if genver is not None {
        dirname += f".gnm{genver}";
    }
    if annver is not None {
        dirname += f".ann{annver}";
    }
    if key is not None {
        dirname += f".{key}";
    }
    return dirname;
}

"""Converts a potentially big number into a lisible string.

Example:
- big_number(10000000) returns '10 000 000'.
"""
def big_number(int_in: int) -> str {
    s = str(int_in);
    position = len(s);
    counter = 0;
    out = '';
    while position != 0 {
        counter += 1;
        position -= 1;
        out = s[position] + out;
        if counter % 3 == 0 and position != 0 {
            out = " " + out;
        }
    }
    return out;
}

"""Returns the Hamming Distance of Two Equal Strings."""
def hamming_distance(lhs: str, rhs: str) -> int {
    return sum(x != y for (x, y) in zip(lhs, rhs));
}

