"""Returns a copy of the given board_state with the desired move applied."""
def apply_move(
    board_state: tuple[tuple[int, int, int], tuple[int, int, int], tuple[int, int, int]],
    move: tuple[int, int],
    side: int
) -> tuple[tuple[int, int, int], tuple[int, int, int], tuple[int, int, int]] {
    (move_x, move_y) = move;
    rows: list[tuple[int, int, int]] = [];
    for x in range(3) {
        if move_x == x {
            temp = list(board_state[x]);
            temp[move_y] = side;
            rows.append(tuple(temp));
        } else {
            rows.append(board_state[x]);
        }
    }
    return tuple(rows);
}

"""This gets the time in hours, mins and seconds."""
def spltime(tseconds: int) -> tuple[int, int, int] {
    hours = tseconds // 3600;
    minutes = int(tseconds / 60) % 60;
    seconds = tseconds % 60;
    return (hours, minutes, seconds);
}

"""Create frequent candidate 1-itemset C1 by scanning data set."""
def create_C1(data_set: list[list[object]]) -> set[frozenset[object]] {
    C1 = set();
    for t in data_set {
        for item in t {
            item_set = frozenset([item]);
            C1.add(item_set);
        }
    }
    return C1;
}

"""Get the experiment type from the filename (timestamp removed)."""
def get_experiment_type(filename: str) -> str {
    file_type = '';
    filename = filename.split('/')[-1];
    elements = filename.split('_');
    for i in range(len(elements) - 3) {
        file_type += '{}_'.format(elements[i]);
    }
    return file_type[:-1];
}

