"""Lookup package licenses"""
def bulk_lookup(license_dict: dict[str, str], pkg_list: list[dict[str, str | list[str] | None]]) -> dict[str, list[str]] {
    pkg_licenses: dict[str, list[str]] = {};
    for pkg in pkg_list {
        if not pkg.get("name") or not pkg.get("version") {
            continue;
        }
        pkg_key = (pkg["name"] as str) + "@" + (pkg["version"] as str);
        if pkg.get("vendor") {
            pkg_key = (pkg.get("vendor") as str) + ":" + (pkg["name"] as str) + "@" + (pkg["version"] as str);
        }
        for lic in (pkg.get("licenses") as list[str]) {
            if lic == "X11" {
                lic = "MIT";
            } elif "MIT" in lic {
                lic = "MIT";
            }
            curr_list = pkg_licenses.get(pkg_key, []);
            match_lic = license_dict.get(lic);
            if match_lic {
                curr_list.append(match_lic);
            }
            pkg_licenses[pkg_key] = curr_list;
        }
    }
    return pkg_licenses;
}

"""Compute a, b such that a*m + b*n = gcd(m, n) via Extended Euclidean algorithm."""
def eea(m: int, n: int) -> tuple[int, int] {
    (p, q, r, s) = (1, 0, 0, 1);
    while n != 0 {
        k = m // n;
        (m, n, p, q, r, s) = (n, m - k * n, q, p - k * q, s, r - k * s);
    }
    return (p, r);
}

"""Helper to dynamically instantiate a class from a name."""
def instantiate[T](class_name: str, *args: tuple, **kwargs: dict) -> T {
    split_name = class_name.split(".");
    module_name = split_name[0];
    class_name = ".".join(split_name[1:]);
    module = __import__(module_name);
    class_ = getattr(module, class_name);
    return class_(*args, **kwargs);
}

"""Return the bounding vertices of the texture square."""
def tex_coord(x: int | float, y: int | float, n: int | float = 8) -> tuple[float, float, float, float, float, float, float, float] {
    m = 1.0 / n;
    dx = x * m;
    dy = y * m;
    return (dx, dy, dx + m, dy, dx + m, dy + m, dx, dy + m);
}

"""Perform regular simple expression matching."""
def isMatch(s: str, p: str) -> bool {
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)];
    dp[0][0] = True;
    for ii in range(1, len(p)) {
        if p[ii] == "*" and dp[0][ii - 1] {
            dp[0][ii + 1] = True;
        }
    }
    for ii in range(len(s)) {
        for jj in range(len(p)) {
            if p[jj] in {s[ii], '.'} {
                dp[ii + 1][jj + 1] = dp[ii][jj];
            } elif p[jj] == '*' {
                if p[jj - 1] not in {s[ii], '.'} {
                    dp[ii + 1][jj + 1] = dp[ii + 1][jj - 1];
                } else {
                    dp[ii + 1][jj + 1] = (
                        dp[ii][jj + 1] or dp[ii + 1][jj] or dp[ii + 1][jj - 1]
                    );
                }
            }
        }
    }
    return dp[-1][-1];
}

"""Flattens a 2d array 'matrix' to an array."""
def Flatten(matrix: list[list[int]]) -> list[int] {
    return [item for row in matrix for item in row];
}

"""Truncate a string to a specified maximum length."""
def truncate_string(string: str, max_length: int) -> str {
    if len(string) <= max_length {
        return string;
    }
    return string[:max_length];
}
